import type { BankQuestion } from "@/lib/bank";

/** Fundamental Rights (Indian Polity): 222 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"polity-fundamental-rights-1","question":"Fundamental Rights are contained in which Part of the Constitution?","options":["Part II","Part III","Part IV","Part IVA"],"answer":1,"explanation":"Part III (Articles 12–35) contains the Fundamental Rights. Part II is Citizenship, Part IV the Directive Principles and Part IVA the Fundamental Duties added in 1976.","difficulty":"easy","questionHi":"मौलिक अधिकार संविधान के किस भाग में हैं?","optionsHi":["भाग II","भाग III","भाग IV","भाग IVA"],"explanationHi":"भाग III (अनुच्छेद 12–35) में मौलिक अधिकार हैं। भाग II नागरिकता है, भाग IV नीति निदेशक तत्व और भाग IVA 1976 में जोड़े गए मौलिक कर्तव्य।"},
  {"id":"polity-fundamental-rights-2","question":"How many Fundamental Rights does the Constitution guarantee today?","options":["5","6","7","11"],"answer":1,"explanation":"Six: equality, freedom, against exploitation, religion, cultural and educational, and constitutional remedies. The trap is 7, the original count before the 44th Amendment (1978) removed the Right to Property; 11 is the number of Fundamental Duties and 5 the number of writs.","difficulty":"easy","questionHi":"आज संविधान कितने मौलिक अधिकारों की गारंटी देता है?","optionsHi":["5","6","7","11"],"explanationHi":"छह: समता, स्वातंत्र्य, शोषण के विरुद्ध, धर्म, संस्कृति और शिक्षा संबंधी, तथा संवैधानिक उपचारों का अधिकार। भ्रम की जड़ 7 है, जो 44वें संशोधन (1978) द्वारा संपत्ति का अधिकार हटाए जाने से पहले की मूल संख्या थी; 11 मौलिक कर्तव्यों की संख्या है और 5 रिटों की संख्या।"},
  {"id":"polity-fundamental-rights-3","question":"Dr. B. R. Ambedkar described which Article as the “heart and soul” of the Constitution?","options":["Article 19","Article 21","Article 32","Article 368"],"answer":2,"explanation":"Article 32 (Right to Constitutional Remedies) lets citizens move the Supreme Court directly to enforce Fundamental Rights.","difficulty":"moderate","questionHi":"डॉ. बी. आर. अंबेडकर ने किस अनुच्छेद को संविधान की “हृदय और आत्मा” कहा?","optionsHi":["अनुच्छेद 19","अनुच्छेद 21","अनुच्छेद 32","अनुच्छेद 368"],"explanationHi":"अनुच्छेद 32 (संवैधानिक उपचारों का अधिकार) नागरिकों को मौलिक अधिकारों के प्रवर्तन के लिए सीधे सर्वोच्च न्यायालय जाने देता है।"},
  {"id":"polity-fundamental-rights-4","question":"The Right to Education (Article 21A) was inserted by which Amendment?","options":["73rd Amendment","74th Amendment","86th Amendment","93rd Amendment"],"answer":2,"explanation":"The 86th Amendment Act, 2002 inserted Article 21A for free and compulsory education for children aged 6–14.","difficulty":"moderate","questionHi":"शिक्षा का अधिकार (अनुच्छेद 21A) किस संशोधन द्वारा जोड़ा गया?","optionsHi":["73वाँ संशोधन","74वाँ संशोधन","86वाँ संशोधन","93वाँ संशोधन"],"explanationHi":"86वें संशोधन अधिनियम, 2002 ने 6–14 वर्ष के बच्चों की निःशुल्क और अनिवार्य शिक्षा के लिए अनुच्छेद 21A जोड़ा।"},
  {"id":"polity-fundamental-rights-5","question":"Fundamental Rights in the Indian Constitution were borrowed from the Constitution of:","options":["UK","USA","Ireland","Canada"],"answer":1,"explanation":"The justiciable Bill of Rights idea came from the US Constitution. Ireland gave India the Directive Principles, the UK parliamentary government and Canada the federation with a strong Centre, so those are the tempting mix-ups.","difficulty":"moderate","questionHi":"भारतीय संविधान के मौलिक अधिकार किस देश के संविधान से लिए गए हैं?","optionsHi":["ब्रिटेन","अमेरिका","आयरलैंड","कनाडा"],"explanationHi":"न्यायोचित अधिकार-पत्र (Bill of Rights) का विचार अमेरिका के संविधान से आया। आयरलैंड ने भारत को नीति निदेशक तत्व, ब्रिटेन ने संसदीय शासन और कनाडा ने सशक्त केंद्र वाला संघ दिया, इसलिए ये भ्रमित करने वाले विकल्प हैं।"},
  {"id":"polity-fundamental-rights-6","question":"The Right to Property was removed from the list of Fundamental Rights by the:","options":["42nd Amendment","44th Amendment","52nd Amendment","86th Amendment"],"answer":1,"explanation":"The 44th Amendment (1978) removed it; it is now a constitutional legal right under Article 300A.","difficulty":"hard","questionHi":"संपत्ति का अधिकार मौलिक अधिकारों की सूची से किसके द्वारा हटाया गया?","optionsHi":["42वाँ संशोधन","44वाँ संशोधन","52वाँ संशोधन","86वाँ संशोधन"],"explanationHi":"44वें संशोधन (1978) ने इसे हटाया; अब यह अनुच्छेद 300A के अंतर्गत संवैधानिक विधिक अधिकार है।"},
  {"id":"polity-fundamental-rights-7","question":"Which writ directs a public official to perform a duty they have failed to perform?","options":["Habeas Corpus","Mandamus","Certiorari","Quo Warranto"],"answer":1,"explanation":"Mandamus (“we command”) orders a public authority to do its duty.","difficulty":"hard","questionHi":"कौन-सी रिट किसी लोक अधिकारी को वह कर्तव्य निभाने का निर्देश देती है जिसे निभाने में वह विफल रहा है?","optionsHi":["बंदी प्रत्यक्षीकरण","परमादेश","उत्प्रेषण","अधिकार पृच्छा"],"explanationHi":"परमादेश (Mandamus, “हम आदेश देते हैं”) किसी लोक प्राधिकारी को अपना कर्तव्य निभाने का आदेश देता है।"},
  {"id":"polity-fundamental-rights-8","question":"The writ of Quo Warranto is issued to:","options":["Order the release of a person from unlawful detention","Test a person's legal claim to hold a public office","Quash an order already passed by an inferior court","Stop an inferior court from exceeding its jurisdiction"],"answer":1,"explanation":"Quo Warranto (“by what authority”) challenges a person’s claim to a public office.","difficulty":"hard","questionHi":"अधिकार पृच्छा (Quo Warranto) रिट किसलिए जारी की जाती है?","optionsHi":["किसी व्यक्ति को अवैध निरोध से मुक्त करने का आदेश देने के लिए","किसी व्यक्ति के लोक पद धारण करने के कानूनी दावे की जाँच के लिए","अधीनस्थ न्यायालय द्वारा पहले ही पारित आदेश को रद्द करने के लिए","अधीनस्थ न्यायालय को अपनी अधिकारिता से बाहर जाने से रोकने के लिए"],"explanationHi":"अधिकार पृच्छा (Quo Warranto, “किस अधिकार से”) किसी व्यक्ति के लोक पद के दावे को चुनौती देती है।"},
  {"id":"polity-fundamental-rights-9","question":"Which Fundamental Right is available to citizens only, not to foreigners?","options":["Article 14","Article 19","Article 21","Article 25"],"answer":1,"explanation":"Article 19 (six freedoms) is for citizens only; Articles 14, 21 and 25 apply to all persons.","difficulty":"very-hard","questionHi":"कौन-सा मौलिक अधिकार केवल नागरिकों को उपलब्ध है, विदेशियों को नहीं?","optionsHi":["अनुच्छेद 14","अनुच्छेद 19","अनुच्छेद 21","अनुच्छेद 25"],"explanationHi":"अनुच्छेद 19 (छह स्वतंत्रताएँ) केवल नागरिकों के लिए है; अनुच्छेद 14, 21 और 25 सभी व्यक्तियों पर लागू होते हैं।"},
  {"id":"polity-fundamental-rights-10","question":"Which Fundamental Rights cannot be suspended even during a National Emergency?","options":["Articles 14 and 19","Articles 19 and 32","Articles 20 and 21","Articles 25 and 26"],"answer":2,"explanation":"After the 44th Amendment, Articles 20 and 21 cannot be suspended under Article 359.","difficulty":"very-hard","questionHi":"राष्ट्रीय आपातकाल के दौरान भी कौन-से मौलिक अधिकार निलंबित नहीं किए जा सकते?","optionsHi":["अनुच्छेद 14 और 19","अनुच्छेद 19 और 32","अनुच्छेद 20 और 21","अनुच्छेद 25 और 26"],"explanationHi":"44वें संशोधन के बाद अनुच्छेद 20 और 21 को अनुच्छेद 359 के अंतर्गत निलंबित नहीं किया जा सकता।"},
  {"id":"polity-fundamental-rights-11","question":"Under which Article can Parliament restrict the Fundamental Rights of members of the armed forces?","options":["Article 33","Article 34","Article 35","Article 31"],"answer":0,"explanation":"Article 33 empowers Parliament to modify Fundamental Rights for armed forces, police and intelligence agencies.","difficulty":"very-hard","questionHi":"किस अनुच्छेद के अंतर्गत संसद सशस्त्र बलों के सदस्यों के मौलिक अधिकारों को प्रतिबंधित कर सकती है?","optionsHi":["अनुच्छेद 33","अनुच्छेद 34","अनुच्छेद 35","अनुच्छेद 31"],"explanationHi":"अनुच्छेद 33 संसद को सशस्त्र बलों, पुलिस और खुफिया एजेंसियों के लिए मौलिक अधिकारों में संशोधन करने का अधिकार देता है।"},
  {"id":"polity-fundamental-rights-12","question":"Which Article of the Constitution abolishes untouchability?","options":["Article 14","Article 15","Article 17","Article 21"],"answer":2,"explanation":"Article 17 abolishes untouchability and forbids its practice in any form.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"संविधान का कौन-सा अनुच्छेद अस्पृश्यता का अंत करता है?","optionsHi":["अनुच्छेद 14","अनुच्छेद 15","अनुच्छेद 17","अनुच्छेद 21"],"explanationHi":"अनुच्छेद 17 अस्पृश्यता का अंत करता है और किसी भी रूप में इसके आचरण को वर्जित करता है।"},
  {"id":"polity-fundamental-rights-13","question":"Which Article is called the “heart and soul of the Constitution” (right to constitutional remedies)?","options":["Article 19","Article 21","Article 32","Article 226"],"answer":2,"explanation":"Ambedkar called Article 32 the heart and soul of the Constitution.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"कौन-सा अनुच्छेद “संविधान की हृदय और आत्मा” (संवैधानिक उपचारों का अधिकार) कहलाता है?","optionsHi":["अनुच्छेद 19","अनुच्छेद 21","अनुच्छेद 32","अनुच्छेद 226"],"explanationHi":"अंबेडकर ने अनुच्छेद 32 को संविधान की हृदय और आत्मा कहा।"},
  {"id":"polity-fundamental-rights-14","question":"The writ issued to a person holding a public office to show by what authority they hold it is:","options":["Habeas corpus","Mandamus","Certiorari","Quo warranto"],"answer":3,"explanation":"Quo warranto means “by what warrant”: it asks the holder of a substantive public office to show his legal authority. Mandamus commands a public duty to be performed, and certiorari quashes an order already made, so neither tests title to an office.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"लोक पद धारण करने वाले व्यक्ति से यह दिखाने को कहने वाली रिट कि वह किस अधिकार से वह पद धारण करता है, कौन-सी है?","optionsHi":["बंदी प्रत्यक्षीकरण","परमादेश","उत्प्रेषण","अधिकार पृच्छा"],"explanationHi":"अधिकार पृच्छा का अर्थ है “किस वारंट से”: यह किसी सारवान लोक पद के धारक से अपना वैध अधिकार दिखाने को कहती है। परमादेश लोक कर्तव्य निभाने का आदेश देता है और उत्प्रेषण पहले से पारित आदेश को रद्द करता है, इसलिए दोनों में से कोई पद के स्वत्व की जाँच नहीं करता।"},
  {"id":"polity-fundamental-rights-15","question":"The right to property was removed from the Fundamental Rights by the 44th Amendment and placed as a legal right under:","options":["Article 19(1)(f)","Article 31","Article 300A","Article 350"],"answer":2,"explanation":"Since 1978 Article 300A protects property as a constitutional, not fundamental, right.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"संपत्ति का अधिकार 44वें संशोधन द्वारा मौलिक अधिकारों से हटाकर किस अनुच्छेद के अंतर्गत विधिक अधिकार के रूप में रखा गया?","optionsHi":["अनुच्छेद 19(1)(f)","अनुच्छेद 31","अनुच्छेद 300A","अनुच्छेद 350"],"explanationHi":"1978 से अनुच्छेद 300A संपत्ति को मौलिक नहीं बल्कि संवैधानिक अधिकार के रूप में संरक्षित करता है।"},
  {"id":"polity-fundamental-rights-16","question":"Consider: 1. Article 15 is available only to citizens. 2. Article 21 is available to citizens and foreigners. 3. Article 19 is suspended automatically during an emergency declared on the ground of war or external aggression. Which are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct. Since the 44th Amendment, Article 358 suspends Article 19 only for war or external aggression, not armed rebellion.","difficulty":"hard","questionHi":"विचार कीजिए: 1. अनुच्छेद 15 केवल नागरिकों को उपलब्ध है। 2. अनुच्छेद 21 नागरिकों और विदेशियों को उपलब्ध है। 3. युद्ध या बाह्य आक्रमण के आधार पर घोषित आपातकाल के दौरान अनुच्छेद 19 स्वतः निलंबित हो जाता है। कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"तीनों सही हैं। 44वें संशोधन के बाद अनुच्छेद 358 अनुच्छेद 19 को केवल युद्ध या बाह्य आक्रमण पर निलंबित करता है, सशस्त्र विद्रोह पर नहीं।"},
  {"id":"polity-fundamental-rights-17","question":"Employment of children below 14 years in factories, mines or other hazardous work is prohibited by:","options":["Article 21A","Article 23","Article 24","Article 39"],"answer":2,"explanation":"Article 24 bans child labour in hazardous jobs; Article 23 bans forced labour and trafficking.","difficulty":"hard","questionHi":"14 वर्ष से कम आयु के बच्चों को कारखानों, खानों या अन्य खतरनाक कार्य में नियोजित करना किसके द्वारा प्रतिषिद्ध है?","optionsHi":["अनुच्छेद 21A","अनुच्छेद 23","अनुच्छेद 24","अनुच्छेद 39"],"explanationHi":"अनुच्छेद 24 खतरनाक कार्यों में बाल श्रम पर रोक लगाता है; अनुच्छेद 23 बलात् श्रम और मानव व्यापार पर रोक लगाता है।"},
  {"id":"polity-fundamental-rights-18","question":"During a National Emergency, the President cannot suspend the right to move courts for the enforcement of:","options":["Articles 14 and 19","Articles 19 and 21","Articles 20 and 21","Articles 21 and 32"],"answer":2,"explanation":"The 44th Amendment (1978) made Articles 20 and 21 non-suspendable under Article 359.","difficulty":"very-hard","questionHi":"राष्ट्रीय आपातकाल के दौरान राष्ट्रपति किन अधिकारों के प्रवर्तन के लिए न्यायालय जाने का अधिकार निलंबित नहीं कर सकता?","optionsHi":["अनुच्छेद 14 और 19","अनुच्छेद 19 और 21","अनुच्छेद 20 और 21","अनुच्छेद 21 और 32"],"explanationHi":"44वें संशोधन (1978) ने अनुच्छेद 20 और 21 को अनुच्छेद 359 के अंतर्गत अनिलंबनीय बना दिया।"},
  {"id":"polity-fundamental-rights-19","question":"The right to privacy was held to be a fundamental right by a nine-judge bench in:","options":["Maneka Gandhi v Union of India (1978)","K. S. Puttaswamy v Union of India (2017)","A. K. Gopalan v State of Madras (1950)","Kharak Singh v State of Uttar Pradesh (1962)"],"answer":1,"explanation":"Puttaswamy (2017) held privacy to be intrinsic to Article 21, overruling the earlier view in M. P. Sharma and Kharak Singh.","difficulty":"very-hard","questionHi":"निजता के अधिकार को नौ न्यायाधीशों की पीठ ने किस मामले में मौलिक अधिकार माना?","optionsHi":["मेनका गांधी बनाम भारत संघ (1978)","के. एस. पुट्टस्वामी बनाम भारत संघ (2017)","ए. के. गोपालन बनाम मद्रास राज्य (1950)","खड़क सिंह बनाम उत्तर प्रदेश राज्य (1962)"],"explanationHi":"पुट्टस्वामी (2017) ने निजता को अनुच्छेद 21 का अंतर्निहित भाग माना और एम. पी. शर्मा तथा खड़क सिंह के पहले के मत को पलट दिया।"},
  {"id":"polity-fundamental-rights-20","question":"How many of these statements are correct? I. Article 14 applies to all persons, including foreigners. II. Article 16 deals with equality of opportunity in public employment. III. Article 18 bars titles but allows military and academic distinctions. IV. Article 17 can be enforced only against the State.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Article 17 (untouchability) applies against private persons too.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. अनुच्छेद 14 विदेशियों सहित सभी व्यक्तियों पर लागू होता है। II. अनुच्छेद 16 लोक नियोजन में अवसर की समता से संबंधित है। III. अनुच्छेद 18 उपाधियों को वर्जित करता है, परंतु सैनिक और शैक्षिक विशिष्टताओं की अनुमति देता है। IV. अनुच्छेद 17 केवल राज्य के विरुद्ध प्रवर्तित कराया जा सकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। अनुच्छेद 17 (अस्पृश्यता) निजी व्यक्तियों के विरुद्ध भी लागू होता है।"},
  {"id":"polity-fundamental-rights-21","question":"How many of these statements are correct? I. Habeas corpus can be issued against private individuals. II. Mandamus can be issued against the President. III. Prohibition can be issued against purely administrative authorities.","options":["Only one","Only two","All three","None"],"answer":0,"explanation":"Only I. Mandamus does not lie against the President or a Governor, and prohibition lies only against judicial or quasi-judicial bodies.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. बंदी प्रत्यक्षीकरण निजी व्यक्तियों के विरुद्ध जारी किया जा सकता है। II. परमादेश राष्ट्रपति के विरुद्ध जारी किया जा सकता है। III. प्रतिषेध केवल प्रशासनिक प्राधिकारियों के विरुद्ध जारी किया जा सकता है।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"केवल I। परमादेश राष्ट्रपति या राज्यपाल के विरुद्ध नहीं दिया जाता, और प्रतिषेध केवल न्यायिक या अर्ध-न्यायिक निकायों के विरुद्ध दिया जाता है।"},
  {"id":"polity-fundamental-rights-22","question":"How many of these Articles are available to foreigners as well as citizens? I. Article 14 II. Article 15 III. Article 20 IV. Article 29","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only Articles 14 and 20. Article 15 protects citizens only, and Article 29 protects “any section of the citizens”.","difficulty":"very-hard","questionHi":"इनमें से कितने अनुच्छेद नागरिकों के साथ-साथ विदेशियों को भी उपलब्ध हैं? I. अनुच्छेद 14 II. अनुच्छेद 15 III. अनुच्छेद 20 IV. अनुच्छेद 29","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल अनुच्छेद 14 और 20। अनुच्छेद 15 केवल नागरिकों की रक्षा करता है, और अनुच्छेद 29 “नागरिकों के किसी भी वर्ग” की रक्षा करता है।"},
  {"id":"polity-fundamental-rights-23","question":"How many of these statements are correct? I. Article 32 is itself a fundamental right. II. The writ jurisdiction of the Supreme Court under Article 32 is wider than that of High Courts under Article 226. III. Jawaharlal Nehru called Article 32 the “heart and soul” of the Constitution.","options":["Only one","Only two","All three","None"],"answer":0,"explanation":"Only I is correct. Article 226 is wider, since High Courts can issue writs for any legal right, not only fundamental rights; and it was Dr Ambedkar, not Nehru, who called Article 32 the 'heart and soul' of the Constitution.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. अनुच्छेद 32 स्वयं एक मौलिक अधिकार है। II. अनुच्छेद 32 के अंतर्गत सर्वोच्च न्यायालय की रिट अधिकारिता अनुच्छेद 226 के अंतर्गत उच्च न्यायालयों की अधिकारिता से अधिक व्यापक है। III. जवाहरलाल नेहरू ने अनुच्छेद 32 को संविधान की “हृदय और आत्मा” कहा।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"केवल I सही है। अनुच्छेद 226 अधिक व्यापक है, क्योंकि उच्च न्यायालय किसी भी कानूनी अधिकार के लिए रिट जारी कर सकते हैं, केवल मौलिक अधिकारों के लिए नहीं; और अनुच्छेद 32 को संविधान की ‘हृदय और आत्मा’ डॉ. अंबेडकर ने कहा था, नेहरू ने नहीं।"},
  {"id":"polity-fundamental-rights-24","question":"The “doctrine of eclipse” applies to:","options":["Pre-Constitution laws inconsistent with fundamental rights","Post-Constitution laws that violate fundamental rights","Constitutional amendments that violate the basic structure","Ordinances that lapse six weeks after Parliament reassembles"],"answer":0,"explanation":"A pre-1950 law that conflicts with a fundamental right is not void but eclipsed; it revives if the right is amended (Bhikaji Narain Dhakras, 1955). Post-constitutional laws that violate fundamental rights are void from the start.","difficulty":"very-hard","questionHi":"“ग्रहण का सिद्धांत” (doctrine of eclipse) किस पर लागू होता है?","optionsHi":["मौलिक अधिकारों से असंगत संविधान-पूर्व कानून","मौलिक अधिकारों का उल्लंघन करने वाले संविधान-पश्चात कानून","मूल ढाँचे का उल्लंघन करने वाले संवैधानिक संशोधन","संसद के पुनः समवेत होने के छह सप्ताह बाद व्यपगत होने वाले अध्यादेश"],"explanationHi":"1950 से पहले का कोई कानून जो मौलिक अधिकार से टकराता है, शून्य नहीं बल्कि ग्रहणग्रस्त होता है; अधिकार में संशोधन होने पर वह पुनर्जीवित हो जाता है (भीकाजी नारायण ढाकरस, 1955)। मौलिक अधिकारों का उल्लंघन करने वाले संविधान-पश्चात कानून शुरू से ही शून्य होते हैं।"},
  {"id":"polity-fundamental-rights-25","question":"Which pair of writ and its literal meaning is NOT correctly matched?","options":["Habeas corpus – “to have the body”","Mandamus – “we command”","Certiorari – “to be certified”","Quo warranto – “to forbid”"],"answer":3,"explanation":"Quo warranto means “by what authority”; it is prohibition that means “to forbid”.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"रिट और उसके शाब्दिक अर्थ की कौन-सी जोड़ी सही सुमेलित नहीं है?","optionsHi":["बंदी प्रत्यक्षीकरण – “शरीर प्रस्तुत करना”","परमादेश – “हम आदेश देते हैं”","उत्प्रेषण – “प्रमाणित किया जाना”","अधिकार पृच्छा – “रोकना”"],"explanationHi":"अधिकार पृच्छा का अर्थ है “किस अधिकार से”; “रोकना” का अर्थ प्रतिषेध का है।"},
  {"id":"polity-fundamental-rights-26","question":"How many of these statements are correct? I. Article 19 originally guaranteed seven freedoms; the right to property was dropped by the 44th Amendment. II. The safeguards of Article 22 against arrest do not apply to enemy aliens. III. Preventive detention beyond three months needs the opinion of an advisory board. IV. Article 21 can be suspended by a Presidential order under Article 359.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Since the 44th Amendment, Articles 20 and 21 cannot be suspended even during a National Emergency.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. अनुच्छेद 19 ने मूल रूप से सात स्वतंत्रताओं की गारंटी दी थी; 44वें संशोधन ने संपत्ति का अधिकार हटा दिया। II. गिरफ्तारी के विरुद्ध अनुच्छेद 22 के रक्षोपाय शत्रु विदेशियों पर लागू नहीं होते। III. तीन माह से अधिक निवारक निरोध के लिए सलाहकार बोर्ड की राय आवश्यक है। IV. अनुच्छेद 21 को अनुच्छेद 359 के अंतर्गत राष्ट्रपति के आदेश द्वारा निलंबित किया जा सकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। 44वें संशोधन के बाद अनुच्छेद 20 और 21 को राष्ट्रीय आपातकाल में भी निलंबित नहीं किया जा सकता।"},
  {"id":"polity-fundamental-rights-27","question":"The Right to Freedom of Religion is guaranteed by which Articles of the Constitution?","options":["Articles 19 to 22","Articles 23 and 24","Articles 25 to 28","Articles 29 and 30"],"answer":2,"explanation":"Articles 25–28 cover freedom of conscience, management of religious affairs, freedom from religious taxes and freedom from religious instruction in state institutions. Articles 29–30 are the Cultural and Educational Rights.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"धर्म की स्वतंत्रता का अधिकार संविधान के किन अनुच्छेदों द्वारा प्रत्याभूत है?","optionsHi":["अनुच्छेद 19 से 22","अनुच्छेद 23 और 24","अनुच्छेद 25 से 28","अनुच्छेद 29 और 30"],"explanationHi":"अनुच्छेद 25–28 अंतःकरण की स्वतंत्रता, धार्मिक कार्यों के प्रबंध, धार्मिक करों से स्वतंत्रता और राज्य संस्थाओं में धार्मिक शिक्षा से स्वतंत्रता को कवर करते हैं। अनुच्छेद 29–30 संस्कृति और शिक्षा संबंधी अधिकार हैं।"},
  {"id":"polity-fundamental-rights-28","question":"Protection against double jeopardy and against being compelled to be a witness against oneself is given by:","options":["Article 20","Article 21","Article 22","Article 19"],"answer":0,"explanation":"Article 20 gives three protections in respect of conviction for offences: no ex post facto law, no double jeopardy and no self-incrimination. Article 22 deals with arrest and detention.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"दोहरे दंड (double jeopardy) से और स्वयं के विरुद्ध साक्षी होने के लिए बाध्य किए जाने से संरक्षण किसके द्वारा दिया गया है?","optionsHi":["अनुच्छेद 20","अनुच्छेद 21","अनुच्छेद 22","अनुच्छेद 19"],"explanationHi":"अनुच्छेद 20 अपराधों के लिए दोषसिद्धि के संबंध में तीन संरक्षण देता है: कोई भूतलक्षी कानून नहीं, कोई दोहरा दंड नहीं और कोई आत्म-अभिशंसन नहीं। अनुच्छेद 22 गिरफ्तारी और निरोध से संबंधित है।"},
  {"id":"polity-fundamental-rights-29","question":"The Cultural and Educational Rights of minorities are contained in:","options":["Articles 14 and 15","Articles 23 and 24","Articles 25 and 26","Articles 29 and 30"],"answer":3,"explanation":"Article 29 protects the language, script and culture of any section of citizens, and Article 30 gives minorities the right to establish and administer educational institutions.","difficulty":"easy","source":"SSC CGL · UPSSSC PET","questionHi":"अल्पसंख्यकों के संस्कृति और शिक्षा संबंधी अधिकार किनमें निहित हैं?","optionsHi":["अनुच्छेद 14 और 15","अनुच्छेद 23 और 24","अनुच्छेद 25 और 26","अनुच्छेद 29 और 30"],"explanationHi":"अनुच्छेद 29 नागरिकों के किसी भी वर्ग की भाषा, लिपि और संस्कृति की रक्षा करता है, और अनुच्छेद 30 अल्पसंख्यकों को शिक्षा संस्थाएँ स्थापित करने और उनका प्रशासन करने का अधिकार देता है।"},
  {"id":"polity-fundamental-rights-30","question":"Under which clause of Article 15 can the State make special provisions for women and children?","options":["Article 15(2)","Article 15(5)","Article 15(4)","Article 15(3)"],"answer":3,"explanation":"Article 15(3) allows special provisions for women and children. Article 15(4) (added in 1951) covers socially and educationally backward classes, SCs and STs, and 15(5) their admission to private educational institutions.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"अनुच्छेद 15 के किस खंड के अंतर्गत राज्य महिलाओं और बच्चों के लिए विशेष उपबंध कर सकता है?","optionsHi":["अनुच्छेद 15(2)","अनुच्छेद 15(5)","अनुच्छेद 15(4)","अनुच्छेद 15(3)"],"explanationHi":"अनुच्छेद 15(3) महिलाओं और बच्चों के लिए विशेष उपबंधों की अनुमति देता है। अनुच्छेद 15(4) (1951 में जोड़ा गया) सामाजिक और शैक्षिक रूप से पिछड़े वर्गों, अनुसूचित जातियों और जनजातियों को कवर करता है, और 15(5) निजी शिक्षा संस्थाओं में उनके प्रवेश को।"},
  {"id":"polity-fundamental-rights-31","question":"Which provision permits reservation of posts in favour of a backward class of citizens that is not adequately represented in state services?","options":["Article 16(1)","Article 16(2)","Article 16(4)","Article 16(3)"],"answer":2,"explanation":"Article 16(4) enables reservation in appointments for any backward class not adequately represented in the services. Article 16(3) lets Parliament prescribe residence as a condition for certain posts.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"कौन-सा उपबंध राज्य सेवाओं में पर्याप्त प्रतिनिधित्व न पाने वाले पिछड़े नागरिक वर्ग के पक्ष में पदों के आरक्षण की अनुमति देता है?","optionsHi":["अनुच्छेद 16(1)","अनुच्छेद 16(2)","अनुच्छेद 16(4)","अनुच्छेद 16(3)"],"explanationHi":"अनुच्छेद 16(4) सेवाओं में पर्याप्त प्रतिनिधित्व न पाने वाले किसी भी पिछड़े वर्ग के लिए नियुक्तियों में आरक्षण को सक्षम बनाता है। अनुच्छेद 16(3) संसद को कुछ पदों के लिए निवास की शर्त निर्धारित करने देता है।"},
  {"id":"polity-fundamental-rights-32","question":"Article 23 prohibits traffic in human beings and begar, but it expressly allows the State to:","options":["Employ children in non-hazardous work with a guardian's consent","Impose compulsory service for public purposes without discrimination","Permit bonded labour in agriculture until an existing debt is repaid","Levy a tax in place of military service on those who are exempted"],"answer":1,"explanation":"Article 23(2) lets the State impose compulsory service for public purposes (such as military or social service) provided it does not discriminate on grounds of religion, race, caste or class.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 23 मानव व्यापार और बेगार को प्रतिषिद्ध करता है, परंतु राज्य को स्पष्ट रूप से किसकी अनुमति देता है?","optionsHi":["अभिभावक की सहमति से बच्चों को गैर-खतरनाक कार्य में नियोजित करना","बिना भेदभाव के सार्वजनिक प्रयोजनों के लिए अनिवार्य सेवा लागू करना","कृषि में विद्यमान ऋण चुकाए जाने तक बंधुआ मजदूरी की अनुमति देना","सैन्य सेवा से छूट पाने वालों पर उसके बदले कर लगाना"],"explanationHi":"अनुच्छेद 23(2) राज्य को सार्वजनिक प्रयोजनों (जैसे सैन्य या सामाजिक सेवा) के लिए अनिवार्य सेवा लागू करने देता है, बशर्ते वह धर्म, मूलवंश, जाति या वर्ग के आधार पर भेदभाव न करे।"},
  {"id":"polity-fundamental-rights-33","question":"Article 30 gives the right to establish and administer educational institutions to:","options":["All citizens","Religious and linguistic minorities","Scheduled Castes and Scheduled Tribes","Only religious minorities"],"answer":1,"explanation":"Article 30(1) confers the right on all minorities, whether based on religion or language. It is a group right that is not available to the majority community.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"अनुच्छेद 30 शिक्षा संस्थाएँ स्थापित करने और उनका प्रशासन करने का अधिकार किसे देता है?","optionsHi":["सभी नागरिकों को","धार्मिक और भाषायी अल्पसंख्यकों को","अनुसूचित जातियों और अनुसूचित जनजातियों को","केवल धार्मिक अल्पसंख्यकों को"],"explanationHi":"अनुच्छेद 30(1) यह अधिकार सभी अल्पसंख्यकों को देता है, चाहे वे धर्म पर आधारित हों या भाषा पर। यह समूह का अधिकार है जो बहुसंख्यक समुदाय को उपलब्ध नहीं है।"},
  {"id":"polity-fundamental-rights-34","question":"Which of these is NOT a ground on which the State may impose reasonable restrictions on freedom of speech under Article 19(2)?","options":["Sovereignty and integrity of India","Contempt of court","Defamation","Economic interests of the State"],"answer":3,"explanation":"Article 19(2) lists sovereignty and integrity, security of the State, friendly relations with foreign states, public order, decency or morality, contempt of court, defamation and incitement to an offence. Economic interests are not a ground.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कौन-सा अनुच्छेद 19(2) के अंतर्गत वाक्-स्वातंत्र्य पर युक्तियुक्त निर्बंधन लगाने का आधार नहीं है?","optionsHi":["भारत की प्रभुता और अखंडता","न्यायालय की अवमानना","मानहानि","राज्य के आर्थिक हित"],"explanationHi":"अनुच्छेद 19(2) प्रभुता और अखंडता, राज्य की सुरक्षा, विदेशी राज्यों से मैत्रीपूर्ण संबंध, लोक व्यवस्था, शिष्टाचार या सदाचार, न्यायालय की अवमानना, मानहानि और अपराध-उद्दीपन को सूचीबद्ध करता है। आर्थिक हित आधार नहीं हैं।"},
  {"id":"polity-fundamental-rights-35","question":"Article 13 declares laws inconsistent with Fundamental Rights void “to the extent of such inconsistency”. The doctrine that follows from these words is the doctrine of:","options":["Eclipse","Severability","Waiver","Pith and substance"],"answer":1,"explanation":"Under the doctrine of severability only the offending part of a law is struck down, if it can be separated from the rest. The doctrine of eclipse applies to pre-constitutional laws that become dormant, not dead.","difficulty":"moderate","source":"UPSC Prelims · State PSC","questionHi":"अनुच्छेद 13 मौलिक अधिकारों से असंगत कानूनों को “ऐसी असंगति की मात्रा तक” शून्य घोषित करता है। इन शब्दों से जो सिद्धांत निकलता है, वह किसका है?","optionsHi":["ग्रहण","पृथक्करणीयता","अधित्याग","सार और तत्व"],"explanationHi":"पृथक्करणीयता के सिद्धांत के अंतर्गत कानून का केवल आपत्तिजनक भाग रद्द होता है, यदि उसे शेष से अलग किया जा सके। ग्रहण का सिद्धांत संविधान-पूर्व कानूनों पर लागू होता है जो मृत नहीं बल्कि सुप्त हो जाते हैं।"},
  {"id":"polity-fundamental-rights-36","question":"Which Amendment added clause (4) to Article 13, declaring that a constitutional amendment under Article 368 is not “law” for the purposes of Article 13?","options":["1st Amendment, 1951","24th Amendment, 1971","25th Amendment, 1971","42nd Amendment, 1976"],"answer":1,"explanation":"After Golaknath (1967) held that Parliament could not amend Fundamental Rights, the 24th Amendment added Article 13(4) and Article 368(3) to restore the amending power. The 25th Amendment inserted Article 31C.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"किस संशोधन ने अनुच्छेद 13 में खंड (4) जोड़ा, जिसमें घोषित किया गया कि अनुच्छेद 368 के अंतर्गत संवैधानिक संशोधन अनुच्छेद 13 के प्रयोजनों के लिए “विधि” नहीं है?","optionsHi":["पहला संशोधन, 1951","24वाँ संशोधन, 1971","25वाँ संशोधन, 1971","42वाँ संशोधन, 1976"],"explanationHi":"गोलकनाथ (1967) में यह माने जाने के बाद कि संसद मौलिक अधिकारों में संशोधन नहीं कर सकती, 24वें संशोधन ने संशोधन की शक्ति बहाल करने के लिए अनुच्छेद 13(4) और अनुच्छेद 368(3) जोड़े। 25वें संशोधन ने अनुच्छेद 31C जोड़ा।"},
  {"id":"polity-fundamental-rights-37","question":"Article 15(5), which allows reservation for socially and educationally backward classes in private unaided educational institutions other than minority institutions, was inserted by the:","options":["85th Amendment, 2001","86th Amendment, 2002","93rd Amendment, 2005","97th Amendment, 2011"],"answer":2,"explanation":"The 93rd Amendment (2005) added Article 15(5) after the Supreme Court’s decision in P. A. Inamdar; it excludes minority institutions under Article 30(1). The 86th Amendment added Article 21A.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 15(5), जो अल्पसंख्यक संस्थाओं को छोड़कर निजी गैर-सहायता प्राप्त शिक्षा संस्थाओं में सामाजिक और शैक्षिक रूप से पिछड़े वर्गों के लिए आरक्षण की अनुमति देता है, किसके द्वारा जोड़ा गया?","optionsHi":["85वाँ संशोधन, 2001","86वाँ संशोधन, 2002","93वाँ संशोधन, 2005","97वाँ संशोधन, 2011"],"explanationHi":"93वें संशोधन (2005) ने पी. ए. इनामदार में सर्वोच्च न्यायालय के निर्णय के बाद अनुच्छेद 15(5) जोड़ा; यह अनुच्छेद 30(1) के अंतर्गत अल्पसंख्यक संस्थाओं को बाहर रखता है। 86वें संशोधन ने अनुच्छेद 21A जोड़ा।"},
  {"id":"polity-fundamental-rights-38","question":"The 10% reservation for Economically Weaker Sections was added through Articles 15(6) and 16(6) by the:","options":["102nd Amendment, 2018","103rd Amendment, 2019","104th Amendment, 2019","101st Amendment, 2016"],"answer":1,"explanation":"The 103rd Amendment (2019) inserted Articles 15(6) and 16(6); it was upheld by a 3:2 majority in Janhit Abhiyan v. Union of India (2022). The 102nd Amendment gave constitutional status to the National Commission for Backward Classes.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"आर्थिक रूप से कमजोर वर्गों के लिए 10% आरक्षण अनुच्छेद 15(6) और 16(6) के माध्यम से किसके द्वारा जोड़ा गया?","optionsHi":["102वाँ संशोधन, 2018","103वाँ संशोधन, 2019","104वाँ संशोधन, 2019","101वाँ संशोधन, 2016"],"explanationHi":"103वें संशोधन (2019) ने अनुच्छेद 15(6) और 16(6) जोड़े; इसे जनहित अभियान बनाम भारत संघ (2022) में 3:2 के बहुमत से बरकरार रखा गया। 102वें संशोधन ने राष्ट्रीय पिछड़ा वर्ग आयोग को संवैधानिक दर्जा दिया।"},
  {"id":"polity-fundamental-rights-39","question":"Before Article 21A was inserted in 2002, the Supreme Court had already read a right to education for children up to 14 years into Article 21 in:","options":["Vishaka v. State of Rajasthan (1997)","Maneka Gandhi v. Union of India (1978)","Olga Tellis v. Bombay Municipal Corporation (1985)","Unni Krishnan v. State of Andhra Pradesh (1993)"],"answer":3,"explanation":"In Unni Krishnan (1993), building on Mohini Jain (1992), the Court held that the right to education up to 14 years flows from Article 21 read with Article 45. Olga Tellis dealt with the right to livelihood and Vishaka with sexual harassment at work.","difficulty":"hard","source":"UPSC Prelims","questionHi":"2002 में अनुच्छेद 21A जोड़े जाने से पहले ही सर्वोच्च न्यायालय ने 14 वर्ष तक के बच्चों के शिक्षा के अधिकार को अनुच्छेद 21 में किस मामले में पढ़ लिया था?","optionsHi":["विशाखा बनाम राजस्थान राज्य (1997)","मेनका गांधी बनाम भारत संघ (1978)","ओल्गा टेलिस बनाम बॉम्बे म्युनिसिपल कॉर्पोरेशन (1985)","उन्नी कृष्णन बनाम आंध्र प्रदेश राज्य (1993)"],"explanationHi":"उन्नी कृष्णन (1993) में, मोहिनी जैन (1992) के आधार पर, न्यायालय ने माना कि 14 वर्ष तक शिक्षा का अधिकार अनुच्छेद 45 के साथ पढ़े गए अनुच्छेद 21 से निकलता है। ओल्गा टेलिस आजीविका के अधिकार से और विशाखा कार्यस्थल पर यौन उत्पीड़न से संबंधित थी।"},
  {"id":"polity-fundamental-rights-40","question":"The 44th Amendment (1978) reduced the period for which a person can be preventively detained without the opinion of an advisory board from three months to two months. What is the status of this change?","options":["It has been in force since the Amendment was notified in 1979","It was struck down by the Supreme Court in A. K. Roy (1982)","It was never notified, so the three-month limit still applies","It applies only to detentions under central laws such as the NSA"],"answer":2,"explanation":"Section 3 of the 44th Amendment Act, which amended Article 22, was never notified by the government, so the original three-month limit continues to operate.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"44वें संशोधन (1978) ने उस अवधि को, जिसके लिए किसी व्यक्ति को सलाहकार बोर्ड की राय के बिना निवारक निरोध में रखा जा सकता है, तीन माह से घटाकर दो माह कर दिया। इस परिवर्तन की स्थिति क्या है?","optionsHi":["अधिसूचित होने के बाद 1979 से यह लागू है","सर्वोच्च न्यायालय ने इसे ए. के. रॉय (1982) में रद्द कर दिया","इसे कभी अधिसूचित नहीं किया गया, इसलिए तीन माह की सीमा अब भी लागू है","यह केवल राष्ट्रीय सुरक्षा अधिनियम (NSA) जैसे केंद्रीय कानूनों के अंतर्गत निरोध पर लागू होता है"],"explanationHi":"44वें संशोधन अधिनियम की धारा 3, जिसने अनुच्छेद 22 में संशोधन किया, सरकार द्वारा कभी अधिसूचित नहीं की गई, इसलिए मूल तीन माह की सीमा लागू रहती है।"},
  {"id":"polity-fundamental-rights-41","question":"The narrow interpretation of “procedure established by law” in A. K. Gopalan (1950) was overturned, requiring the procedure under Article 21 to be just, fair and reasonable, in:","options":["Kharak Singh v. State of U.P. (1962)","Sunil Batra v. Delhi Administration (1978)","ADM Jabalpur v. Shivkant Shukla (1976)","Maneka Gandhi v. Union of India (1978)"],"answer":3,"explanation":"Maneka Gandhi (1978) read Articles 14, 19 and 21 together and introduced American-style due process into Article 21. ADM Jabalpur (the Habeas Corpus case) had, in contrast, denied relief during the Emergency.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"ए. के. गोपालन (1950) में “विधि द्वारा स्थापित प्रक्रिया” की संकीर्ण व्याख्या को किस मामले में पलटा गया, जिसमें अनुच्छेद 21 के अंतर्गत प्रक्रिया का न्यायसंगत, निष्पक्ष और युक्तियुक्त होना आवश्यक ठहराया गया?","optionsHi":["खड़क सिंह बनाम उत्तर प्रदेश राज्य (1962)","सुनील बत्रा बनाम दिल्ली प्रशासन (1978)","एडीएम जबलपुर बनाम शिवकांत शुक्ला (1976)","मेनका गांधी बनाम भारत संघ (1978)"],"explanationHi":"मेनका गांधी (1978) ने अनुच्छेद 14, 19 और 21 को साथ पढ़ा और अनुच्छेद 21 में अमेरिकी शैली की “सम्यक प्रक्रिया” (due process) लाई। इसके विपरीत एडीएम जबलपुर (बंदी प्रत्यक्षीकरण मामला) ने आपातकाल में राहत देने से इनकार किया था।"},
  {"id":"polity-fundamental-rights-42","question":"The right to form co-operative societies was added to Article 19(1)(c) by the:","options":["73rd Amendment, 1992","86th Amendment, 2002","97th Amendment, 2011","99th Amendment, 2014"],"answer":2,"explanation":"The 97th Amendment (2011) added “co-operative societies” to Article 19(1)(c), inserted Article 43B in the Directive Principles and added Part IX-B on co-operative societies.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"सहकारी समितियाँ बनाने का अधिकार अनुच्छेद 19(1)(c) में किसके द्वारा जोड़ा गया?","optionsHi":["73वाँ संशोधन, 1992","86वाँ संशोधन, 2002","97वाँ संशोधन, 2011","99वाँ संशोधन, 2014"],"explanationHi":"97वें संशोधन (2011) ने अनुच्छेद 19(1)(c) में “सहकारी समितियाँ” जोड़ा, नीति निदेशक तत्वों में अनुच्छेद 43B जोड़ा और सहकारी समितियों पर भाग IX-B जोड़ा।"},
  {"id":"polity-fundamental-rights-43","question":"Under Article 32(3), the power to issue writs for the enforcement of Fundamental Rights can be conferred on any other court by:","options":["The President by order","Parliament by law","The Supreme Court by rules","The Chief Justice of India"],"answer":1,"explanation":"Article 32(3) empowers Parliament, by law, to authorise any other court to exercise the Supreme Court’s writ powers without prejudice to the Supreme Court’s own jurisdiction. No such law has yet been made.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"अनुच्छेद 32(3) के अंतर्गत मौलिक अधिकारों के प्रवर्तन के लिए रिट जारी करने की शक्ति किसी अन्य न्यायालय को किसके द्वारा दी जा सकती है?","optionsHi":["राष्ट्रपति द्वारा आदेश से","संसद द्वारा कानून से","सर्वोच्च न्यायालय द्वारा नियमों से","भारत के मुख्य न्यायाधीश द्वारा"],"explanationHi":"अनुच्छेद 32(3) संसद को कानून द्वारा किसी अन्य न्यायालय को सर्वोच्च न्यायालय की रिट शक्तियों के प्रयोग का अधिकार देने की शक्ति देता है, सर्वोच्च न्यायालय की अपनी अधिकारिता पर प्रभाव डाले बिना। अब तक ऐसा कोई कानून नहीं बना है।"},
  {"id":"polity-fundamental-rights-44","question":"The protection against ex post facto laws in Article 20(1) does NOT extend to:","options":["Imposing a penalty greater than that prescribed when the offence was committed","Conviction for an act that was not an offence when committed","Civil liabilities and retrospective tax laws","Punishment for a criminal offence under a retrospective law"],"answer":2,"explanation":"Article 20(1) applies only to criminal convictions and punishments. Civil legislation and tax laws can operate retrospectively, as can preventive detention, which is not a punishment for an offence.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 20(1) में भूतलक्षी कानूनों (ex post facto) से संरक्षण किस पर लागू नहीं होता?","optionsHi":["अपराध के समय निर्धारित दंड से अधिक दंड लगाना","ऐसे कृत्य के लिए दोषसिद्धि जो करते समय अपराध नहीं था","सिविल दायित्व और भूतलक्षी कर कानून","भूतलक्षी कानून के अंतर्गत किसी आपराधिक अपराध के लिए दंड"],"explanationHi":"अनुच्छेद 20(1) केवल आपराधिक दोषसिद्धि और दंड पर लागू होता है। सिविल विधान और कर कानून भूतलक्षी हो सकते हैं, और निवारक निरोध भी, जो किसी अपराध का दंड नहीं है।"},
  {"id":"polity-fundamental-rights-45","question":"How many of these statements about Article 19 are correct? I. Article 19 today guarantees six freedoms. II. The freedom to acquire, hold and dispose of property under Article 19(1)(f) was deleted by the 44th Amendment. III. The ground “sovereignty and integrity of India” in Article 19(2) was added by the 16th Amendment, 1963. IV. The rights under Article 19 are available only to citizens.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: Article 19 now has six freedoms after the 44th Amendment removed 19(1)(f), the 16th Amendment (1963) added 'sovereignty and integrity of India', and Article 19 rights are available only to citizens.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 19 के बारे में इनमें से कितने कथन सही हैं? I. आज अनुच्छेद 19 छह स्वतंत्रताओं की गारंटी देता है। II. अनुच्छेद 19(1)(f) के अंतर्गत संपत्ति अर्जित करने, धारण करने और व्ययन की स्वतंत्रता 44वें संशोधन द्वारा हटा दी गई। III. अनुच्छेद 19(2) में “भारत की प्रभुता और अखंडता” का आधार 16वें संशोधन, 1963 द्वारा जोड़ा गया। IV. अनुच्छेद 19 के अधिकार केवल नागरिकों को उपलब्ध हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार सही हैं: 44वें संशोधन द्वारा 19(1)(f) हटाए जाने के बाद अनुच्छेद 19 में अब छह स्वतंत्रताएँ हैं, 16वें संशोधन (1963) ने ‘भारत की प्रभुता और अखंडता’ जोड़ा, और अनुच्छेद 19 के अधिकार केवल नागरिकों को उपलब्ध हैं।"},
  {"id":"polity-fundamental-rights-46","question":"Assertion (A): The rights under Articles 20 and 21 cannot be suspended even during a National Emergency. Reason (R): The 44th Amendment, 1978 amended Article 359 to exclude Articles 20 and 21 from any Presidential order suspending the enforcement of Fundamental Rights.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"After the Emergency experience and ADM Jabalpur, the 44th Amendment made Articles 20 and 21 immune from suspension under Article 359; R is exactly why A holds.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): अनुच्छेद 20 और 21 के अधिकार राष्ट्रीय आपातकाल में भी निलंबित नहीं किए जा सकते। कारण (R): 44वें संशोधन, 1978 ने अनुच्छेद 359 में संशोधन कर अनुच्छेद 20 और 21 को मौलिक अधिकारों के प्रवर्तन को निलंबित करने वाले राष्ट्रपति के किसी भी आदेश से बाहर कर दिया।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"आपातकाल के अनुभव और एडीएम जबलपुर के बाद 44वें संशोधन ने अनुच्छेद 20 और 21 को अनुच्छेद 359 के अंतर्गत निलंबन से मुक्त कर दिया; R ठीक यही कारण है कि A सही है।"},
  {"id":"polity-fundamental-rights-47","question":"Arrange these Supreme Court cases in chronological order: 1. Maneka Gandhi 2. A. K. Gopalan 3. K. S. Puttaswamy 4. Kesavananda Bharati","options":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1"],"answer":0,"explanation":"A. K. Gopalan (1950), Kesavananda Bharati (1973), Maneka Gandhi (1978) and Puttaswamy (2017).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सर्वोच्च न्यायालय के इन मामलों को कालानुक्रम में व्यवस्थित कीजिए: 1. मेनका गांधी 2. ए. के. गोपालन 3. के. एस. पुट्टस्वामी 4. केशवानंद भारती","optionsHi":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1"],"explanationHi":"ए. के. गोपालन (1950), केशवानंद भारती (1973), मेनका गांधी (1978) और पुट्टस्वामी (2017)।"},
  {"id":"polity-fundamental-rights-48","question":"Which pair of Article and its subject is NOT correctly matched?","options":["Article 16 – Equality of opportunity in public employment","Article 18 – Abolition of untouchability","Article 23 – Prohibition of traffic in human beings and forced labour","Article 28 – Freedom from religious instruction in institutions wholly maintained by State funds"],"answer":1,"explanation":"Article 18 abolishes titles; untouchability is abolished by Article 17.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"अनुच्छेद और उसके विषय की कौन-सी जोड़ी सही सुमेलित नहीं है?","optionsHi":["अनुच्छेद 16 – लोक नियोजन में अवसर की समता","अनुच्छेद 18 – अस्पृश्यता का अंत","अनुच्छेद 23 – मानव व्यापार और बलात् श्रम का प्रतिषेध","अनुच्छेद 28 – पूर्णतः राज्य निधि से पोषित संस्थाओं में धार्मिक शिक्षा से स्वतंत्रता"],"explanationHi":"अनुच्छेद 18 उपाधियों का अंत करता है; अस्पृश्यता का अंत अनुच्छेद 17 द्वारा होता है।"},
  {"id":"polity-fundamental-rights-49","question":"How many of these statements about Articles 25 to 28 are correct? I. Article 25 (freedom of conscience) is available to all persons, not only citizens. II. Article 26 gives rights to religious denominations as groups. III. Article 27 says no person shall be compelled to pay taxes for the promotion of any particular religion. IV. Article 28 bars religious instruction in institutions wholly maintained out of State funds.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Note the distinction in Article 27: a tax for promoting a religion is barred, but a fee for regulating religious institutions is permissible.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 25 से 28 के बारे में इनमें से कितने कथन सही हैं? I. अनुच्छेद 25 (अंतःकरण की स्वतंत्रता) सभी व्यक्तियों को उपलब्ध है, केवल नागरिकों को नहीं। II. अनुच्छेद 26 धार्मिक संप्रदायों को समूह के रूप में अधिकार देता है। III. अनुच्छेद 27 कहता है कि किसी व्यक्ति को किसी विशेष धर्म की अभिवृद्धि के लिए कर चुकाने को बाध्य नहीं किया जाएगा। IV. अनुच्छेद 28 पूर्णतः राज्य निधि से पोषित संस्थाओं में धार्मिक शिक्षा को वर्जित करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार सही हैं। अनुच्छेद 27 में भेद ध्यान रखें: किसी धर्म की अभिवृद्धि के लिए कर वर्जित है, परंतु धार्मिक संस्थाओं के विनियमन के लिए शुल्क अनुमेय है।"},
  {"id":"polity-fundamental-rights-50","question":"How many of these statements about reservation-related Amendments are correct? I. The 77th Amendment (1995) added Article 16(4A) allowing reservation in promotions for SCs and STs. II. The 81st Amendment (2000) added Article 16(4B) allowing unfilled reserved vacancies to be carried forward. III. The 85th Amendment (2001) introduced the “creamy layer” concept into Article 16. IV. The 103rd Amendment (2019) added Articles 15(6) and 16(6) for Economically Weaker Sections.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. The 85th Amendment gave consequential seniority in promotion; the creamy layer idea came from the Supreme Court (Indra Sawhney, 1992), not from an amendment.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"आरक्षण संबंधी संशोधनों के बारे में इनमें से कितने कथन सही हैं? I. 77वें संशोधन (1995) ने अनुसूचित जातियों और जनजातियों के लिए पदोन्नति में आरक्षण की अनुमति देने वाला अनुच्छेद 16(4A) जोड़ा। II. 81वें संशोधन (2000) ने अनुच्छेद 16(4B) जोड़ा, जो न भरी गई आरक्षित रिक्तियों को आगे ले जाने की अनुमति देता है। III. 85वें संशोधन (2001) ने अनुच्छेद 16 में “क्रीमी लेयर” की अवधारणा लाई। IV. 103वें संशोधन (2019) ने आर्थिक रूप से कमजोर वर्गों के लिए अनुच्छेद 15(6) और 16(6) जोड़े।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। 85वें संशोधन ने पदोन्नति में परिणामी वरिष्ठता दी; क्रीमी लेयर का विचार सर्वोच्च न्यायालय (इंद्रा साहनी, 1992) से आया, किसी संशोधन से नहीं।"},
  {"id":"polity-fundamental-rights-51","question":"Assertion (A): Some Fundamental Rights can be enforced against private individuals and not only against the State. Reason (R): Articles 15(2), 17, 23 and 24 are worded so as to apply against private persons as well.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Most Fundamental Rights run against the State, but access to shops and public places (15(2)), untouchability (17), forced labour (23) and child labour (24) are enforceable against private persons too.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): कुछ मौलिक अधिकार निजी व्यक्तियों के विरुद्ध भी प्रवर्तित कराए जा सकते हैं, केवल राज्य के विरुद्ध नहीं। कारण (R): अनुच्छेद 15(2), 17, 23 और 24 इस प्रकार शब्दबद्ध हैं कि वे निजी व्यक्तियों पर भी लागू होते हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"अधिकांश मौलिक अधिकार राज्य के विरुद्ध लागू होते हैं, परंतु दुकानों और सार्वजनिक स्थानों तक पहुँच (15(2)), अस्पृश्यता (17), बलात् श्रम (23) और बाल श्रम (24) निजी व्यक्तियों के विरुद्ध भी प्रवर्तनीय हैं।"},
  {"id":"polity-fundamental-rights-52","question":"How many of these statements about writs are correct? I. Habeas corpus will not be issued when the detention is lawful. II. Mandamus cannot be issued to enforce a private contractual obligation. III. Certiorari, originally confined to judicial and quasi-judicial bodies, has been available against administrative authorities since 1991. IV. Quo warranto lies only in respect of a substantive public office.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Habeas corpus fails for lawful detention, mandamus does not enforce private contracts, certiorari extends to administrative authorities since 1991, and quo warranto lies only for a substantive public office.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"रिटों के बारे में इनमें से कितने कथन सही हैं? I. निरोध वैध होने पर बंदी प्रत्यक्षीकरण जारी नहीं किया जाएगा। II. परमादेश किसी निजी संविदात्मक बाध्यता के प्रवर्तन के लिए जारी नहीं किया जा सकता। III. उत्प्रेषण, जो मूल रूप से न्यायिक और अर्ध-न्यायिक निकायों तक सीमित था, 1991 से प्रशासनिक प्राधिकारियों के विरुद्ध उपलब्ध है। IV. अधिकार पृच्छा केवल सारवान लोक पद के संबंध में लागू होती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार सही हैं। वैध निरोध में बंदी प्रत्यक्षीकरण विफल होता है, परमादेश निजी संविदाओं को लागू नहीं कराता, उत्प्रेषण 1991 से प्रशासनिक प्राधिकारियों तक बढ़ा है, और अधिकार पृच्छा केवल सारवान लोक पद के लिए होती है।"},
  {"id":"polity-fundamental-rights-53","question":"Arrange these Constitutional Amendments in chronological order: 1. 44th Amendment (right to property removed) 2. 86th Amendment (right to education) 3. 24th Amendment (Article 13(4) added) 4. 93rd Amendment (Article 15(5) added)","options":["3, 1, 2, 4","1, 3, 2, 4","3, 1, 4, 2","1, 3, 4, 2"],"answer":0,"explanation":"Anchor each amendment to its year: 24th (1971), 44th (1978), 86th (2002) and 93rd (2005), giving 3, 1, 2, 4. The tempting slip is placing the 93rd before the 86th because both deal with education.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"इन संवैधानिक संशोधनों को कालानुक्रम में व्यवस्थित कीजिए: 1. 44वाँ संशोधन (संपत्ति का अधिकार हटाया गया) 2. 86वाँ संशोधन (शिक्षा का अधिकार) 3. 24वाँ संशोधन (अनुच्छेद 13(4) जोड़ा गया) 4. 93वाँ संशोधन (अनुच्छेद 15(5) जोड़ा गया)","optionsHi":["3, 1, 2, 4","1, 3, 2, 4","3, 1, 4, 2","1, 3, 4, 2"],"explanationHi":"प्रत्येक संशोधन को उसके वर्ष से जोड़ें: 24वाँ (1971), 44वाँ (1978), 86वाँ (2002) और 93वाँ (2005), जिससे 3, 1, 2, 4 बनता है। भ्रम यह है कि 93वें को 86वें से पहले रख दिया जाए क्योंकि दोनों शिक्षा से संबंधित हैं।"},
  {"id":"polity-fundamental-rights-54","question":"How many of these have been held by the Supreme Court to be part of the right to life under Article 21? I. Right to sleep II. Right to die with dignity, including passive euthanasia III. Right to privacy IV. Right to property","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I (Ramlila Maidan, 2012), II (Common Cause, 2018) and III (Puttaswamy, 2017) are part of Article 21. The right to property is only a constitutional/legal right under Article 300A since 1978.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने को सर्वोच्च न्यायालय ने अनुच्छेद 21 के अंतर्गत जीवन के अधिकार का भाग माना है? I. सोने का अधिकार II. गरिमा के साथ मृत्यु का अधिकार, जिसमें निष्क्रिय इच्छामृत्यु शामिल है III. निजता का अधिकार IV. संपत्ति का अधिकार","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I (रामलीला मैदान, 2012), II (कॉमन कॉज, 2018) और III (पुट्टस्वामी, 2017) अनुच्छेद 21 का भाग हैं। संपत्ति का अधिकार 1978 से केवल अनुच्छेद 300A के अंतर्गत संवैधानिक/विधिक अधिकार है।"},
  {"id":"polity-fundamental-rights-55","question":"Which of these is NOT a Fundamental Right under Article 19?","options":["Right to form associations or unions","Right to strike","Right to move freely throughout the territory of India","Right to reside and settle in any part of India"],"answer":1,"explanation":"The Supreme Court has repeatedly held that the right to strike is not a fundamental right; it is only a legal right regulated by industrial law, and does not flow from the right to form unions under Article 19(1)(c).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कौन-सा अनुच्छेद 19 के अंतर्गत मौलिक अधिकार नहीं है?","optionsHi":["संगम या संघ बनाने का अधिकार","हड़ताल का अधिकार","भारत के राज्यक्षेत्र में सर्वत्र अबाध संचरण का अधिकार","भारत के किसी भी भाग में निवास करने और बसने का अधिकार"],"explanationHi":"सर्वोच्च न्यायालय ने बार-बार माना है कि हड़ताल का अधिकार मौलिक अधिकार नहीं है; यह केवल औद्योगिक कानून द्वारा विनियमित विधिक अधिकार है, और यह अनुच्छेद 19(1)(c) के संघ बनाने के अधिकार से नहीं निकलता।"},
  {"id":"polity-fundamental-rights-56","question":"Assertion (A): Article 15(4), permitting special provisions for socially and educationally backward classes, was added by the 1st Amendment, 1951. Reason (R): It was Parliament’s response to the Supreme Court striking down caste-based reservation in State of Madras v. Champakam Dorairajan.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"In Champakam Dorairajan (1951) the Court struck down the Madras Communal G.O. as violating Article 15(1); the 1st Amendment then inserted Article 15(4) to permit such provisions.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): सामाजिक और शैक्षिक रूप से पिछड़े वर्गों के लिए विशेष उपबंधों की अनुमति देने वाला अनुच्छेद 15(4) पहले संशोधन, 1951 द्वारा जोड़ा गया। कारण (R): यह मद्रास राज्य बनाम चंपकम दोराईराजन में सर्वोच्च न्यायालय द्वारा जाति-आधारित आरक्षण को रद्द करने पर संसद की प्रतिक्रिया थी।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"चंपकम दोराईराजन (1951) में न्यायालय ने मद्रास सांप्रदायिक सरकारी आदेश को अनुच्छेद 15(1) का उल्लंघन मानकर रद्द किया; फिर पहले संशोधन ने ऐसे उपबंधों की अनुमति देने के लिए अनुच्छेद 15(4) जोड़ा।"},
  {"id":"polity-fundamental-rights-57","question":"Article 21A obliges the State to provide free and compulsory education to all children in the age group of:","options":["3 to 10 years","5 to 15 years","6 to 14 years","6 to 18 years"],"answer":2,"explanation":"Article 21A, inserted by the 86th Amendment (2002), covers children aged six to fourteen; the Right of Children to Free and Compulsory Education Act, 2009 gives it effect.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"अनुच्छेद 21A राज्य को किस आयु वर्ग के सभी बच्चों को निःशुल्क और अनिवार्य शिक्षा देने के लिए बाध्य करता है?","optionsHi":["3 से 10 वर्ष","5 से 15 वर्ष","6 से 14 वर्ष","6 से 18 वर्ष"],"explanationHi":"86वें संशोधन (2002) द्वारा जोड़ा गया अनुच्छेद 21A छह से चौदह वर्ष के बच्चों को कवर करता है; बच्चों का निःशुल्क और अनिवार्य शिक्षा का अधिकार अधिनियम, 2009 इसे प्रभावी बनाता है।"},
  {"id":"polity-fundamental-rights-58","question":"Which Article defines the term “State” for the purposes of Part III (Fundamental Rights)?","options":["Article 12","Article 13","Article 36","Article 14"],"answer":0,"explanation":"Article 12 defines “State” to include the Government and Parliament of India, State governments and legislatures, and all local or other authorities. Article 36 applies the same meaning to Part IV.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"कौन-सा अनुच्छेद भाग III (मौलिक अधिकार) के प्रयोजनों के लिए “राज्य” पद को परिभाषित करता है?","optionsHi":["अनुच्छेद 12","अनुच्छेद 13","अनुच्छेद 36","अनुच्छेद 14"],"explanationHi":"अनुच्छेद 12 “राज्य” में भारत की सरकार और संसद, राज्यों की सरकारें और विधानमंडल, तथा सभी स्थानीय या अन्य प्राधिकारियों को शामिल करता है। अनुच्छेद 36 यही अर्थ भाग IV पर लागू करता है।"},
  {"id":"polity-fundamental-rights-59","question":"Under Article 22(2), a person arrested and detained must be produced before the nearest magistrate within:","options":["12 hours","24 hours, excluding the time of the journey","48 hours, including the time of the journey","72 hours"],"answer":1,"explanation":"Article 22(2) fixes 24 hours, excluding the time needed for the journey from the place of arrest to the court. No further detention is allowed without the magistrate’s authority.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"अनुच्छेद 22(2) के अंतर्गत गिरफ्तार और निरुद्ध किए गए व्यक्ति को निकटतम मजिस्ट्रेट के समक्ष कितने समय के भीतर पेश किया जाना चाहिए?","optionsHi":["12 घंटे","24 घंटे, यात्रा का समय छोड़कर","48 घंटे, यात्रा का समय सहित","72 घंटे"],"explanationHi":"अनुच्छेद 22(2) 24 घंटे तय करता है, गिरफ्तारी के स्थान से न्यायालय तक यात्रा में लगे समय को छोड़कर। मजिस्ट्रेट के प्राधिकार के बिना और अधिक निरोध की अनुमति नहीं है।"},
  {"id":"polity-fundamental-rights-60","question":"The freedom to reside and settle in any part of the territory of India is guaranteed by:","options":["Article 19(1)(b)","Article 19(1)(d)","Article 19(1)(g)","Article 19(1)(e)"],"answer":3,"explanation":"Article 19(1)(e) is the freedom to reside and settle; 19(1)(d) is the separate freedom to move freely throughout India; 19(1)(b) is to assemble peaceably and 19(1)(g) is to practise any profession or trade.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"भारत के राज्यक्षेत्र के किसी भी भाग में निवास करने और बसने की स्वतंत्रता किसके द्वारा प्रत्याभूत है?","optionsHi":["अनुच्छेद 19(1)(b)","अनुच्छेद 19(1)(d)","अनुच्छेद 19(1)(g)","अनुच्छेद 19(1)(e)"],"explanationHi":"अनुच्छेद 19(1)(e) निवास करने और बसने की स्वतंत्रता है; 19(1)(d) भारत में सर्वत्र अबाध संचरण की अलग स्वतंत्रता है; 19(1)(b) शांतिपूर्वक एकत्र होना और 19(1)(g) कोई वृत्ति या व्यापार करना है।"},
  {"id":"polity-fundamental-rights-61","question":"The Ninth Schedule, which shields the laws placed in it from challenge on the ground of violating Fundamental Rights, was added along with Article 31B by the:","options":["1st Amendment, 1951","4th Amendment, 1955","17th Amendment, 1964","25th Amendment, 1971"],"answer":0,"explanation":"The 1st Amendment (1951) created Article 31B and the Ninth Schedule to protect land reform laws. In I. R. Coelho (2007) the Court held that laws added after 24 April 1973 can still be tested against the basic structure.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"नौवीं अनुसूची, जो उसमें रखे गए कानूनों को मौलिक अधिकारों के उल्लंघन के आधार पर चुनौती से बचाती है, अनुच्छेद 31B के साथ किसके द्वारा जोड़ी गई?","optionsHi":["पहला संशोधन, 1951","चौथा संशोधन, 1955","17वाँ संशोधन, 1964","25वाँ संशोधन, 1971"],"explanationHi":"पहले संशोधन (1951) ने भूमि सुधार कानूनों की रक्षा के लिए अनुच्छेद 31B और नौवीं अनुसूची बनाई। आई. आर. कोएलो (2007) में न्यायालय ने माना कि 24 अप्रैल 1973 के बाद जोड़े गए कानूनों की भी मूल ढाँचे की कसौटी पर जाँच हो सकती है।"},
  {"id":"polity-fundamental-rights-62","question":"Article 29(1), which protects the right to conserve a distinct language, script or culture, is available to:","options":["Only religious minorities notified as such by the Central Government","Only linguistic minorities, as determined State by State","Any section of citizens with its own language, script or culture","All persons residing in India, including foreign nationals"],"answer":2,"explanation":"Article 29(1) speaks of “any section of the citizens”, so it is not confined to minorities, unlike Article 30. Being limited to citizens, it does not extend to foreigners.","difficulty":"moderate","source":"UPSC Prelims · State PSC","questionHi":"अनुच्छेद 29(1), जो विशिष्ट भाषा, लिपि या संस्कृति को बनाए रखने के अधिकार की रक्षा करता है, किसे उपलब्ध है?","optionsHi":["केवल केंद्र सरकार द्वारा अधिसूचित धार्मिक अल्पसंख्यकों को","केवल भाषायी अल्पसंख्यकों को, जैसा राज्य-दर-राज्य निर्धारित हो","नागरिकों के किसी भी वर्ग को जिसकी अपनी भाषा, लिपि या संस्कृति हो","भारत में निवास करने वाले सभी व्यक्तियों को, विदेशी नागरिकों सहित"],"explanationHi":"अनुच्छेद 29(1) “नागरिकों के किसी भी वर्ग” की बात करता है, इसलिए अनुच्छेद 30 के विपरीत यह अल्पसंख्यकों तक सीमित नहीं है। नागरिकों तक सीमित होने के कारण यह विदेशियों तक नहीं बढ़ता।"},
  {"id":"polity-fundamental-rights-63","question":"Explanation I to Article 25 states that the wearing and carrying of which of these shall be deemed to be included in the profession of the Sikh religion?","options":["Kara","Kirpan","Kesh","Kangha"],"answer":1,"explanation":"Explanation I to Article 25 expressly protects the wearing and carrying of kirpans by Sikhs. The other articles of faith are not mentioned in the text.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"अनुच्छेद 25 का स्पष्टीकरण I कहता है कि इनमें से किसे धारण करना और लेकर चलना सिख धर्म के मानने में शामिल समझा जाएगा?","optionsHi":["कड़ा","कृपाण","केश","कंघा"],"explanationHi":"अनुच्छेद 25 का स्पष्टीकरण I सिखों द्वारा कृपाण धारण करने और लेकर चलने को स्पष्ट रूप से संरक्षित करता है। अन्य आस्था-प्रतीकों का पाठ में उल्लेख नहीं है।"},
  {"id":"polity-fundamental-rights-64","question":"Under Article 16(3), a residence requirement within a State for appointment to certain posts under that State can be prescribed only by:","options":["The State Legislature","The Governor","Parliament","The State Public Service Commission"],"answer":2,"explanation":"Article 16(3) allows only Parliament to prescribe residence as a condition for employment in a State; Article 35 reinforces that such laws are for Parliament alone, not State legislatures.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 16(3) के अंतर्गत किसी राज्य के अधीन कुछ पदों पर नियुक्ति के लिए उस राज्य में निवास की शर्त केवल किसके द्वारा निर्धारित की जा सकती है?","optionsHi":["राज्य विधानमंडल","राज्यपाल","संसद","राज्य लोक सेवा आयोग"],"explanationHi":"अनुच्छेद 16(3) केवल संसद को किसी राज्य में नियोजन के लिए निवास की शर्त निर्धारित करने देता है; अनुच्छेद 35 इसे पुष्ट करता है कि ऐसे कानून केवल संसद के लिए हैं, राज्य विधानमंडलों के लिए नहीं।"},
  {"id":"polity-fundamental-rights-65","question":"Under Article 35, the power to make laws to give effect to provisions such as Articles 16(3), 32(3), 33 and 34 is vested in:","options":["Parliament only","State Legislatures only","Both Parliament and State Legislatures","The President by order"],"answer":0,"explanation":"Article 35 gives this power exclusively to Parliament so that there is uniformity across India; State legislatures cannot legislate on these matters.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 35 के अंतर्गत अनुच्छेद 16(3), 32(3), 33 और 34 जैसे उपबंधों को प्रभावी बनाने वाले कानून बनाने की शक्ति किसमें निहित है?","optionsHi":["केवल संसद में","केवल राज्य विधानमंडलों में","संसद और राज्य विधानमंडल दोनों में","राष्ट्रपति में, आदेश द्वारा"],"explanationHi":"अनुच्छेद 35 यह शक्ति केवल संसद को देता है ताकि पूरे भारत में एकरूपता रहे; राज्य विधानमंडल इन विषयों पर कानून नहीं बना सकते।"},
  {"id":"polity-fundamental-rights-66","question":"Article 34 allows Parliament, by law, to indemnify any government servant for acts done to restore order in an area where:","options":["A National Emergency is in force","Martial law was in force","President’s Rule is in force","An area is declared disturbed under AFSPA"],"answer":1,"explanation":"Article 34 deals with restriction of rights while martial law is in force, and lets Parliament indemnify acts done in connection with it. The Constitution does not define martial law.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"अनुच्छेद 34 संसद को किसी ऐसे क्षेत्र में, जहाँ व्यवस्था बहाल करने के लिए किए गए कार्यों के संबंध में, किसी सरकारी सेवक को कानून द्वारा क्षतिपूर्ति देने की अनुमति देता है, जहाँ:","optionsHi":["राष्ट्रीय आपातकाल लागू है","सैनिक शासन लागू था","राष्ट्रपति शासन लागू है","कोई क्षेत्र AFSPA के अंतर्गत अशांत घोषित है"],"explanationHi":"अनुच्छेद 34 सैनिक शासन लागू रहने के दौरान अधिकारों के निर्बंधन से संबंधित है, और संसद को उससे जुड़े कार्यों की क्षतिपूर्ति करने देता है। संविधान सैनिक शासन को परिभाषित नहीं करता।"},
  {"id":"polity-fundamental-rights-67","question":"In Indra Sawhney v. Union of India (1992), the Supreme Court upheld 27% reservation for OBCs subject to which conditions?","options":["Exclusion of the creamy layer and an overall ceiling of 50%","Reservation in promotions and no fixed ceiling on the total","A 60% ceiling and identification on economic criteria alone","Reservation confined to backward classes among Hindus only"],"answer":0,"explanation":"The nine-judge bench required the creamy layer to be excluded, set a normal 50% ceiling and held that Article 16(4) does not permit reservation in promotions (later restored for SCs/STs by the 77th Amendment).","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"इंद्रा साहनी बनाम भारत संघ (1992) में सर्वोच्च न्यायालय ने OBC के लिए 27% आरक्षण को किन शर्तों के अधीन बरकरार रखा?","optionsHi":["क्रीमी लेयर का अपवर्जन और कुल 50% की सीमा","पदोन्नति में आरक्षण और कुल पर कोई निश्चित सीमा नहीं","60% की सीमा और केवल आर्थिक मानदंडों पर पहचान","आरक्षण केवल हिंदुओं के पिछड़े वर्गों तक सीमित"],"explanationHi":"नौ न्यायाधीशों की पीठ ने क्रीमी लेयर को बाहर रखना आवश्यक किया, सामान्यतः 50% की सीमा तय की और माना कि अनुच्छेद 16(4) पदोन्नति में आरक्षण की अनुमति नहीं देता (जो बाद में 77वें संशोधन द्वारा अनुसूचित जातियों/जनजातियों के लिए बहाल हुआ)।"},
  {"id":"polity-fundamental-rights-68","question":"The right to a speedy trial was first recognised as part of Article 21 in:","options":["Hussainara Khatoon v. State of Bihar (1979)","Olga Tellis v. Bombay Municipal Corporation (1985)","Maneka Gandhi v. Union of India (1978)","Sunil Batra v. Delhi Administration (1978)"],"answer":0,"explanation":"Hussainara Khatoon, a PIL on undertrial prisoners in Bihar, held speedy trial to be implicit in Article 21. Olga Tellis concerned pavement dwellers and the right to livelihood.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"त्वरित विचारण का अधिकार अनुच्छेद 21 के भाग के रूप में पहली बार किस मामले में मान्य हुआ?","optionsHi":["हुसैनारा खातून बनाम बिहार राज्य (1979)","ओल्गा टेलिस बनाम बॉम्बे म्युनिसिपल कॉर्पोरेशन (1985)","मेनका गांधी बनाम भारत संघ (1978)","सुनील बत्रा बनाम दिल्ली प्रशासन (1978)"],"explanationHi":"बिहार के विचाराधीन कैदियों पर जनहित याचिका हुसैनारा खातून ने त्वरित विचारण को अनुच्छेद 21 में निहित माना। ओल्गा टेलिस फुटपाथ निवासियों और आजीविका के अधिकार से संबंधित था।"},
  {"id":"polity-fundamental-rights-69","question":"The Supreme Court held that the right to livelihood is part of the right to life under Article 21 in a case brought by pavement dwellers of Bombay. The case is:","options":["M. C. Mehta v. Union of India","Olga Tellis v. Bombay Municipal Corporation","Vishaka v. State of Rajasthan","Francis Coralie Mullin v. Administrator, Delhi"],"answer":1,"explanation":"Olga Tellis (1985) held that eviction deprives a person of livelihood and therefore engages Article 21, though it allowed eviction after fair procedure. Vishaka (1997) laid down guidelines on sexual harassment at work.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"सर्वोच्च न्यायालय ने बंबई के फुटपाथ निवासियों द्वारा लाए गए मामले में माना कि आजीविका का अधिकार अनुच्छेद 21 के अंतर्गत जीवन के अधिकार का भाग है। वह मामला कौन-सा है?","optionsHi":["एम. सी. मेहता बनाम भारत संघ","ओल्गा टेलिस बनाम बॉम्बे म्युनिसिपल कॉर्पोरेशन","विशाखा बनाम राजस्थान राज्य","फ्रांसिस कोरालि मुलिन बनाम प्रशासक, दिल्ली"],"explanationHi":"ओल्गा टेलिस (1985) ने माना कि बेदखली व्यक्ति को आजीविका से वंचित करती है और इसलिए अनुच्छेद 21 को आकर्षित करती है, यद्यपि उसने उचित प्रक्रिया के बाद बेदखली की अनुमति दी। विशाखा (1997) ने कार्यस्थल पर यौन उत्पीड़न पर दिशानिर्देश दिए।"},
  {"id":"polity-fundamental-rights-70","question":"Which of these has been held by the Supreme Court NOT to be “State” under Article 12?","options":["Life Insurance Corporation of India","Oil and Natural Gas Corporation Ltd","A municipal corporation of a large city","Board of Control for Cricket in India"],"answer":3,"explanation":"In Zee Telefilms v. Union of India (2005) the Court held the BCCI is not “State” since it is not financially, functionally or administratively controlled by the government; it remains subject to writs under Article 226 for public functions. Statutory corporations such as LIC and ONGC are State.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"सर्वोच्च न्यायालय ने इनमें से किसे अनुच्छेद 12 के अंतर्गत “राज्य” नहीं माना है?","optionsHi":["भारतीय जीवन बीमा निगम","तेल और प्राकृतिक गैस निगम लिमिटेड","किसी बड़े शहर का नगर निगम","भारतीय क्रिकेट नियंत्रण बोर्ड"],"explanationHi":"ज़ी टेलीफिल्म्स बनाम भारत संघ (2005) में न्यायालय ने माना कि BCCI “राज्य” नहीं है क्योंकि वह वित्तीय, कार्यात्मक या प्रशासनिक रूप से सरकार के नियंत्रण में नहीं है; सार्वजनिक कार्यों के लिए वह अनुच्छेद 226 के अंतर्गत रिटों के अधीन रहता है। LIC और ONGC जैसे सांविधिक निगम राज्य हैं।"},
  {"id":"polity-fundamental-rights-71","question":"Match the case with what it decided: A. Shreya Singhal (2015) B. Navtej Singh Johar (2018) C. Selvi v. State of Karnataka (2010) D. Shayara Bano (2017). 1. Instant triple talaq is unconstitutional 2. Section 66A of the IT Act struck down 3. Consensual same-sex relations between adults decriminalised 4. Involuntary narco-analysis violates Article 20(3)","options":["A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1","A-4, B-3, C-2, D-1"],"answer":2,"explanation":"Shreya Singhal struck down Section 66A as violating Article 19(1)(a); Navtej Johar read down Section 377 IPC; Selvi held compulsory narco tests violate the right against self-incrimination; Shayara Bano invalidated talaq-e-biddat.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"मामले का उसके निर्णय से मिलान कीजिए: A. श्रेया सिंघल (2015) B. नवतेज सिंह जौहर (2018) C. सेल्वी बनाम कर्नाटक राज्य (2010) D. शायरा बानो (2017)। 1. तत्काल तीन तलाक असंवैधानिक है 2. सूचना प्रौद्योगिकी अधिनियम की धारा 66A रद्द 3. वयस्कों के बीच सहमति से समलैंगिक संबंध अपराध-मुक्त 4. अनैच्छिक नार्को-विश्लेषण अनुच्छेद 20(3) का उल्लंघन है","optionsHi":["A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1","A-4, B-3, C-2, D-1"],"explanationHi":"श्रेया सिंघल ने धारा 66A को अनुच्छेद 19(1)(a) का उल्लंघन मानकर रद्द किया; नवतेज जौहर ने भारतीय दंड संहिता की धारा 377 को सीमित किया; सेल्वी ने माना कि अनिवार्य नार्को परीक्षण आत्म-अभिशंसन के विरुद्ध अधिकार का उल्लंघन है; शायरा बानो ने तलाक-ए-बिद्दत को अमान्य किया।"},
  {"id":"polity-fundamental-rights-72","question":"How many of these statements about Article 22 are correct? I. An arrested person must be informed of the grounds of arrest as soon as may be. II. An arrested person has the right to consult and be defended by a legal practitioner of choice. III. An arrested person must be produced before a magistrate within 24 hours. IV. These three safeguards apply equally to a person held under a preventive detention law.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct under Article 22(1) and (2). IV is wrong: Article 22(3) expressly excludes enemy aliens and persons under preventive detention from these safeguards; detainees get the separate protections of 22(4)–(7).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 22 के बारे में इनमें से कितने कथन सही हैं? I. गिरफ्तार व्यक्ति को यथाशीघ्र गिरफ्तारी के आधार बताए जाने चाहिए। II. गिरफ्तार व्यक्ति को अपनी पसंद के विधि व्यवसायी से परामर्श करने और प्रतिरक्षा कराने का अधिकार है। III. गिरफ्तार व्यक्ति को 24 घंटे के भीतर मजिस्ट्रेट के समक्ष पेश किया जाना चाहिए। IV. ये तीनों रक्षोपाय निवारक निरोध कानून के अंतर्गत निरुद्ध व्यक्ति पर समान रूप से लागू होते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III अनुच्छेद 22(1) और (2) के अंतर्गत सही हैं। IV गलत है: अनुच्छेद 22(3) शत्रु विदेशियों और निवारक निरोध में निरुद्ध व्यक्तियों को इन रक्षोपायों से स्पष्ट रूप से बाहर रखता है; निरुद्धों को 22(4)–(7) के अलग संरक्षण मिलते हैं।"},
  {"id":"polity-fundamental-rights-73","question":"Assertion (A): The freedoms under Article 19 are automatically suspended when a National Emergency is proclaimed on the ground of armed rebellion. Reason (R): After the 44th Amendment, Article 358 suspends Article 19 only when the Emergency is declared on the ground of war or external aggression.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"A is false and R is true. Since 1978, Article 358 applies only to an external Emergency (war or external aggression); an Emergency on the ground of armed rebellion does not automatically suspend Article 19.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): सशस्त्र विद्रोह के आधार पर राष्ट्रीय आपातकाल की उद्घोषणा होने पर अनुच्छेद 19 की स्वतंत्रताएँ स्वतः निलंबित हो जाती हैं। कारण (R): 44वें संशोधन के बाद अनुच्छेद 358 अनुच्छेद 19 को तभी निलंबित करता है जब आपातकाल युद्ध या बाह्य आक्रमण के आधार पर घोषित हो।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"A असत्य है और R सत्य है। 1978 से अनुच्छेद 358 केवल बाह्य आपातकाल (युद्ध या बाह्य आक्रमण) पर लागू होता है; सशस्त्र विद्रोह के आधार पर आपातकाल अनुच्छेद 19 को स्वतः निलंबित नहीं करता।"},
  {"id":"polity-fundamental-rights-74","question":"Arrange these cases on Parliament’s power to amend Fundamental Rights in chronological order: 1. Golaknath 2. Shankari Prasad 3. Sajjan Singh 4. Kesavananda Bharati","options":["2, 1, 3, 4","2, 3, 1, 4","3, 2, 1, 4","2, 3, 4, 1"],"answer":1,"explanation":"Shankari Prasad (1951) and Sajjan Singh (1965) upheld Parliament’s power to amend Fundamental Rights; Golaknath (1967) denied it; Kesavananda Bharati (1973) restored it subject to the basic structure.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"मौलिक अधिकारों में संशोधन की संसद की शक्ति पर इन मामलों को कालानुक्रम में व्यवस्थित कीजिए: 1. गोलकनाथ 2. शंकरी प्रसाद 3. सज्जन सिंह 4. केशवानंद भारती","optionsHi":["2, 1, 3, 4","2, 3, 1, 4","3, 2, 1, 4","2, 3, 4, 1"],"explanationHi":"शंकरी प्रसाद (1951) और सज्जन सिंह (1965) ने मौलिक अधिकारों में संशोधन की संसद की शक्ति को बरकरार रखा; गोलकनाथ (1967) ने इसे अस्वीकार किया; केशवानंद भारती (1973) ने इसे मूल ढाँचे की शर्त के साथ बहाल किया।"},
  {"id":"polity-fundamental-rights-75","question":"How many of these statements about Article 30 are correct? I. Minority status for Article 30 is determined State-wise, as held in T. M. A. Pai Foundation (2002). II. Article 30(1A), on compensation when the property of a minority institution is acquired, was added by the 44th Amendment. III. The State cannot discriminate against a minority institution while granting aid. IV. Article 30 is available to both religious and linguistic minorities.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: TMA Pai (2002) made minority status State-wise, Article 30(1A) came from the 44th Amendment, Article 30(2) bars discrimination in aid, and Article 30(1) covers minorities based on religion or language.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 30 के बारे में इनमें से कितने कथन सही हैं? I. अनुच्छेद 30 के लिए अल्पसंख्यक दर्जा राज्य-दर-राज्य निर्धारित होता है, जैसा टी. एम. ए. पाई फाउंडेशन (2002) में माना गया। II. अल्पसंख्यक संस्था की संपत्ति के अधिग्रहण पर प्रतिकर संबंधी अनुच्छेद 30(1A) 44वें संशोधन द्वारा जोड़ा गया। III. सहायता देते समय राज्य अल्पसंख्यक संस्था के साथ भेदभाव नहीं कर सकता। IV. अनुच्छेद 30 धार्मिक और भाषायी दोनों अल्पसंख्यकों को उपलब्ध है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार सही हैं: टी. एम. ए. पाई (2002) ने अल्पसंख्यक दर्जा राज्य-वार बनाया, अनुच्छेद 30(1A) 44वें संशोधन से आया, अनुच्छेद 30(2) सहायता में भेदभाव को वर्जित करता है, और अनुच्छेद 30(1) धर्म या भाषा पर आधारित अल्पसंख्यकों को कवर करता है।"},
  {"id":"polity-fundamental-rights-76","question":"How many of these are grounds on which reasonable restrictions may be imposed on freedom of speech and expression under Article 19(2)? I. Contempt of court II. Defamation III. Protection of the interests of any Scheduled Tribe IV. Interests of the general public","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are grounds in Article 19(2). Protection of Scheduled Tribes' interests is a ground under Article 19(5) for movement and residence, and interests of the general public is a ground under Articles 19(5) and 19(6), not for speech.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने ऐसे आधार हैं जिन पर अनुच्छेद 19(2) के अंतर्गत वाक् और अभिव्यक्ति की स्वतंत्रता पर युक्तियुक्त निर्बंधन लगाए जा सकते हैं? I. न्यायालय की अवमानना II. मानहानि III. किसी अनुसूचित जनजाति के हितों का संरक्षण IV. सामान्य जनता के हित","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II अनुच्छेद 19(2) के आधार हैं। अनुसूचित जनजातियों के हितों का संरक्षण संचरण और निवास संबंधी अनुच्छेद 19(5) के अंतर्गत आधार है, और सामान्य जनता के हित अनुच्छेद 19(5) और 19(6) के अंतर्गत आधार हैं, वाक् के लिए नहीं।"},
  {"id":"polity-fundamental-rights-77","question":"How many of these statements about Article 17 are correct? I. The Untouchability (Offences) Act, 1955 was renamed the Protection of Civil Rights Act in 1976. II. The Constitution does not define “untouchability”. III. The SC and ST (Prevention of Atrocities) Act was enacted in 1989. IV. The right under Article 17 is absolute and not subject to any exception.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Article 17 abolishes untouchability and forbids its practice in any form, without exceptions, and leaves the term undefined; Parliament has enforced it through the 1955 (renamed 1976) and 1989 Acts.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अनुच्छेद 17 के बारे में इनमें से कितने कथन सही हैं? I. अस्पृश्यता (अपराध) अधिनियम, 1955 का नाम 1976 में बदलकर नागरिक अधिकार संरक्षण अधिनियम रखा गया। II. संविधान “अस्पृश्यता” को परिभाषित नहीं करता। III. अनुसूचित जाति और जनजाति (अत्याचार निवारण) अधिनियम 1989 में बना। IV. अनुच्छेद 17 का अधिकार निरपेक्ष है और किसी अपवाद के अधीन नहीं है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार सही हैं। अनुच्छेद 17 अस्पृश्यता का अंत करता है और किसी भी रूप में इसके आचरण को बिना अपवाद वर्जित करता है, और पद को अपरिभाषित छोड़ता है; संसद ने इसे 1955 (1976 में नाम बदला) और 1989 के अधिनियमों द्वारा प्रवर्तित किया है।"},
  {"id":"polity-fundamental-rights-78","question":"How many of these statements about Articles 15 and 16 are correct? I. Article 15(1) bars discrimination on grounds only of religion, race, caste, sex or place of birth. II. Article 16(2) additionally lists descent and residence as forbidden grounds in public employment. III. Article 15(2) applies to access to shops, hotels and places of public entertainment, even when privately owned. IV. Article 16(5) permits an office connected with a religious institution to be reserved for members of that religion.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Descent and residence appear in Article 16(2) but not in Article 15(1), a frequent trap; 15(2) binds private persons too.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 15 और 16 के बारे में इनमें से कितने कथन सही हैं? I. अनुच्छेद 15(1) केवल धर्म, मूलवंश, जाति, लिंग या जन्मस्थान के आधार पर विभेद को वर्जित करता है। II. अनुच्छेद 16(2) लोक नियोजन में वर्जित आधारों के रूप में वंश और निवास को भी सूचीबद्ध करता है। III. अनुच्छेद 15(2) दुकानों, होटलों और सार्वजनिक मनोरंजन के स्थानों तक पहुँच पर लागू होता है, भले ही वे निजी स्वामित्व के हों। IV. अनुच्छेद 16(5) किसी धार्मिक संस्था से संबंधित पद को उस धर्म के सदस्यों के लिए आरक्षित करने की अनुमति देता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार सही हैं। वंश और निवास अनुच्छेद 16(2) में हैं, अनुच्छेद 15(1) में नहीं, जो एक बार-बार आने वाला भ्रम है; 15(2) निजी व्यक्तियों पर भी बाध्यकारी है।"},
  {"id":"polity-fundamental-rights-79","question":"Assertion (A): The protection against double jeopardy under Article 20(2) does not bar departmental proceedings after a criminal prosecution for the same act. Reason (R): Article 20(2) applies only where the person has been prosecuted and punished before a court or judicial tribunal.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. As held in Maqbool Hussain (1953), departmental or administrative proceedings are not prosecution and punishment by a court, so Article 20(2) does not apply to them.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): अनुच्छेद 20(2) के अंतर्गत दोहरे दंड से संरक्षण एक ही कृत्य के लिए आपराधिक अभियोजन के बाद विभागीय कार्यवाही को नहीं रोकता। कारण (R): अनुच्छेद 20(2) केवल वहाँ लागू होता है जहाँ व्यक्ति को न्यायालय या न्यायिक अधिकरण के समक्ष अभियोजित और दंडित किया गया हो।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है। जैसा मकबूल हुसैन (1953) में माना गया, विभागीय या प्रशासनिक कार्यवाही न्यायालय द्वारा अभियोजन और दंड नहीं है, इसलिए अनुच्छेद 20(2) उन पर लागू नहीं होता।"},
  {"id":"polity-fundamental-rights-80","question":"Arrange these insertions into Part III in chronological order: 1. Article 15(4) for backward classes 2. Article 16(4A) for reservation in promotions 3. The right to form co-operative societies in Article 19(1)(c) 4. Article 21A","options":["1, 2, 4, 3","1, 4, 2, 3","2, 1, 4, 3","1, 2, 3, 4"],"answer":0,"explanation":"Article 15(4): 1st Amendment, 1951. Article 16(4A): 77th Amendment, 1995. Article 21A: 86th Amendment, 2002. Co-operative societies: 97th Amendment, 2011.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"भाग III में इन अंतःस्थापनों को कालानुक्रम में व्यवस्थित कीजिए: 1. पिछड़े वर्गों के लिए अनुच्छेद 15(4) 2. पदोन्नति में आरक्षण के लिए अनुच्छेद 16(4A) 3. अनुच्छेद 19(1)(c) में सहकारी समितियाँ बनाने का अधिकार 4. अनुच्छेद 21A","optionsHi":["1, 2, 4, 3","1, 4, 2, 3","2, 1, 4, 3","1, 2, 3, 4"],"explanationHi":"अनुच्छेद 15(4): पहला संशोधन, 1951। अनुच्छेद 16(4A): 77वाँ संशोधन, 1995। अनुच्छेद 21A: 86वाँ संशोधन, 2002। सहकारी समितियाँ: 97वाँ संशोधन, 2011।"},
  {"id":"polity-fundamental-rights-81","question":"Which of these Fundamental Rights is available ONLY to citizens and not to foreigners?","options":["Article 20 – protection in respect of conviction for offences","Article 22 – protection against arbitrary arrest","Article 25 – freedom of religion","Article 16 – equality of opportunity in public employment"],"answer":3,"explanation":"Articles 15, 16, 19, 29 and 30 are confined to citizens. Articles 20, 21, 22 and 25 extend to all persons, though Article 22’s safeguards do not apply to enemy aliens.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"इनमें से कौन-सा मौलिक अधिकार केवल नागरिकों को उपलब्ध है, विदेशियों को नहीं?","optionsHi":["अनुच्छेद 20 – अपराधों के लिए दोषसिद्धि के संबंध में संरक्षण","अनुच्छेद 22 – मनमानी गिरफ्तारी से संरक्षण","अनुच्छेद 25 – धर्म की स्वतंत्रता","अनुच्छेद 16 – लोक नियोजन में अवसर की समता"],"explanationHi":"अनुच्छेद 15, 16, 19, 29 और 30 नागरिकों तक सीमित हैं। अनुच्छेद 20, 21, 22 और 25 सभी व्यक्तियों तक बढ़ते हैं, यद्यपि अनुच्छेद 22 के रक्षोपाय शत्रु विदेशियों पर लागू नहीं होते।"},
  {"id":"polity-fundamental-rights-82","question":"The phrase \"equal protection of the laws\" in Article 14 is drawn from the Constitution of:","options":["Britain","USA","Ireland","Canada"],"answer":1,"explanation":"Article 14 combines \"equality before the law\", a British idea (a negative concept: no special privileges), with \"equal protection of the laws\", taken from the 14th Amendment of the US Constitution (a positive concept: like treatment in like circumstances).","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"अनुच्छेद 14 में “विधियों का समान संरक्षण” पदावली किस देश के संविधान से ली गई है?","optionsHi":["ब्रिटेन","अमेरिका","आयरलैंड","कनाडा"],"explanationHi":"अनुच्छेद 14 “विधि के समक्ष समता”, जो ब्रिटिश विचार है (नकारात्मक अवधारणा: कोई विशेषाधिकार नहीं), को “विधियों के समान संरक्षण”, जो अमेरिकी संविधान के 14वें संशोधन से लिया गया है (सकारात्मक अवधारणा: समान परिस्थितियों में समान व्यवहार), के साथ जोड़ता है।"},
  {"id":"polity-fundamental-rights-83","question":"The right to vote in elections to the Lok Sabha and State Assemblies is a:","options":["A Fundamental Right under Article 21","A Fundamental Right guaranteed by Article 326","A Fundamental Duty under Article 51A","A constitutional and statutory right only"],"answer":3,"explanation":"Article 326 provides for adult suffrage, and the details are in the Representation of the People Act, 1951. Voting is therefore a constitutional and statutory right, not a Fundamental Right, as the Supreme Court has held several times (for example in Kuldip Nayar, 2006).","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"लोकसभा और राज्य विधानसभाओं के चुनावों में मतदान का अधिकार क्या है?","optionsHi":["अनुच्छेद 21 के अंतर्गत मौलिक अधिकार","अनुच्छेद 326 द्वारा प्रत्याभूत मौलिक अधिकार","अनुच्छेद 51A के अंतर्गत मौलिक कर्तव्य","केवल संवैधानिक और सांविधिक अधिकार"],"explanationHi":"अनुच्छेद 326 वयस्क मताधिकार का प्रावधान करता है, और ब्योरे लोक प्रतिनिधित्व अधिनियम, 1951 में हैं। इसलिए मतदान संवैधानिक और सांविधिक अधिकार है, मौलिक अधिकार नहीं, जैसा सर्वोच्च न्यायालय ने कई बार माना है (उदाहरण के लिए कुलदीप नायर, 2006)।"},
  {"id":"polity-fundamental-rights-84","question":"Freedom of the press is not mentioned in so many words in the Constitution. The Supreme Court has held it to be part of:","options":["Article 19(1)(a)","Article 14","Article 19(1)(g)","Article 21"],"answer":0,"explanation":"Freedom of the press is implied in the freedom of speech and expression under Article 19(1)(a), as the Court held from Romesh Thappar and Brij Bhushan (1950) onwards. Article 19(1)(g), the freedom of trade or business, is the tempting wrong option.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"संविधान में प्रेस की स्वतंत्रता का स्पष्ट शब्दों में उल्लेख नहीं है। सर्वोच्च न्यायालय ने इसे किसका भाग माना है?","optionsHi":["अनुच्छेद 19(1)(a)","अनुच्छेद 14","अनुच्छेद 19(1)(g)","अनुच्छेद 21"],"explanationHi":"प्रेस की स्वतंत्रता अनुच्छेद 19(1)(a) के अंतर्गत वाक् और अभिव्यक्ति की स्वतंत्रता में निहित है, जैसा रोमेश थापर और ब्रज भूषण (1950) से न्यायालय मानता आया है। अनुच्छेद 19(1)(g), व्यापार या कारोबार की स्वतंत्रता, भ्रमित करने वाला गलत विकल्प है।"},
  {"id":"polity-fundamental-rights-85","question":"Under Explanation II to Article 25, the reference to \"Hindus\" in Article 25(2)(b) includes persons professing which religions?","options":["Sikh, Jaina or Parsi","Sikh, Jaina or Buddhist","Buddhist, Jaina or Parsi","Sikh, Buddhist or Christian"],"answer":1,"explanation":"Explanation II says the reference to Hindus includes persons professing the Sikh, Jaina or Buddhist religion, and that Hindu religious institutions are to be read the same way. This matters for laws throwing open Hindu religious institutions to all classes.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 25 के स्पष्टीकरण II के अनुसार, अनुच्छेद 25(2)(b) में “हिंदुओं” के उल्लेख में किन धर्मों को मानने वाले व्यक्ति शामिल हैं?","optionsHi":["सिख, जैन या पारसी","सिख, जैन या बौद्ध","बौद्ध, जैन या पारसी","सिख, बौद्ध या ईसाई"],"explanationHi":"स्पष्टीकरण II कहता है कि हिंदुओं के उल्लेख में सिख, जैन या बौद्ध धर्म को मानने वाले व्यक्ति शामिल हैं, और हिंदू धार्मिक संस्थाओं को भी इसी प्रकार पढ़ा जाना है। यह हिंदू धार्मिक संस्थाओं को सभी वर्गों के लिए खोलने वाले कानूनों के लिए महत्वपूर्ण है।"},
  {"id":"polity-fundamental-rights-86","question":"Article 19(1)(b) guarantees citizens the right to assemble. Which two conditions are written into the clause itself?","options":["Peaceably and without arms","With police permission and in daylight","In public places and with prior notice","Without arms and for lawful purposes only"],"answer":0,"explanation":"The clause reads \"to assemble peaceably and without arms\". Other limits, such as public order and the sovereignty and integrity of India, come through Article 19(3), not through the clause itself.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"अनुच्छेद 19(1)(b) नागरिकों को सम्मेलन करने का अधिकार देता है। खंड में ही कौन-सी दो शर्तें लिखी हैं?","optionsHi":["शांतिपूर्वक और बिना शस्त्रों के","पुलिस की अनुमति से और दिन के उजाले में","सार्वजनिक स्थानों पर और पूर्व सूचना के साथ","बिना शस्त्रों के और केवल वैध प्रयोजनों के लिए"],"explanationHi":"खंड कहता है “शांतिपूर्वक और निरायुध सम्मेलन करना”। लोक व्यवस्था और भारत की प्रभुता व अखंडता जैसी अन्य सीमाएँ अनुच्छेद 19(3) से आती हैं, खंड से स्वयं नहीं।"},
  {"id":"polity-fundamental-rights-87","question":"The concept of \"rule of law\", which is reflected in \"equality before the law\" in Article 14, was propounded by:","options":["Ivor Jennings","Ernest Barker","K. C. Wheare","A. V. Dicey"],"answer":3,"explanation":"A. V. Dicey set out the rule of law with three parts: no arbitrary power, equality before the law, and the primacy of individual rights. The Supreme Court has held the rule of law to be a basic feature of the Constitution.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"“विधि का शासन” की अवधारणा, जो अनुच्छेद 14 में “विधि के समक्ष समता” में परिलक्षित होती है, किसने प्रतिपादित की?","optionsHi":["आइवर जेनिंग्स","अर्नेस्ट बार्कर","के. सी. व्हीयर","ए. वी. डायसी"],"explanationHi":"ए. वी. डायसी ने विधि के शासन को तीन भागों में रखा: मनमानी शक्ति का अभाव, विधि के समक्ष समता, और व्यक्तिगत अधिकारों की प्रधानता। सर्वोच्च न्यायालय ने विधि के शासन को संविधान की मूल विशेषता माना है।"},
  {"id":"polity-fundamental-rights-88","question":"The Vishaka guidelines (1997) on sexual harassment of women at the workplace, based on Articles 14, 15, 19(1)(g) and 21, were later replaced by a law passed in:","options":["2005","2013","2010","2019"],"answer":1,"explanation":"The Sexual Harassment of Women at Workplace (Prevention, Prohibition and Redressal) Act, 2013 (the POSH Act) gave statutory form to the Vishaka guidelines, including Internal Complaints Committees.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"कार्यस्थल पर महिलाओं के यौन उत्पीड़न पर विशाखा दिशानिर्देश (1997), जो अनुच्छेद 14, 15, 19(1)(g) और 21 पर आधारित थे, बाद में किस वर्ष पारित कानून से प्रतिस्थापित हुए?","optionsHi":["2005","2013","2010","2019"],"explanationHi":"कार्यस्थल पर महिलाओं का यौन उत्पीड़न (निवारण, प्रतिषेध और प्रतितोष) अधिनियम, 2013 (POSH अधिनियम) ने आंतरिक शिकायत समितियों सहित विशाखा दिशानिर्देशों को सांविधिक रूप दिया।"},
  {"id":"polity-fundamental-rights-89","question":"In Bijoe Emmanuel v. State of Kerala (1986), the Supreme Court protected schoolchildren who stood respectfully but did not sing the National Anthem because of their faith. Their right was upheld under:","options":["Articles 14 and 15(1)","Articles 21 and 28(3)","Articles 19(1)(a) and 25","Articles 29(1) and 30(1)"],"answer":2,"explanation":"The Court held that the freedom of speech in Article 19(1)(a) includes the freedom to remain silent, and that expelling the Jehovah's Witness children also violated their freedom of religion under Article 25. Article 28(3) is about compelled attendance at religious instruction, not the anthem.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"बिजॉय इमैनुएल बनाम केरल राज्य (1986) में सर्वोच्च न्यायालय ने उन स्कूली बच्चों की रक्षा की जो अपनी आस्था के कारण राष्ट्रगान गाते नहीं थे, पर सम्मान से खड़े रहते थे। उनका अधिकार किसके अंतर्गत बरकरार रखा गया?","optionsHi":["अनुच्छेद 14 और 15(1)","अनुच्छेद 21 और 28(3)","अनुच्छेद 19(1)(a) और 25","अनुच्छेद 29(1) और 30(1)"],"explanationHi":"न्यायालय ने माना कि अनुच्छेद 19(1)(a) की वाक्-स्वतंत्रता में चुप रहने की स्वतंत्रता शामिल है, और यहोवा के साक्षी बच्चों का निष्कासन अनुच्छेद 25 के अंतर्गत उनकी धर्म की स्वतंत्रता का भी उल्लंघन था। अनुच्छेद 28(3) धार्मिक शिक्षा में अनिवार्य उपस्थिति के बारे में है, राष्ट्रगान के बारे में नहीं।"},
  {"id":"polity-fundamental-rights-90","question":"In National Legal Services Authority v. Union of India (2014), the Supreme Court:","options":["Recognised transgender persons as a third gender","Decriminalised consensual same-sex relations between adults","Struck down the practice of instant triple talaq","Declared the right to privacy a fundamental right"],"answer":0,"explanation":"NALSA (2014) recognised transgender persons as a third gender entitled to rights under Articles 14, 15, 16, 19 and 21. Section 377 was read down in Navtej Singh Johar (2018), and privacy came in Puttaswamy (2017).","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"नेशनल लीगल सर्विसेज अथॉरिटी बनाम भारत संघ (2014) में सर्वोच्च न्यायालय ने:","optionsHi":["ट्रांसजेंडर व्यक्तियों को तीसरे लिंग के रूप में मान्यता दी","वयस्कों के बीच सहमति से समलैंगिक संबंधों को अपराध-मुक्त किया","तत्काल तीन तलाक की प्रथा को रद्द किया","निजता के अधिकार को मौलिक अधिकार घोषित किया"],"explanationHi":"NALSA (2014) ने ट्रांसजेंडर व्यक्तियों को तीसरे लिंग के रूप में मान्यता दी जो अनुच्छेद 14, 15, 16, 19 और 21 के अंतर्गत अधिकारों के हकदार हैं। धारा 377 को नवतेज सिंह जौहर (2018) में सीमित किया गया, और निजता पुट्टस्वामी (2017) में आई।"},
  {"id":"polity-fundamental-rights-91","question":"Under Article 18(3), a person who is NOT a citizen of India but holds an office of profit or trust under the State can accept a title from a foreign State only with the consent of:","options":["The Prime Minister","Parliament","The President","The Ministry of External Affairs"],"answer":2,"explanation":"Article 18(2) flatly bars citizens from accepting foreign titles. Article 18(3) lets a non-citizen holding an office of profit or trust under the State accept one only with the President's consent, and Article 18(4) applies the same rule to presents and emoluments.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 18(3) के अंतर्गत, भारत का नागरिक न होने पर भी राज्य के अधीन लाभ या विश्वास का पद धारण करने वाला व्यक्ति किसी विदेशी राज्य से उपाधि केवल किसकी सहमति से स्वीकार कर सकता है?","optionsHi":["प्रधानमंत्री","संसद","राष्ट्रपति","विदेश मंत्रालय"],"explanationHi":"अनुच्छेद 18(2) नागरिकों को विदेशी उपाधियाँ स्वीकार करने से पूरी तरह रोकता है। अनुच्छेद 18(3) राज्य के अधीन लाभ या विश्वास का पद धारण करने वाले गैर-नागरिक को राष्ट्रपति की सहमति से ही उपाधि स्वीकार करने देता है, और अनुच्छेद 18(4) यही नियम भेंट और उपलब्धियों पर लागू करता है।"},
  {"id":"polity-fundamental-rights-92","question":"The Supreme Court upheld freedom of the press against a ban on a journal's entry into Madras State in a 1950 case, which led Parliament to add \"public order\" to Article 19(2) through the 1st Amendment. The case is:","options":["A. K. Gopalan v. State of Madras","Romesh Thappar v. State of Madras","State of Madras v. Champakam Dorairajan","Kharak Singh v. State of U.P."],"answer":1,"explanation":"In Romesh Thappar (1950) the ban on the journal \"Cross Roads\" was struck down because \"public order\" was not then a ground in Article 19(2). The 1st Amendment (1951) added public order, friendly relations with foreign States and incitement to an offence. Champakam Dorairajan led to Article 15(4).","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"सर्वोच्च न्यायालय ने 1950 के एक मामले में, जिसमें एक पत्रिका के मद्रास राज्य में प्रवेश पर प्रतिबंध था, प्रेस की स्वतंत्रता को बरकरार रखा, जिसके कारण संसद ने पहले संशोधन द्वारा अनुच्छेद 19(2) में “लोक व्यवस्था” जोड़ी। वह मामला कौन-सा है?","optionsHi":["ए. के. गोपालन बनाम मद्रास राज्य","रोमेश थापर बनाम मद्रास राज्य","मद्रास राज्य बनाम चंपकम दोराईराजन","खड़क सिंह बनाम उत्तर प्रदेश राज्य"],"explanationHi":"रोमेश थापर (1950) में पत्रिका “क्रॉस रोड्स” पर प्रतिबंध रद्द हुआ क्योंकि तब “लोक व्यवस्था” अनुच्छेद 19(2) में आधार नहीं थी। पहले संशोधन (1951) ने लोक व्यवस्था, विदेशी राज्यों से मैत्रीपूर्ण संबंध और अपराध-उद्दीपन जोड़े। चंपकम दोराईराजन से अनुच्छेद 15(4) आया।"},
  {"id":"polity-fundamental-rights-93","question":"Which judgment first held that \"equality is antithetic to arbitrariness\", giving Article 14 a meaning beyond reasonable classification?","options":["State of West Bengal v. Anwar Ali Sarkar (1952)","R. C. Cooper v. Union of India (1970)","Indra Sawhney v. Union of India (1992)","E. P. Royappa v. State of Tamil Nadu (1974)"],"answer":3,"explanation":"In E. P. Royappa (1974), Justice Bhagwati wrote that equality and arbitrariness are sworn enemies, so an arbitrary act violates Article 14. Anwar Ali Sarkar (1952) applied the older test of reasonable classification.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"किस निर्णय ने पहली बार माना कि “समता मनमानेपन की विरोधी है”, जिससे अनुच्छेद 14 को युक्तियुक्त वर्गीकरण से परे अर्थ मिला?","optionsHi":["पश्चिम बंगाल राज्य बनाम अनवर अली सरकार (1952)","आर. सी. कूपर बनाम भारत संघ (1970)","इंद्रा साहनी बनाम भारत संघ (1992)","ई. पी. रॉयप्पा बनाम तमिलनाडु राज्य (1974)"],"explanationHi":"ई. पी. रॉयप्पा (1974) में न्यायमूर्ति भगवती ने लिखा कि समता और मनमानापन जन्मजात शत्रु हैं, इसलिए मनमाना कार्य अनुच्छेद 14 का उल्लंघन करता है। अनवर अली सरकार (1952) ने युक्तियुक्त वर्गीकरण की पुरानी कसौटी लागू की थी।"},
  {"id":"polity-fundamental-rights-94","question":"In People's Union for Democratic Rights v. Union of India (1982), about workers on the Asiad construction projects, the Supreme Court held that:","options":["Employing contract labour on public projects is barred by Article 24","Paying below the minimum wage is forced labour under Article 23","Construction workers are entitled to housing plots under Article 39(b)","Article 23 can be enforced only against the State, not contractors"],"answer":1,"explanation":"The Court held that labour given for less than the minimum wage is \"forced labour\" banned by Article 23, since economic need is a form of compulsion. Article 23 also applies against private persons.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"पीपुल्स यूनियन फॉर डेमोक्रेटिक राइट्स बनाम भारत संघ (1982) में, जो एशियाड निर्माण परियोजनाओं के कामगारों से संबंधित था, सर्वोच्च न्यायालय ने माना कि:","optionsHi":["सार्वजनिक परियोजनाओं में ठेका श्रमिकों का नियोजन अनुच्छेद 24 द्वारा वर्जित है","न्यूनतम मजदूरी से कम भुगतान अनुच्छेद 23 के अंतर्गत बलात् श्रम है","निर्माण कामगार अनुच्छेद 39(b) के अंतर्गत आवासीय भूखंडों के हकदार हैं","अनुच्छेद 23 केवल राज्य के विरुद्ध प्रवर्तित हो सकता है, ठेकेदारों के विरुद्ध नहीं"],"explanationHi":"न्यायालय ने माना कि न्यूनतम मजदूरी से कम पर दिया गया श्रम अनुच्छेद 23 द्वारा वर्जित “बलात् श्रम” है, क्योंकि आर्थिक आवश्यकता भी एक प्रकार की विवशता है। अनुच्छेद 23 निजी व्यक्तियों के विरुद्ध भी लागू होता है।"},
  {"id":"polity-fundamental-rights-95","question":"Article 28(1) bars religious instruction in institutions wholly maintained out of State funds. Under Article 28(2), this bar does NOT apply to an institution that:","options":["Is established and administered by a religious minority under Article 30(1)","Gets State grants covering less than half of its annual expenses","Is State-run but founded under a trust that requires religious instruction","Is a university set up by a State Act with a department of theology"],"answer":2,"explanation":"Article 28(2) exempts institutions administered by the State but established under an endowment or trust requiring religious instruction. Under Article 28(3), State-recognised or State-aided institutions may give such instruction, but nobody can be made to attend without consent (or a guardian's consent for a minor).","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 28(1) पूर्णतः राज्य निधि से पोषित संस्थाओं में धार्मिक शिक्षा वर्जित करता है। अनुच्छेद 28(2) के अंतर्गत यह वर्जन किस संस्था पर लागू नहीं होता?","optionsHi":["जो अनुच्छेद 30(1) के अंतर्गत किसी धार्मिक अल्पसंख्यक द्वारा स्थापित और प्रशासित हो","जिसे राज्य अनुदान उसके वार्षिक व्यय के आधे से कम को कवर करते हों","जो राज्य द्वारा संचालित हो परंतु ऐसे न्यास के अधीन स्थापित हो जिसमें धार्मिक शिक्षा आवश्यक हो","जो राज्य अधिनियम से स्थापित विश्वविद्यालय हो जिसमें धर्मशास्त्र विभाग हो"],"explanationHi":"अनुच्छेद 28(2) उन संस्थाओं को छूट देता है जिनका प्रशासन राज्य करता है परंतु जो ऐसे बंदोबस्त या न्यास के अधीन स्थापित हुईं जिसमें धार्मिक शिक्षा आवश्यक है। अनुच्छेद 28(3) के अंतर्गत राज्य-मान्यता प्राप्त या राज्य-सहायता प्राप्त संस्थाएँ ऐसी शिक्षा दे सकती हैं, पर किसी को सहमति के बिना (या अवयस्क के लिए अभिभावक की सहमति के बिना) उपस्थित होने को बाध्य नहीं किया जा सकता।"},
  {"id":"polity-fundamental-rights-96","question":"In Union of India v. Naveen Jindal (2004), the Supreme Court held that the right of a citizen to fly the National Flag with respect and dignity is part of:","options":["Article 21","Article 51A(a) only, and is not enforceable","Article 25","Article 19(1)(a)"],"answer":3,"explanation":"The Court treated flying the flag as an expression of allegiance and pride covered by Article 19(1)(a), subject to reasonable restrictions such as the Flag Code and the Prevention of Insults to National Honour Act, 1971.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"यूनियन ऑफ इंडिया बनाम नवीन जिंदल (2004) में सर्वोच्च न्यायालय ने माना कि नागरिक का राष्ट्रीय ध्वज को सम्मान और गरिमा से फहराने का अधिकार किसका भाग है?","optionsHi":["अनुच्छेद 21","केवल अनुच्छेद 51A(a), और यह प्रवर्तनीय नहीं है","अनुच्छेद 25","अनुच्छेद 19(1)(a)"],"explanationHi":"न्यायालय ने ध्वज फहराने को निष्ठा और गर्व की अभिव्यक्ति माना जो अनुच्छेद 19(1)(a) में आती है, ध्वज संहिता और राष्ट्रीय सम्मान के अपमान की रोकथाम अधिनियम, 1971 जैसे युक्तियुक्त निर्बंधनों के अधीन।"},
  {"id":"polity-fundamental-rights-97","question":"The right of a poor prisoner to free legal aid, including help to file an appeal, was read into Article 21 in:","options":["M. H. Hoskot v. State of Maharashtra (1978)","D. K. Basu v. State of West Bengal (1997)","Sunil Batra v. Delhi Administration (1978)","Prem Shankar Shukla v. Delhi Administration (1980)"],"answer":0,"explanation":"M. H. Hoskot (1978) held that free legal aid for an indigent prisoner, including a free copy of the judgment and counsel for the appeal, is part of the fair procedure Article 21 requires. D. K. Basu laid down arrest guidelines and Prem Shankar Shukla dealt with handcuffing.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"गरीब कैदी का निःशुल्क विधिक सहायता पाने का अधिकार, जिसमें अपील दायर करने में सहायता भी शामिल है, अनुच्छेद 21 में किस मामले में पढ़ा गया?","optionsHi":["एम. एच. होसकोट बनाम महाराष्ट्र राज्य (1978)","डी. के. बसु बनाम पश्चिम बंगाल राज्य (1997)","सुनील बत्रा बनाम दिल्ली प्रशासन (1978)","प्रेम शंकर शुक्ला बनाम दिल्ली प्रशासन (1980)"],"explanationHi":"एम. एच. होसकोट (1978) ने माना कि निर्धन कैदी के लिए निःशुल्क विधिक सहायता, जिसमें निर्णय की निःशुल्क प्रति और अपील के लिए अधिवक्ता शामिल हैं, अनुच्छेद 21 द्वारा अपेक्षित निष्पक्ष प्रक्रिया का भाग है। डी. के. बसु ने गिरफ्तारी के दिशानिर्देश बनाए और प्रेम शंकर शुक्ला हथकड़ी से संबंधित था।"},
  {"id":"polity-fundamental-rights-98","question":"In Ajay Hasia v. Khalid Mujib (1981), the Supreme Court set out tests for deciding when a body is an \"instrumentality or agency of the State\" and so \"State\" under Article 12. On these tests it held which body to be \"State\"?","options":["A private cricket club affiliated to a State body","A society running a regional engineering college","A registered political party contesting elections","A private trust running a temple with public donations"],"answer":1,"explanation":"The Court held the society that ran the Regional Engineering College, Srinagar to be State, because of deep government funding and control. The tests are government share capital, financial aid, deep and pervasive control, and public functions.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"अजय हसिया बनाम खालिद मुजीब (1981) में सर्वोच्च न्यायालय ने यह तय करने की कसौटियाँ बताईं कि कोई निकाय कब “राज्य का अभिकरण या साधन” है और इसलिए अनुच्छेद 12 के अंतर्गत “राज्य” है। इन कसौटियों पर उसने किस निकाय को “राज्य” माना?","optionsHi":["किसी राज्य निकाय से संबद्ध निजी क्रिकेट क्लब","क्षेत्रीय इंजीनियरिंग कॉलेज चलाने वाली सोसायटी","चुनाव लड़ने वाला पंजीकृत राजनीतिक दल","सार्वजनिक दान से मंदिर चलाने वाला निजी न्यास"],"explanationHi":"न्यायालय ने क्षेत्रीय इंजीनियरिंग कॉलेज, श्रीनगर चलाने वाली सोसायटी को गहरे सरकारी वित्तपोषण और नियंत्रण के कारण राज्य माना। कसौटियाँ हैं: सरकारी अंश पूँजी, वित्तीय सहायता, गहरा और व्यापक नियंत्रण, और सार्वजनिक कार्य।"},
  {"id":"polity-fundamental-rights-99","question":"Which clause of Article 16 permits a law requiring that the holder of an office connected with a religious or denominational institution belong to that religion?","options":["Article 16(2)","Article 16(3)","Article 16(5)","Article 16(4B)"],"answer":2,"explanation":"Article 16(5) saves such laws from the guarantee of equal opportunity. Article 16(3) concerns residence requirements, and Article 16(4B) lets unfilled reserved vacancies be carried forward.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 16 का कौन-सा खंड ऐसे कानून की अनुमति देता है जिसमें किसी धार्मिक या सांप्रदायिक संस्था से संबंधित पद के धारक का उस धर्म का होना आवश्यक हो?","optionsHi":["अनुच्छेद 16(2)","अनुच्छेद 16(3)","अनुच्छेद 16(5)","अनुच्छेद 16(4B)"],"explanationHi":"अनुच्छेद 16(5) ऐसे कानूनों को अवसर की समता की गारंटी से बचाता है। अनुच्छेद 16(3) निवास की शर्तों से और अनुच्छेद 16(4B) न भरी आरक्षित रिक्तियों को आगे ले जाने से संबंधित है।"},
  {"id":"polity-fundamental-rights-100","question":"Under Article 13(3)(a), \"law\" includes several things. How many of these are covered? I. Ordinance II. Bye-law III. Custom or usage having the force of law IV. Notification","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are covered: Article 13(3)(a) defines law to include any ordinance, order, bye-law, rule, regulation, notification, and custom or usage having the force of law in India.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 13(3)(a) के अंतर्गत “विधि” में कई चीजें शामिल हैं। इनमें से कितनी कवर होती हैं? I. अध्यादेश II. उप-नियम III. विधि का बल रखने वाली रूढ़ि या प्रथा IV. अधिसूचना","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार कवर होती हैं: अनुच्छेद 13(3)(a) विधि को परिभाषित करता है जिसमें कोई भी अध्यादेश, आदेश, उप-विधि, नियम, विनियम, अधिसूचना, तथा भारत में विधि का बल रखने वाली रूढ़ि या प्रथा शामिल है।"},
  {"id":"polity-fundamental-rights-101","question":"Under Article 33, Parliament may restrict or abrogate Fundamental Rights to ensure discipline and the proper discharge of duties. How many of these groups does it cover? I. Members of the armed forces II. Members of forces charged with maintaining public order III. Persons employed in bureaus set up by the State for intelligence or counter-intelligence IV. Persons employed in telecommunication systems set up for such forces or bureaus","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are covered. Groups III and IV were added to Article 33 by the 50th Amendment (1984). Only Parliament, not a State legislature, can make such a law.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 33 के अंतर्गत संसद अनुशासन और कर्तव्यों के उचित निर्वहन को सुनिश्चित करने के लिए मौलिक अधिकारों को प्रतिबंधित या निरसित कर सकती है। यह इनमें से कितने समूहों को कवर करता है? I. सशस्त्र बलों के सदस्य II. लोक व्यवस्था बनाए रखने का भार रखने वाले बलों के सदस्य III. राज्य द्वारा खुफिया या प्रति-खुफिया के लिए स्थापित ब्यूरो में नियोजित व्यक्ति IV. ऐसे बलों या ब्यूरो के लिए स्थापित दूरसंचार प्रणाली में नियोजित व्यक्ति","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार कवर होते हैं। समूह III और IV अनुच्छेद 33 में 50वें संशोधन (1984) द्वारा जोड़े गए। ऐसा कानून केवल संसद बना सकती है, राज्य विधानमंडल नहीं।"},
  {"id":"polity-fundamental-rights-102","question":"Match the case with what it decided: A. Bachan Singh v. State of Punjab (1980) B. Bandhua Mukti Morcha v. Union of India (1984) C. Kaushal Kishor v. State of U.P. (2023) D. Shirur Mutt case (1954). 1. Laid the basis of the \"essential religious practices\" test 2. Death penalty only in the \"rarest of rare\" cases 3. Identifying and releasing bonded labourers 4. Rights under Articles 19 and 21 can be enforced against persons other than the State","options":["A-2, B-3, C-4, D-1","A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-4, C-3, D-1"],"answer":0,"explanation":"Bachan Singh upheld the death penalty but limited it to the rarest of rare cases. Bandhua Mukti Morcha was a PIL on bonded labour under Articles 21 and 23. Kaushal Kishor (a Constitution Bench) held that Articles 19 and 21 can apply horizontally. The Shirur Mutt case (1954) held that Article 26 protects what is essential to a religion.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"मामले का उसके निर्णय से मिलान कीजिए: A. बचन सिंह बनाम पंजाब राज्य (1980) B. बंधुआ मुक्ति मोर्चा बनाम भारत संघ (1984) C. कौशल किशोर बनाम उत्तर प्रदेश राज्य (2023) D. शिरूर मठ मामला (1954)। 1. “अनिवार्य धार्मिक प्रथाओं” की कसौटी का आधार रखा 2. मृत्युदंड केवल “विरल से विरलतम” मामलों में 3. बंधुआ मजदूरों की पहचान और मुक्ति 4. अनुच्छेद 19 और 21 के अधिकार राज्य के अलावा अन्य व्यक्तियों के विरुद्ध भी प्रवर्तित हो सकते हैं","optionsHi":["A-2, B-3, C-4, D-1","A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-4, C-3, D-1"],"explanationHi":"बचन सिंह ने मृत्युदंड को बरकरार रखा पर उसे विरल से विरलतम मामलों तक सीमित किया। बंधुआ मुक्ति मोर्चा अनुच्छेद 21 और 23 के अंतर्गत बंधुआ मजदूरी पर जनहित याचिका थी। कौशल किशोर (संविधान पीठ) ने माना कि अनुच्छेद 19 और 21 क्षैतिज रूप से लागू हो सकते हैं। शिरूर मठ मामले (1954) ने माना कि अनुच्छेद 26 किसी धर्म के लिए अनिवार्य बातों की रक्षा करता है।"},
  {"id":"polity-fundamental-rights-103","question":"Arrange these judgments in chronological order: 1. Anuradha Bhasin v. Union of India (internet shutdowns in Jammu and Kashmir) 2. Kharak Singh v. State of U.P. (night-time domiciliary visits) 3. Satwant Singh Sawhney (right to travel abroad) 4. Shreya Singhal v. Union of India (Section 66A of the IT Act)","options":["3, 2, 4, 1","2, 3, 1, 4","2, 4, 3, 1","2, 3, 4, 1"],"answer":3,"explanation":"Kharak Singh 1962 → Satwant Singh Sawhney 1967 → Shreya Singhal 2015 → Anuradha Bhasin 2020. Anuradha Bhasin held that speech and trade over the internet are protected under Articles 19(1)(a) and 19(1)(g), and that indefinite suspension of the internet is not permissible.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इन निर्णयों को कालानुक्रम में व्यवस्थित कीजिए: 1. अनुराधा भसीन बनाम भारत संघ (जम्मू-कश्मीर में इंटरनेट बंदी) 2. खड़क सिंह बनाम उत्तर प्रदेश राज्य (रात्रि में घर पर तलाशी) 3. सत्वंत सिंह साहनी (विदेश यात्रा का अधिकार) 4. श्रेया सिंघल बनाम भारत संघ (सूचना प्रौद्योगिकी अधिनियम की धारा 66A)","optionsHi":["3, 2, 4, 1","2, 3, 1, 4","2, 4, 3, 1","2, 3, 4, 1"],"explanationHi":"खड़क सिंह 1962 → सत्वंत सिंह साहनी 1967 → श्रेया सिंघल 2015 → अनुराधा भसीन 2020। अनुराधा भसीन ने माना कि इंटरनेट पर वाक् और व्यापार अनुच्छेद 19(1)(a) और 19(1)(g) के अंतर्गत संरक्षित हैं, और इंटरनेट का अनिश्चितकालीन निलंबन अनुमेय नहीं है।"},
  {"id":"polity-fundamental-rights-104","question":"Assertion (A): A citizen cannot waive a Fundamental Right, even of their own free will. Reason (R): Fundamental Rights are not only for the benefit of the individual; they rest on public policy, as the Supreme Court held in Basheshar Nath v. CIT (1959).","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"In Basheshar Nath (1959) the Court held that the rights in Part III, at least Article 14, are put there as a matter of public policy, so an individual cannot give them up by agreement or settlement. R gives the reason for A.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): कोई नागरिक किसी मौलिक अधिकार का अधित्याग नहीं कर सकता, अपनी स्वतंत्र इच्छा से भी नहीं। कारण (R): मौलिक अधिकार केवल व्यक्ति के हित के लिए नहीं हैं; वे लोक नीति पर आधारित हैं, जैसा सर्वोच्च न्यायालय ने बशेशर नाथ बनाम आयकर आयुक्त (1959) में माना।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"बशेशर नाथ (1959) में न्यायालय ने माना कि भाग III के अधिकार, कम से कम अनुच्छेद 14, लोक नीति के रूप में रखे गए हैं, इसलिए कोई व्यक्ति उन्हें करार या समझौते से नहीं छोड़ सकता। R, A का कारण बताता है।"},
  {"id":"polity-fundamental-rights-105","question":"How many of these statements about the right to education are correct? I. The Right of Children to Free and Compulsory Education Act, 2009 came into force on 1 April 2010. II. Section 12(1)(c) of the Act requires private unaided schools to admit at least 25% of the entry class from weaker and disadvantaged groups. III. In Pramati Educational and Cultural Trust (2014), the Act was held not to apply to minority schools, aided or unaided. IV. Article 21A was inserted by the 93rd Amendment.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Article 21A was inserted by the 86th Amendment (2002). The 93rd Amendment (2005) inserted Article 15(5) on reservation in educational institutions.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"शिक्षा के अधिकार के बारे में इनमें से कितने कथन सही हैं? I. बच्चों का निःशुल्क और अनिवार्य शिक्षा का अधिकार अधिनियम, 2009 1 अप्रैल 2010 को लागू हुआ। II. अधिनियम की धारा 12(1)(c) निजी गैर-सहायता प्राप्त स्कूलों से प्रवेश कक्षा की कम से कम 25% सीटें कमजोर और वंचित समूहों को देने की अपेक्षा करती है। III. प्रमति एजुकेशनल एंड कल्चरल ट्रस्ट (2014) में माना गया कि अधिनियम अल्पसंख्यक स्कूलों पर, सहायता प्राप्त या गैर-सहायता प्राप्त, लागू नहीं होता। IV. अनुच्छेद 21A 93वें संशोधन द्वारा जोड़ा गया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। अनुच्छेद 21A 86वें संशोधन (2002) द्वारा जोड़ा गया। 93वें संशोधन (2005) ने शिक्षा संस्थाओं में आरक्षण संबंधी अनुच्छेद 15(5) जोड़ा।"},
  {"id":"polity-fundamental-rights-106","question":"How many of these statements about Indian Young Lawyers Association v. State of Kerala (2018), the Sabarimala case, are correct? I. By a 4:1 majority it struck down the exclusion of women aged 10 to 50 from the temple. II. The lone dissent came from Justice Indu Malhotra. III. The majority held that Ayyappa devotees form a separate religious denomination under Article 26. IV. All four majority judges based their decision on Article 17 (untouchability).","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I and II are correct. The majority held that Ayyappa devotees are NOT a separate denomination; Justice Malhotra, dissenting, held that they are. Only Justice Chandrachud treated the exclusion as a form of untouchability under Article 17.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इंडियन यंग लॉयर्स एसोसिएशन बनाम केरल राज्य (2018), सबरीमाला मामले, के बारे में इनमें से कितने कथन सही हैं? I. 4:1 के बहुमत से इसने 10 से 50 वर्ष की महिलाओं को मंदिर से बाहर रखने को रद्द किया। II. अकेली असहमति न्यायमूर्ति इंदु मल्होत्रा की थी। III. बहुमत ने माना कि अय्यप्पा भक्त अनुच्छेद 26 के अंतर्गत अलग धार्मिक संप्रदाय हैं। IV. चारों बहुमत न्यायाधीशों ने अपना निर्णय अनुच्छेद 17 (अस्पृश्यता) पर आधारित किया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I और II सही हैं। बहुमत ने माना कि अय्यप्पा भक्त अलग संप्रदाय नहीं हैं; असहमत न्यायमूर्ति मल्होत्रा ने माना कि वे हैं। केवल न्यायमूर्ति चंद्रचूड़ ने बहिष्कार को अनुच्छेद 17 के अंतर्गत अस्पृश्यता का रूप माना।"},
  {"id":"polity-fundamental-rights-107","question":"Article 19(5) allows reasonable restrictions on the freedom to move freely and to reside and settle in any part of India in the interests of the general public. What other ground does it name?","options":["Maintaining friendly relations with foreign States","Maintenance of supplies essential to the community","Decency, morality and incitement to an offence","Protecting the interests of any Scheduled Tribe"],"answer":3,"explanation":"Article 19(5) names two grounds: the interests of the general public and the protection of the interests of any Scheduled Tribe. The second one supports Inner Line Permits and limits on outsiders settling in tribal areas. Friendly relations and decency are grounds under Article 19(2) for speech.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 19(5) सामान्य जनता के हित में भारत में सर्वत्र संचरण और निवास करने तथा बसने की स्वतंत्रता पर युक्तियुक्त निर्बंधन की अनुमति देता है। यह और कौन-सा आधार बताता है?","optionsHi":["विदेशी राज्यों से मैत्रीपूर्ण संबंध बनाए रखना","समुदाय के लिए आवश्यक आपूर्तियों का रखरखाव","शिष्टाचार, सदाचार और अपराध-उद्दीपन","किसी अनुसूचित जनजाति के हितों का संरक्षण"],"explanationHi":"अनुच्छेद 19(5) दो आधार बताता है: सामान्य जनता के हित और किसी अनुसूचित जनजाति के हितों का संरक्षण। दूसरा आधार इनर लाइन परमिट और जनजातीय क्षेत्रों में बाहरी लोगों के बसने पर सीमाओं का समर्थन करता है। मैत्रीपूर्ण संबंध और शिष्टाचार वाक् के लिए अनुच्छेद 19(2) के आधार हैं।"},
  {"id":"polity-fundamental-rights-108","question":"How many of these statements about Public Interest Litigation are correct? I. In S. P. Gupta v. Union of India (1981), the Supreme Court relaxed the rule of locus standi. II. Letters and postcards sent to judges have been treated as writ petitions (epistolary jurisdiction). III. A PIL can be filed in a High Court under Article 226 as well as in the Supreme Court under Article 32. IV. Article 32(2) expressly mentions public interest litigation.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. PIL is a creation of the judges. The Constitution nowhere uses the phrase, and Article 32(2) only lists the writs (habeas corpus, mandamus, prohibition, quo warranto and certiorari) and directions or orders.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"जनहित याचिका के बारे में इनमें से कितने कथन सही हैं? I. एस. पी. गुप्ता बनाम भारत संघ (1981) में सर्वोच्च न्यायालय ने सुनवाई के अधिकार (locus standi) का नियम शिथिल किया। II. न्यायाधीशों को भेजे गए पत्रों और पोस्टकार्डों को रिट याचिका माना गया है (पत्र अधिकारिता)। III. जनहित याचिका अनुच्छेद 226 के अंतर्गत उच्च न्यायालय में भी और अनुच्छेद 32 के अंतर्गत सर्वोच्च न्यायालय में भी दायर की जा सकती है। IV. अनुच्छेद 32(2) जनहित याचिका का स्पष्ट उल्लेख करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। जनहित याचिका न्यायाधीशों की रचना है। संविधान में यह पदावली कहीं नहीं है, और अनुच्छेद 32(2) केवल रिटों (बंदी प्रत्यक्षीकरण, परमादेश, प्रतिषेध, अधिकार पृच्छा और उत्प्रेषण) और निदेशों या आदेशों को सूचीबद्ध करता है।"},
  {"id":"polity-fundamental-rights-109","question":"How many of these statements about preventive detention are correct? I. Only Parliament can make a law on preventive detention for reasons of defence, foreign affairs or the security of India. II. Parliament and the State legislatures can both legislate on preventive detention for the security of a State, public order or essential supplies and services. III. Article 22(7) empowers Parliament to prescribe the maximum period of detention. IV. The grounds of detention must be communicated, though facts against the public interest may be withheld.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. I is Entry 9 of the Union List and II is Entry 3 of the Concurrent List. III is Article 22(7)(b), and IV comes from Articles 22(5) and 22(6).","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"निवारक निरोध के बारे में इनमें से कितने कथन सही हैं? I. रक्षा, विदेश कार्य या भारत की सुरक्षा के कारणों से निवारक निरोध पर केवल संसद कानून बना सकती है। II. किसी राज्य की सुरक्षा, लोक व्यवस्था या आवश्यक आपूर्तियों और सेवाओं के लिए संसद और राज्य विधानमंडल दोनों निवारक निरोध पर कानून बना सकते हैं। III. अनुच्छेद 22(7) संसद को निरोध की अधिकतम अवधि निर्धारित करने का अधिकार देता है। IV. निरोध के आधार सूचित किए जाने चाहिए, यद्यपि लोक हित के विरुद्ध तथ्य रोके जा सकते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार सही हैं। I संघ सूची की प्रविष्टि 9 है और II समवर्ती सूची की प्रविष्टि 3। III अनुच्छेद 22(7)(b) है, और IV अनुच्छेद 22(5) और 22(6) से आता है।"},
  {"id":"polity-fundamental-rights-110","question":"Assertion (A): A minority educational institution that receives aid from the State cannot refuse admission to a student only because the student belongs to another religion. Reason (R): Article 29(2) forbids denying admission to a State-maintained or State-aided institution on grounds only of religion, race, caste or language.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Article 29(2) binds aided minority institutions too, so R explains A. The Court has still let such institutions give reasonable preference to their own community (St. Stephen's College, 1992), without shutting out others.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): राज्य से सहायता पाने वाली अल्पसंख्यक शिक्षा संस्था किसी छात्र को केवल इसलिए प्रवेश देने से इनकार नहीं कर सकती कि वह दूसरे धर्म का है। कारण (R): अनुच्छेद 29(2) राज्य-पोषित या राज्य-सहायता प्राप्त संस्था में केवल धर्म, मूलवंश, जाति या भाषा के आधार पर प्रवेश से वंचित करने को वर्जित करता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"अनुच्छेद 29(2) सहायता प्राप्त अल्पसंख्यक संस्थाओं पर भी बाध्यकारी है, इसलिए R, A की व्याख्या करता है। फिर भी न्यायालय ने ऐसी संस्थाओं को दूसरों को बाहर किए बिना अपने समुदाय को युक्तियुक्त वरीयता देने दी है (सेंट स्टीफेंस कॉलेज, 1992)।"},
  {"id":"polity-fundamental-rights-111","question":"Which pair of a \"saving\" Article and the Amendment that inserted it is NOT correctly matched?","options":["Article 31D – 4th Amendment, 1955","Article 31A – 1st Amendment, 1951","Article 31B – 1st Amendment, 1951","Article 31C – 25th Amendment, 1971"],"answer":0,"explanation":"Article 31D, which saved laws against \"anti-national activities\", was inserted by the 42nd Amendment (1976) and repealed by the 43rd (1977). The 4th Amendment (1955) only amended Article 31A and added laws to the Ninth Schedule.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"“व्यावृत्ति” अनुच्छेद और उसे जोड़ने वाले संशोधन की कौन-सी जोड़ी सही सुमेलित नहीं है?","optionsHi":["अनुच्छेद 31D – चौथा संशोधन, 1955","अनुच्छेद 31A – पहला संशोधन, 1951","अनुच्छेद 31B – पहला संशोधन, 1951","अनुच्छेद 31C – 25वाँ संशोधन, 1971"],"explanationHi":"अनुच्छेद 31D, जो “राष्ट्र-विरोधी गतिविधियों” के विरुद्ध कानूनों को बचाता था, 42वें संशोधन (1976) द्वारा जोड़ा गया और 43वें (1977) द्वारा निरसित हुआ। चौथे संशोधन (1955) ने केवल अनुच्छेद 31A में संशोधन किया और नौवीं अनुसूची में कानून जोड़े।"},
  {"id":"polity-fundamental-rights-112","question":"Which Article of the Constitution abolishes titles?","options":["Article 16","Article 17","Article 18","Article 19"],"answer":2,"explanation":"Article 18 abolishes titles other than military or academic distinctions. Article 17 abolishes untouchability, a common trap.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"संविधान का कौन-सा अनुच्छेद उपाधियों का अंत करता है?","optionsHi":["अनुच्छेद 16","अनुच्छेद 17","अनुच्छेद 18","अनुच्छेद 19"],"explanationHi":"अनुच्छेद 18 सैनिक या शैक्षिक विशिष्टताओं के सिवाय उपाधियों का अंत करता है। अनुच्छेद 17 अस्पृश्यता का अंत करता है, जो सामान्य भ्रम है।"},
  {"id":"polity-fundamental-rights-113","question":"The Right against Exploitation is contained in:","options":["Articles 19–22","Articles 23–24","Articles 25–28","Articles 29–30"],"answer":1,"explanation":"Article 23 bans traffic in human beings and forced labour; Article 24 bans child labour in factories, mines and hazardous work. Articles 25–28 are freedom of religion.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"शोषण के विरुद्ध अधिकार किनमें निहित है?","optionsHi":["अनुच्छेद 19–22","अनुच्छेद 23–24","अनुच्छेद 25–28","अनुच्छेद 29–30"],"explanationHi":"अनुच्छेद 23 मानव व्यापार और बलात् श्रम पर रोक लगाता है; अनुच्छेद 24 कारखानों, खानों और खतरनाक कार्य में बाल श्रम पर रोक लगाता है। अनुच्छेद 25–28 धर्म की स्वतंत्रता हैं।"},
  {"id":"polity-fundamental-rights-114","question":"Which Article says that no person shall be compelled to pay any tax whose proceeds are used to promote a particular religion?","options":["Article 25","Article 26","Article 28","Article 27"],"answer":3,"explanation":"Article 27 bars taxes earmarked for promoting any particular religion. Article 26 covers denominational rights and Article 28 religious instruction in educational institutions.","difficulty":"easy","source":"SSC CGL · State PSCs","questionHi":"कौन-सा अनुच्छेद कहता है कि किसी व्यक्ति को ऐसा कर चुकाने के लिए बाध्य नहीं किया जाएगा जिसकी आगम किसी विशेष धर्म की अभिवृद्धि के लिए उपयोग हों?","optionsHi":["अनुच्छेद 25","अनुच्छेद 26","अनुच्छेद 28","अनुच्छेद 27"],"explanationHi":"अनुच्छेद 27 किसी विशेष धर्म की अभिवृद्धि के लिए निर्धारित करों को वर्जित करता है। अनुच्छेद 26 सांप्रदायिक अधिकारों को और अनुच्छेद 28 शिक्षा संस्थाओं में धार्मिक शिक्षा को कवर करता है।"},
  {"id":"polity-fundamental-rights-115","question":"Article 18(1) abolishes titles, but makes an exception for:","options":["Military or academic distinctions","Hereditary titles of former rulers","Titles conferred by foreign States","Titles conferred by Parliament by law"],"answer":0,"explanation":"Article 18(1) bars the State from conferring titles except military or academic distinctions. Foreign titles cannot be accepted by citizens at all (Article 18(2)).","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"अनुच्छेद 18(1) उपाधियों का अंत करता है, परंतु किसके लिए अपवाद बनाता है?","optionsHi":["सैनिक या शैक्षिक विशिष्टताएँ","पूर्व शासकों की वंशानुगत उपाधियाँ","विदेशी राज्यों द्वारा प्रदान की गई उपाधियाँ","संसद द्वारा कानून से प्रदान की गई उपाधियाँ"],"explanationHi":"अनुच्छेद 18(1) राज्य को सैनिक या शैक्षिक विशिष्टताओं के सिवाय उपाधियाँ प्रदान करने से रोकता है। विदेशी उपाधियाँ नागरिक बिल्कुल स्वीकार नहीं कर सकते (अनुच्छेद 18(2))।"},
  {"id":"polity-fundamental-rights-116","question":"The law that gives effect to Article 23 by abolishing bonded labour was enacted in:","options":["1956","1986","1976","1996"],"answer":2,"explanation":"The Bonded Labour System (Abolition) Act was passed in 1976. The Child Labour (Prohibition and Regulation) Act, linked to Article 24, came in 1986.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"बंधुआ मजदूरी का उन्मूलन करके अनुच्छेद 23 को प्रभावी बनाने वाला कानून किस वर्ष बना?","optionsHi":["1956","1986","1976","1996"],"explanationHi":"बंधुआ मजदूरी प्रथा (उन्मूलन) अधिनियम 1976 में पारित हुआ। अनुच्छेद 24 से जुड़ा बाल श्रम (प्रतिषेध और विनियमन) अधिनियम 1986 में आया।"},
  {"id":"polity-fundamental-rights-117","question":"In Joseph Shine v. Union of India (2018), the Supreme Court struck down:","options":["Section 377 IPC as applied to consenting adults","Section 124A IPC on sedition","Section 66A of the IT Act","Section 497 IPC on adultery"],"answer":3,"explanation":"Joseph Shine held the adultery provision violative of Articles 14, 15 and 21 because it treated the wife as the husband's property. Section 377 was read down in Navtej Johar (2018) and Section 66A struck down in Shreya Singhal (2015).","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"जोसेफ शाइन बनाम भारत संघ (2018) में सर्वोच्च न्यायालय ने क्या रद्द किया?","optionsHi":["सहमति देने वाले वयस्कों पर लागू भारतीय दंड संहिता की धारा 377","राजद्रोह संबंधी भारतीय दंड संहिता की धारा 124A","सूचना प्रौद्योगिकी अधिनियम की धारा 66A","व्यभिचार संबंधी भारतीय दंड संहिता की धारा 497"],"explanationHi":"जोसेफ शाइन ने व्यभिचार के उपबंध को अनुच्छेद 14, 15 और 21 का उल्लंघन माना क्योंकि वह पत्नी को पति की संपत्ति मानता था। धारा 377 को नवतेज जौहर (2018) में सीमित किया गया और धारा 66A श्रेया सिंघल (2015) में रद्द हुई।"},
  {"id":"polity-fundamental-rights-118","question":"Which Article gives every religious denomination the right to manage its own affairs in matters of religion?","options":["Article 26","Article 25","Article 28","Article 30"],"answer":0,"explanation":"Article 26 lets denominations set up religious and charitable institutions, manage their religious affairs, and own and administer property. Article 25 is the individual's freedom of conscience; Article 30 concerns minority educational institutions.","difficulty":"moderate","source":"SSC CGL · State PSCs","questionHi":"कौन-सा अनुच्छेद प्रत्येक धार्मिक संप्रदाय को धर्म के विषयों में अपने कार्यों का प्रबंध करने का अधिकार देता है?","optionsHi":["अनुच्छेद 26","अनुच्छेद 25","अनुच्छेद 28","अनुच्छेद 30"],"explanationHi":"अनुच्छेद 26 संप्रदायों को धार्मिक और पूर्त संस्थाएँ स्थापित करने, अपने धार्मिक कार्यों का प्रबंध करने, तथा संपत्ति के स्वामित्व और प्रशासन का अधिकार देता है। अनुच्छेद 25 व्यक्ति की अंतःकरण की स्वतंत्रता है; अनुच्छेद 30 अल्पसंख्यक शिक्षा संस्थाओं से संबंधित है।"},
  {"id":"polity-fundamental-rights-119","question":"D. K. Basu v. State of West Bengal (1997) is best known for laying down:","options":["Guidelines on sexual harassment at the workplace","Guidelines on passive euthanasia and living wills","Guidelines on excluding the creamy layer among OBCs","Guidelines for the police on arrest and detention"],"answer":3,"explanation":"D. K. Basu framed requirements such as an arrest memo, informing a relative and medical examination, to prevent custodial violence under Article 21. Workplace guidelines came from Vishaka (1997).","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"डी. के. बसु बनाम पश्चिम बंगाल राज्य (1997) किस बात के लिए सबसे अधिक जाना जाता है?","optionsHi":["कार्यस्थल पर यौन उत्पीड़न के दिशानिर्देश","निष्क्रिय इच्छामृत्यु और जीवित वसीयत के दिशानिर्देश","OBC में क्रीमी लेयर को बाहर रखने के दिशानिर्देश","गिरफ्तारी और निरोध के संबंध में पुलिस के लिए दिशानिर्देश"],"explanationHi":"डी. के. बसु ने अनुच्छेद 21 के अंतर्गत हिरासत में हिंसा रोकने के लिए गिरफ्तारी मेमो, किसी रिश्तेदार को सूचित करना और चिकित्सा परीक्षण जैसी आवश्यकताएँ बनाईं। कार्यस्थल के दिशानिर्देश विशाखा (1997) से आए।"},
  {"id":"polity-fundamental-rights-120","question":"Which ground of discrimination is prohibited by Article 16(2) but NOT listed in Article 15(1)?","options":["Sex","Descent","Caste","Place of birth"],"answer":1,"explanation":"Article 15(1) lists religion, race, caste, sex and place of birth. Article 16(2), on public employment, adds descent and residence.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कौन-सा विभेद का आधार अनुच्छेद 16(2) द्वारा प्रतिषिद्ध है, परंतु अनुच्छेद 15(1) में सूचीबद्ध नहीं है?","optionsHi":["लिंग","वंश","जाति","जन्मस्थान"],"explanationHi":"अनुच्छेद 15(1) धर्म, मूलवंश, जाति, लिंग और जन्मस्थान को सूचीबद्ध करता है। लोक नियोजन संबंधी अनुच्छेद 16(2) वंश और निवास जोड़ता है।"},
  {"id":"polity-fundamental-rights-121","question":"In Balaji Raghavan v. Union of India, the Supreme Court held that national awards such as the Bharat Ratna and Padma awards:","options":["Are not titles under Article 18, but must not be used as prefixes or suffixes","Are titles of nobility barred by Article 18, and must therefore be abolished","Are not titles, and so may freely be used as prefixes to the recipient's name","Can be conferred only after Parliament passes a resolution approving each one"],"answer":0,"explanation":"The Court upheld the awards as recognition of merit, not titles of nobility, but said that using them as prefixes or suffixes could lead to forfeiture.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"बालाजी राघवन बनाम भारत संघ में सर्वोच्च न्यायालय ने माना कि भारत रत्न और पद्म जैसे राष्ट्रीय सम्मान:","optionsHi":["अनुच्छेद 18 के अंतर्गत उपाधियाँ नहीं हैं, परंतु उन्हें उपसर्ग या प्रत्यय के रूप में प्रयोग नहीं करना चाहिए","अनुच्छेद 18 द्वारा वर्जित कुलीनता की उपाधियाँ हैं, इसलिए उन्हें समाप्त करना चाहिए","उपाधियाँ नहीं हैं, इसलिए उन्हें प्राप्तकर्ता के नाम के उपसर्ग के रूप में स्वतंत्र रूप से प्रयोग किया जा सकता है","तभी प्रदान किए जा सकते हैं जब संसद प्रत्येक को अनुमोदित करने का संकल्प पारित करे"],"explanationHi":"न्यायालय ने सम्मानों को योग्यता की मान्यता मानकर बरकरार रखा, कुलीनता की उपाधियाँ नहीं, परंतु कहा कि उन्हें उपसर्ग या प्रत्यय के रूप में प्रयोग करने पर वे जब्त हो सकते हैं।"},
  {"id":"polity-fundamental-rights-122","question":"Which case held that the right to “propagate” religion under Article 25 does not include a right to convert another person?","options":["Sri Lakshmindra Thirtha Swamiar (Shirur Mutt), 1954","Rev. Stanislaus v. State of M.P. (1977)","Ismail Faruqui v. Union of India (1994)","Aruna Roy v. Union of India (2002)"],"answer":1,"explanation":"Stanislaus upheld the Madhya Pradesh and Orissa anti-conversion laws, holding that propagation means spreading one's beliefs, not converting others. Shirur Mutt laid down the essential practices test.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किस मामले में माना गया कि अनुच्छेद 25 के अंतर्गत धर्म के “प्रचार” के अधिकार में किसी अन्य व्यक्ति को धर्मांतरित करने का अधिकार शामिल नहीं है?","optionsHi":["श्री लक्ष्मींद्र तीर्थ स्वामियार (शिरूर मठ), 1954","रेव. स्टैनिस्लॉस बनाम मध्य प्रदेश राज्य (1977)","इस्माइल फारूकी बनाम भारत संघ (1994)","अरुणा रॉय बनाम भारत संघ (2002)"],"explanationHi":"स्टैनिस्लॉस ने मध्य प्रदेश और ओडिशा के धर्मांतरण-विरोधी कानूनों को बरकरार रखा, यह मानते हुए कि प्रचार का अर्थ अपने विश्वासों का प्रसार है, दूसरों का धर्मांतरण नहीं। शिरूर मठ ने अनिवार्य प्रथाओं की कसौटी तय की।"},
  {"id":"polity-fundamental-rights-123","question":"Article 16(4B), which lets unfilled reserved vacancies be carried forward as a separate class outside the 50% ceiling, was inserted by the:","options":["77th Amendment, 1995","81st Amendment, 2000","85th Amendment, 2001","93rd Amendment, 2005"],"answer":1,"explanation":"The 81st Amendment (2000) added Article 16(4B) for backlog vacancies. The 77th added Article 16(4A) and the 85th added consequential seniority to it.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 16(4B), जो न भरी आरक्षित रिक्तियों को 50% की सीमा से बाहर अलग वर्ग के रूप में आगे ले जाने देता है, किसके द्वारा जोड़ा गया?","optionsHi":["77वाँ संशोधन, 1995","81वाँ संशोधन, 2000","85वाँ संशोधन, 2001","93वाँ संशोधन, 2005"],"explanationHi":"81वें संशोधन (2000) ने बैकलॉग रिक्तियों के लिए अनुच्छेद 16(4B) जोड़ा। 77वें ने अनुच्छेद 16(4A) जोड़ा और 85वें ने उसमें परिणामी वरिष्ठता जोड़ी।"},
  {"id":"polity-fundamental-rights-124","question":"In Janhit Abhiyan v. Union of India (2022), the Supreme Court:","options":["Struck down the EWS quota for breaching the 50% ceiling","Upheld the EWS quota unanimously","Upheld the 103rd Amendment by a 3:2 majority","Referred the question to a nine-judge bench"],"answer":2,"explanation":"A five-judge bench upheld the 10% EWS reservation by 3:2; Chief Justice U. U. Lalit and Justice S. Ravindra Bhat dissented over the exclusion of SC, ST and OBC poor.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जनहित अभियान बनाम भारत संघ (2022) में सर्वोच्च न्यायालय ने:","optionsHi":["50% की सीमा के उल्लंघन के लिए EWS कोटा रद्द किया","EWS कोटा सर्वसम्मति से बरकरार रखा","103वें संशोधन को 3:2 के बहुमत से बरकरार रखा","प्रश्न नौ न्यायाधीशों की पीठ को भेजा"],"explanationHi":"पाँच न्यायाधीशों की पीठ ने 10% EWS आरक्षण को 3:2 से बरकरार रखा; मुख्य न्यायाधीश यू. यू. ललित और न्यायमूर्ति एस. रवींद्र भट ने अनुसूचित जाति, जनजाति और OBC के गरीबों के बहिष्कार पर असहमति जताई।"},
  {"id":"polity-fundamental-rights-125","question":"The right to enjoy pollution-free water and air was held to be part of the right to life under Article 21 in:","options":["Olga Tellis v. Bombay Municipal Corporation (1985)","Francis Coralie Mullin v. UT of Delhi (1981)","Parmanand Katara v. Union of India (1989)","Subhash Kumar v. State of Bihar (1991)"],"answer":3,"explanation":"Subhash Kumar (1991) read a clean environment into Article 21. Olga Tellis is about livelihood, Francis Coralie Mullin about human dignity and Parmanand Katara about emergency medical aid.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"प्रदूषण-मुक्त जल और वायु का आनंद लेने का अधिकार अनुच्छेद 21 के अंतर्गत जीवन के अधिकार का भाग किस मामले में माना गया?","optionsHi":["ओल्गा टेलिस बनाम बॉम्बे म्युनिसिपल कॉर्पोरेशन (1985)","फ्रांसिस कोरालि मुलिन बनाम दिल्ली संघ राज्यक्षेत्र (1981)","परमानंद कटारा बनाम भारत संघ (1989)","सुभाष कुमार बनाम बिहार राज्य (1991)"],"explanationHi":"सुभाष कुमार (1991) ने स्वच्छ पर्यावरण को अनुच्छेद 21 में पढ़ा। ओल्गा टेलिस आजीविका के बारे में, फ्रांसिस कोरालि मुलिन मानवीय गरिमा के बारे में और परमानंद कटारा आपातकालीन चिकित्सा सहायता के बारे में है।"},
  {"id":"polity-fundamental-rights-126","question":"In State of Punjab v. Davinder Singh (2024), a seven-judge bench of the Supreme Court held that:","options":["The creamy-layer rule can never be applied to Scheduled Castes or Tribes","States may sub-classify Scheduled Castes, overruling E. V. Chinnaiah (2005)","Reservation in promotions for SCs and STs is unconstitutional under Article 16","The 50% ceiling on reservation is absolute and admits no exception"],"answer":1,"explanation":"By 6:1 the Court held SCs are not a homogeneous class and can be sub-classified, overruling the five-judge ruling in E. V. Chinnaiah. Justice Bela Trivedi dissented.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पंजाब राज्य बनाम देविंदर सिंह (2024) में सर्वोच्च न्यायालय की सात न्यायाधीशों की पीठ ने माना कि:","optionsHi":["क्रीमी लेयर का नियम अनुसूचित जातियों या जनजातियों पर कभी लागू नहीं किया जा सकता","राज्य अनुसूचित जातियों का उप-वर्गीकरण कर सकते हैं, ई. वी. चिन्नैया (2005) को पलटते हुए","अनुसूचित जातियों और जनजातियों के लिए पदोन्नति में आरक्षण अनुच्छेद 16 के अंतर्गत असंवैधानिक है","आरक्षण की 50% सीमा निरपेक्ष है और उसका कोई अपवाद नहीं है"],"explanationHi":"6:1 से न्यायालय ने माना कि अनुसूचित जातियाँ समरूप वर्ग नहीं हैं और उनका उप-वर्गीकरण हो सकता है, ई. वी. चिन्नैया में पाँच न्यायाधीशों के निर्णय को पलटते हुए। न्यायमूर्ति बेला त्रिवेदी ने असहमति जताई।"},
  {"id":"polity-fundamental-rights-127","question":"In M. C. Mehta v. State of Tamil Nadu (1996), about child workers in the Sivakasi match and fireworks industry, the Supreme Court directed:","options":["Errant employers to pay compensation per child into a welfare fund","The closure of all match and fireworks factories in Tamil Nadu","Lowering the age limit in Article 24 from 14 years to 12 years","Transfer of all child workers to residential schools run by the Centre"],"answer":0,"explanation":"The Court ordered employers violating the child labour law to pay compensation per child into a welfare fund, and the State to provide education and alternative employment for an adult family member. Article 24 itself sets the age at 14.","difficulty":"hard","source":"UPSC Prelims","questionHi":"एम. सी. मेहता बनाम तमिलनाडु राज्य (1996) में, जो शिवकाशी के माचिस और आतिशबाजी उद्योग के बाल श्रमिकों से संबंधित था, सर्वोच्च न्यायालय ने निर्देश दिया:","optionsHi":["गलती करने वाले नियोक्ता प्रति बच्चा मुआवजा कल्याण निधि में जमा करें","तमिलनाडु की सभी माचिस और आतिशबाजी फैक्टरियाँ बंद की जाएँ","अनुच्छेद 24 में आयु सीमा 14 वर्ष से घटाकर 12 वर्ष की जाए","सभी बाल श्रमिकों को केंद्र द्वारा संचालित आवासीय विद्यालयों में स्थानांतरित किया जाए"],"explanationHi":"न्यायालय ने बाल श्रम कानून का उल्लंघन करने वाले नियोक्ताओं को प्रति बच्चा मुआवजा कल्याण निधि में देने और राज्य को शिक्षा तथा परिवार के एक वयस्क सदस्य के लिए वैकल्पिक रोजगार उपलब्ध कराने का आदेश दिया। अनुच्छेद 24 स्वयं आयु 14 वर्ष तय करता है।"},
  {"id":"polity-fundamental-rights-128","question":"Article 30(1A), which requires that compensation for compulsory acquisition of a minority educational institution's property must not restrict or abrogate its Article 30 right, was inserted by the:","options":["42nd Amendment, 1976","25th Amendment, 1971","44th Amendment, 1978","93rd Amendment, 2005"],"answer":2,"explanation":"When the 44th Amendment removed the Fundamental Right to property, it added Article 30(1A) so minority institutions kept protection against inadequate compensation.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 30(1A), जो अपेक्षा करता है कि अल्पसंख्यक शिक्षा संस्था की संपत्ति के अनिवार्य अधिग्रहण का प्रतिकर उसके अनुच्छेद 30 के अधिकार को निर्बंधित या निरसित न करे, किसके द्वारा जोड़ा गया?","optionsHi":["42वाँ संशोधन, 1976","25वाँ संशोधन, 1971","44वाँ संशोधन, 1978","93वाँ संशोधन, 2005"],"explanationHi":"जब 44वें संशोधन ने संपत्ति का मौलिक अधिकार हटाया, तो उसने अनुच्छेद 30(1A) जोड़ा ताकि अल्पसंख्यक संस्थाओं को अपर्याप्त प्रतिकर के विरुद्ध संरक्षण बना रहे।"},
  {"id":"polity-fundamental-rights-129","question":"The “essential religious practices” test for deciding what Article 25 protects was first laid down in:","options":["Ismail Faruqui v. Union of India (1994)","Shayara Bano v. Union of India (2017)","Bijoe Emmanuel v. State of Kerala (1986)","The Shirur Mutt case (1954)"],"answer":3,"explanation":"The Shirur Mutt case (1954) held that religion covers practices essential to it, which the State cannot regulate except as allowed. Ismail Faruqui later applied the idea to hold a mosque not essential to Islam.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 25 जिसकी रक्षा करता है, उसे तय करने के लिए “अनिवार्य धार्मिक प्रथाओं” की कसौटी पहली बार किसमें निर्धारित की गई?","optionsHi":["इस्माइल फारूकी बनाम भारत संघ (1994)","शायरा बानो बनाम भारत संघ (2017)","बिजॉय इमैनुएल बनाम केरल राज्य (1986)","शिरूर मठ मामला (1954)"],"explanationHi":"शिरूर मठ मामले (1954) ने माना कि धर्म में उसके लिए अनिवार्य प्रथाएँ शामिल हैं, जिन्हें राज्य अनुमत सीमा के सिवाय विनियमित नहीं कर सकता। इस्माइल फारूकी ने बाद में इसी विचार को लागू करके माना कि मस्जिद इस्लाम के लिए अनिवार्य नहीं है।"},
  {"id":"polity-fundamental-rights-130","question":"Assertion (A): Article 14 forbids class legislation but permits reasonable classification. Reason (R): A classification is valid if it rests on an intelligible differentia that has a rational nexus with the object of the law.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: the twin test of intelligible differentia and rational nexus (Anwar Ali Sarkar, 1952; Budhan Choudhry, 1955) separates permissible classification from forbidden class legislation.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"अभिकथन (A): अनुच्छेद 14 वर्ग विधान को वर्जित करता है परंतु युक्तियुक्त वर्गीकरण की अनुमति देता है। कारण (R): वर्गीकरण तभी वैध है जब वह बोधगम्य अंतर (intelligible differentia) पर आधारित हो जिसका कानून के उद्देश्य से तर्कसंगत संबंध हो।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है: बोधगम्य अंतर और तर्कसंगत संबंध की दोहरी कसौटी (अनवर अली सरकार, 1952; बुधन चौधरी, 1955) अनुमेय वर्गीकरण को वर्जित वर्ग विधान से अलग करती है।"},
  {"id":"polity-fundamental-rights-131","question":"Match the case with the right it read into Article 21: A. Francis Coralie Mullin (1981) B. Parmanand Katara (1989) C. Subramanian Swamy v. Union of India (2016) D. Shafin Jahan v. Asokan K. M. (2018) — 1. Emergency medical aid 2. Right to live with human dignity 3. Choice of a life partner 4. Reputation","options":["A-1, B-2, C-4, D-3","A-2, B-1, C-4, D-3","A-2, B-1, C-3, D-4","A-4, B-1, C-2, D-3"],"answer":1,"explanation":"Francis Coralie Mullin: life means life with dignity. Parmanand Katara: doctors must give emergency aid. Subramanian Swamy upheld criminal defamation since reputation is part of Article 21. Shafin Jahan (Hadiya case): choice of spouse.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मामले का उस अधिकार से मिलान कीजिए जो उसने अनुच्छेद 21 में पढ़ा: A. फ्रांसिस कोरालि मुलिन (1981) B. परमानंद कटारा (1989) C. सुब्रमण्यम स्वामी बनाम भारत संघ (2016) D. शफीन जहाँ बनाम अशोकन के. एम. (2018) — 1. आपातकालीन चिकित्सा सहायता 2. मानवीय गरिमा के साथ जीने का अधिकार 3. जीवनसाथी चुनने का अधिकार 4. प्रतिष्ठा","optionsHi":["A-1, B-2, C-4, D-3","A-2, B-1, C-4, D-3","A-2, B-1, C-3, D-4","A-4, B-1, C-2, D-3"],"explanationHi":"फ्रांसिस कोरालि मुलिन: जीवन का अर्थ गरिमा के साथ जीवन है। परमानंद कटारा: चिकित्सकों को आपातकालीन सहायता देनी चाहिए। सुब्रमण्यम स्वामी ने आपराधिक मानहानि को बरकरार रखा क्योंकि प्रतिष्ठा अनुच्छेद 21 का भाग है। शफीन जहाँ (हादिया मामला): जीवनसाथी का चुनाव।"},
  {"id":"polity-fundamental-rights-132","question":"Consider the following statements: 1. Article 25 is subject to public order, morality, health and the other provisions of Part III. 2. Article 26 is expressly subject to public order, morality, health and also to the other provisions of Part III. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Only 1 is correct. Article 26 is subject only to public order, morality and health; the words “and to the other provisions of this Part” appear in Article 25(1) but not in Article 26.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. अनुच्छेद 25 लोक व्यवस्था, सदाचार, स्वास्थ्य और भाग III के अन्य उपबंधों के अधीन है। 2. अनुच्छेद 26 स्पष्ट रूप से लोक व्यवस्था, सदाचार, स्वास्थ्य और भाग III के अन्य उपबंधों के भी अधीन है। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"केवल 1 सही है। अनुच्छेद 26 केवल लोक व्यवस्था, सदाचार और स्वास्थ्य के अधीन है; “और इस भाग के अन्य उपबंधों के” शब्द अनुच्छेद 25(1) में हैं, अनुच्छेद 26 में नहीं।"},
  {"id":"polity-fundamental-rights-133","question":"Consider the following statements about Article 19(2): 1. “Sovereignty and integrity of India” was added as a ground of restriction by the 1st Amendment, 1951. 2. “Public order” and “incitement to an offence” were added by the 1st Amendment, 1951. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":1,"explanation":"Only 2 is correct. The 1st Amendment added public order, friendly relations with foreign States and incitement to an offence. Sovereignty and integrity came with the 16th Amendment, 1963.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 19(2) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. “भारत की प्रभुता और अखंडता” निर्बंधन के आधार के रूप में पहले संशोधन, 1951 द्वारा जोड़ी गई। 2. “लोक व्यवस्था” और “अपराध-उद्दीपन” पहले संशोधन, 1951 द्वारा जोड़े गए। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"केवल 2 सही है। पहले संशोधन ने लोक व्यवस्था, विदेशी राज्यों से मैत्रीपूर्ण संबंध और अपराध-उद्दीपन जोड़े। प्रभुता और अखंडता 16वें संशोधन, 1963 के साथ आई।"},
  {"id":"polity-fundamental-rights-134","question":"The 1976 judgment that held that no one could move a court for habeas corpus while the right under Article 21 stood suspended during the Emergency, with Justice H. R. Khanna dissenting, is:","options":["A. K. Gopalan v. State of Madras","Kharak Singh v. State of U.P.","ADM Jabalpur v. Shivkant Shukla","Golaknath v. State of Punjab"],"answer":2,"explanation":"ADM Jabalpur (4:1) was expressly overruled by the nine-judge bench in K. S. Puttaswamy (2017). The 44th Amendment had already barred suspension of Articles 20 and 21 during an emergency.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"1976 का वह निर्णय, जिसमें न्यायमूर्ति एच. आर. खन्ना की असहमति के साथ माना गया कि आपातकाल में अनुच्छेद 21 का अधिकार निलंबित रहने पर कोई बंदी प्रत्यक्षीकरण के लिए न्यायालय नहीं जा सकता, कौन-सा है?","optionsHi":["ए. के. गोपालन बनाम मद्रास राज्य","खड़क सिंह बनाम उत्तर प्रदेश राज्य","एडीएम जबलपुर बनाम शिवकांत शुक्ला","गोलकनाथ बनाम पंजाब राज्य"],"explanationHi":"एडीएम जबलपुर (4:1) को के. एस. पुट्टस्वामी (2017) में नौ न्यायाधीशों की पीठ ने स्पष्ट रूप से पलट दिया। 44वें संशोधन ने पहले ही आपातकाल में अनुच्छेद 20 और 21 के निलंबन को वर्जित कर दिया था।"},
  {"id":"polity-fundamental-rights-135","question":"Assertion (A): The 93rd Amendment inserted Article 15(5), enabling reservation in private unaided educational institutions other than minority institutions. Reason (R): In P. A. Inamdar (2005), the Supreme Court had held that the State could not impose reservation on unaided private institutions.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: Parliament passed the 93rd Amendment in response to Inamdar. Article 15(5) was later upheld in Pramati Educational Trust (2014).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): 93वें संशोधन ने अनुच्छेद 15(5) जोड़ा, जो अल्पसंख्यक संस्थाओं को छोड़कर निजी गैर-सहायता प्राप्त शिक्षा संस्थाओं में आरक्षण को सक्षम बनाता है। कारण (R): पी. ए. इनामदार (2005) में सर्वोच्च न्यायालय ने माना था कि राज्य गैर-सहायता प्राप्त निजी संस्थाओं पर आरक्षण नहीं थोप सकता।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है: संसद ने इनामदार के उत्तर में 93वाँ संशोधन पारित किया। अनुच्छेद 15(5) को बाद में प्रमति एजुकेशनल ट्रस्ट (2014) में बरकरार रखा गया।"},
  {"id":"polity-fundamental-rights-136","question":"Consider the following statements about the child labour law as amended in 2016: 1. Children below 14 may not be employed in any occupation, except helping their family or family enterprise in non-hazardous work outside school hours. 2. Adolescents aged 14 to 18 may not be employed in hazardous occupations and processes. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. The 2016 amendment renamed the 1986 law the Child and Adolescent Labour (Prohibition and Regulation) Act, going beyond Article 24's ban on hazardous work for those under 14.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"2016 में संशोधित बाल श्रम कानून के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. 14 वर्ष से कम के बच्चों को किसी भी व्यवसाय में नियोजित नहीं किया जा सकता, सिवाय स्कूल के समय के बाहर गैर-खतरनाक कार्य में अपने परिवार या पारिवारिक उद्यम की सहायता करने के। 2. 14 से 18 वर्ष के किशोरों को खतरनाक व्यवसायों और प्रक्रियाओं में नियोजित नहीं किया जा सकता। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। 2016 के संशोधन ने 1986 के कानून का नाम बाल एवं किशोर श्रम (प्रतिषेध और विनियमन) अधिनियम रखा, जो 14 वर्ष से कम के लिए खतरनाक कार्य पर रोक वाले अनुच्छेद 24 से आगे जाता है।"},
  {"id":"polity-fundamental-rights-137","question":"How many of these statements about the 86th Amendment are correct? I. It inserted Article 21A. II. It substituted Article 45 to provide for early childhood care and education for children below six. III. It added Fundamental Duty 51A(k) on parents and guardians. IV. It was enacted in 2002.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The 86th Amendment (2002) made education for 6–14-year-olds a Fundamental Right, shifted Article 45 to children under six, and added the parental duty in Article 51A(k).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"86वें संशोधन के बारे में इनमें से कितने कथन सही हैं? I. इसने अनुच्छेद 21A जोड़ा। II. इसने अनुच्छेद 45 को प्रतिस्थापित किया ताकि छह वर्ष से कम के बच्चों की प्रारंभिक देखभाल और शिक्षा का प्रावधान हो। III. इसने माता-पिता और संरक्षकों पर मौलिक कर्तव्य 51A(k) जोड़ा। IV. यह 2002 में अधिनियमित हुआ।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चार सही हैं। 86वें संशोधन (2002) ने 6–14 वर्ष की शिक्षा को मौलिक अधिकार बनाया, अनुच्छेद 45 को छह वर्ष से कम के बच्चों की ओर मोड़ा, और अनुच्छेद 51A(k) में माता-पिता का कर्तव्य जोड़ा।"},
  {"id":"polity-fundamental-rights-138","question":"Arrange these freedom of speech judgments in chronological order: 1. Kedar Nath Singh (sedition upheld but read down) 2. Shreya Singhal (Section 66A struck down) 3. Romesh Thappar (ban on a journal struck down) 4. S. G. Vombatkere (sedition prosecutions put in abeyance)","options":["1, 3, 2, 4","3, 1, 4, 2","1, 3, 4, 2","3, 1, 2, 4"],"answer":3,"explanation":"Romesh Thappar (1950), Kedar Nath Singh (1962), Shreya Singhal (2015) and S. G. Vombatkere (2022).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"वाक्-स्वातंत्र्य के इन निर्णयों को कालानुक्रम में व्यवस्थित कीजिए: 1. केदार नाथ सिंह (राजद्रोह बरकरार पर सीमित) 2. श्रेया सिंघल (धारा 66A रद्द) 3. रोमेश थापर (पत्रिका पर प्रतिबंध रद्द) 4. एस. जी. वोम्बटकेरे (राजद्रोह अभियोजन स्थगित)","optionsHi":["1, 3, 2, 4","3, 1, 4, 2","1, 3, 4, 2","3, 1, 2, 4"],"explanationHi":"रोमेश थापर (1950), केदार नाथ सिंह (1962), श्रेया सिंघल (2015) और एस. जी. वोम्बटकेरे (2022)।"},
  {"id":"polity-fundamental-rights-139","question":"Match the case with the protection it recognised: A. Sunil Batra (1978) B. Prem Shankar Shukla (1980) C. Chameli Singh (1996) D. Satwant Singh Sawhney (1967) — 1. Right to shelter 2. Right to travel abroad 3. Protection against routine handcuffing 4. Protection of prisoners against solitary confinement and bar fetters","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1","A-4, B-1, C-3, D-2"],"answer":1,"explanation":"Sunil Batra protected prisoners from solitary confinement and bar fetters, Prem Shankar Shukla restricted handcuffing, Chameli Singh recognised shelter, and Satwant Singh Sawhney treated travel abroad as part of personal liberty.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मामले का उस संरक्षण से मिलान कीजिए जिसे उसने मान्य किया: A. सुनील बत्रा (1978) B. प्रेम शंकर शुक्ला (1980) C. चमेली सिंह (1996) D. सत्वंत सिंह साहनी (1967) — 1. आश्रय का अधिकार 2. विदेश यात्रा का अधिकार 3. नियमित हथकड़ी से संरक्षण 4. कैदियों का एकांत कारावास और बार-बेड़ियों से संरक्षण","optionsHi":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1","A-4, B-1, C-3, D-2"],"explanationHi":"सुनील बत्रा ने कैदियों को एकांत कारावास और बार-बेड़ियों से बचाया, प्रेम शंकर शुक्ला ने हथकड़ी पर रोक लगाई, चमेली सिंह ने आश्रय को मान्यता दी, और सत्वंत सिंह साहनी ने विदेश यात्रा को व्यक्तिगत स्वतंत्रता का भाग माना।"},
  {"id":"polity-fundamental-rights-140","question":"Consider the following statements: 1. In M. Nagaraj (2006), the Supreme Court upheld Article 16(4A) but required the State to show backwardness, inadequate representation and overall administrative efficiency before reserving promotions. 2. In Jarnail Singh (2018), it held that the State need not collect quantifiable data on the backwardness of SCs and STs for such promotions. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. Jarnail Singh modified Nagaraj only on proving backwardness of SCs and STs, while keeping the other conditions and applying the creamy-layer principle.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. एम. नागराज (2006) में सर्वोच्च न्यायालय ने अनुच्छेद 16(4A) को बरकरार रखा पर राज्य से पदोन्नति में आरक्षण से पहले पिछड़ेपन, अपर्याप्त प्रतिनिधित्व और समग्र प्रशासनिक दक्षता को दिखाने की अपेक्षा की। 2. जरनैल सिंह (2018) में उसने माना कि ऐसी पदोन्नतियों के लिए राज्य को अनुसूचित जातियों और जनजातियों के पिछड़ेपन पर मात्रात्मक आँकड़े जुटाने की आवश्यकता नहीं है। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। जरनैल सिंह ने नागराज को केवल अनुसूचित जातियों और जनजातियों के पिछड़ेपन को सिद्ध करने के संबंध में संशोधित किया, अन्य शर्तें बनाए रखीं और क्रीमी लेयर सिद्धांत लागू किया।"},
  {"id":"polity-fundamental-rights-141","question":"How many of these statements about K. S. Puttaswamy v. Union of India (2017) are correct? I. It was decided by nine judges. II. The decision was by a 5:4 majority. III. It overruled M. P. Sharma and Kharak Singh to the extent they denied a right to privacy. IV. The same nine-judge bench also decided the validity of the Aadhaar Act.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong: the nine-judge bench was unanimous. IV is wrong: the Aadhaar Act was decided separately in 2018 by a five-judge bench.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"के. एस. पुट्टस्वामी बनाम भारत संघ (2017) के बारे में इनमें से कितने कथन सही हैं? I. यह नौ न्यायाधीशों द्वारा निर्णीत हुआ। II. निर्णय 5:4 के बहुमत से था। III. इसने निजता के अधिकार को नकारने की सीमा तक एम. पी. शर्मा और खड़क सिंह को पलट दिया। IV. उसी नौ न्यायाधीशों की पीठ ने आधार अधिनियम की वैधता भी तय की।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। II गलत है: नौ न्यायाधीशों की पीठ सर्वसम्मत थी। IV गलत है: आधार अधिनियम का निर्णय 2018 में पाँच न्यायाधीशों की पीठ ने अलग से किया।"},
  {"id":"polity-fundamental-rights-142","question":"Under Article 13, only the part of a statute that violates a Fundamental Right is struck down, if it can be separated from the rest without defeating the law’s purpose. This doctrine of severability was explained in:","options":["Bhikaji Narain Dhakras v. State of Madhya Pradesh (1955)","Basheshar Nath v. Commissioner of Income Tax (1959)","R. M. D. Chamarbaugwala v. Union of India (1957)","Kesavananda Bharati v. State of Kerala (1973)"],"answer":2,"explanation":"R. M. D. C. (1957), on prize competitions, set out when the valid part of a law survives. Bhikaji Narain is the doctrine of eclipse and Basheshar Nath the bar on waiving Fundamental Rights.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 13 के अंतर्गत कानून का केवल वही भाग रद्द होता है जो मौलिक अधिकार का उल्लंघन करता है, यदि उसे कानून के उद्देश्य को विफल किए बिना शेष से अलग किया जा सके। पृथक्करणीयता का यह सिद्धांत किसमें समझाया गया?","optionsHi":["भीकाजी नारायण ढाकरस बनाम मध्य प्रदेश राज्य (1955)","बशेशर नाथ बनाम आयकर आयुक्त (1959)","आर. एम. डी. चमारबागवाला बनाम भारत संघ (1957)","केशवानंद भारती बनाम केरल राज्य (1973)"],"explanationHi":"आर. एम. डी. सी. (1957) ने, पुरस्कार प्रतियोगिताओं के संबंध में, तय किया कि कानून का वैध भाग कब बचा रहता है। भीकाजी नारायण ग्रहण का सिद्धांत है और बशेशर नाथ मौलिक अधिकारों के अधित्याग पर रोक।"},
  {"id":"polity-fundamental-rights-143","question":"Consider the following statements about Jarnail Singh v. Lachhmi Narain Gupta (2018): 1. It held that M. Nagaraj (2006) need not be referred to a larger bench. 2. It held that the State need not collect quantifiable data on the backwardness of Scheduled Castes and Scheduled Tribes before giving them reservation in promotion. 3. It held that the creamy layer principle can be applied to Scheduled Castes and Scheduled Tribes in promotions. Which of the statements given above is/are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"All three are correct: the five-judge bench declined to revisit Nagaraj, dropped only its requirement of data on SC/ST backwardness (kept the data on inadequate representation and efficiency), and applied the creamy layer test.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जरनैल सिंह बनाम लक्ष्मी नारायण गुप्ता (2018) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसने माना कि एम. नागराज (2006) को बड़ी पीठ को भेजने की आवश्यकता नहीं है। 2. इसने माना कि अनुसूचित जातियों और जनजातियों को पदोन्नति में आरक्षण देने से पहले राज्य को उनके पिछड़ेपन पर मात्रात्मक आँकड़े जुटाने की आवश्यकता नहीं है। 3. इसने माना कि क्रीमी लेयर सिद्धांत पदोन्नति में अनुसूचित जातियों और जनजातियों पर लागू किया जा सकता है। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"तीनों सही हैं: पाँच न्यायाधीशों की पीठ ने नागराज पर पुनर्विचार से इनकार किया, केवल उसकी अनुसूचित जाति/जनजाति पिछड़ेपन पर आँकड़ों की शर्त हटाई (अपर्याप्त प्रतिनिधित्व और दक्षता पर आँकड़े बनाए रखे), और क्रीमी लेयर कसौटी लागू की।"},
  {"id":"polity-fundamental-rights-144","question":"In which case did the Supreme Court strike down an order fixing the price of newspapers according to their number of pages, holding that a restriction on circulation infringes the freedom of the press?","options":["Romesh Thappar v. State of Madras (1950)","Brij Bhushan v. State of Delhi (1950)","Indian Express Newspapers v. Union of India (1985)","Sakal Papers v. Union of India (1962)"],"answer":3,"explanation":"Sakal Papers (1962) held that the price-and-page schedule curtailed circulation, which is part of Article 19(1)(a), and could not be justified as a restriction on business under Article 19(6). Romesh Thappar and Brij Bhushan were 1950 cases on a ban and on pre-censorship.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किस मामले में सर्वोच्च न्यायालय ने समाचार पत्रों के पृष्ठों की संख्या के अनुसार उनके मूल्य निर्धारित करने वाले आदेश को रद्द किया, यह मानते हुए कि प्रसार पर निर्बंधन प्रेस की स्वतंत्रता का उल्लंघन है?","optionsHi":["रोमेश थापर बनाम मद्रास राज्य (1950)","ब्रज भूषण बनाम दिल्ली राज्य (1950)","इंडियन एक्सप्रेस न्यूजपेपर्स बनाम भारत संघ (1985)","सकाल पेपर्स बनाम भारत संघ (1962)"],"explanationHi":"सकाल पेपर्स (1962) ने माना कि मूल्य-और-पृष्ठ अनुसूची ने प्रसार को घटाया, जो अनुच्छेद 19(1)(a) का भाग है, और इसे अनुच्छेद 19(6) के अंतर्गत व्यापार पर निर्बंधन के रूप में उचित नहीं ठहराया जा सकता। रोमेश थापर और ब्रज भूषण प्रतिबंध और पूर्व-सेंसरशिप के 1950 के मामले थे।"},
  {"id":"polity-fundamental-rights-145","question":"The right to know, as a part of the freedom of speech and expression, was first recognised by the Supreme Court in a case concerning the disclosure of the ‘Blue Book’ on the Prime Minister’s security. Which case?","options":["Indira Nehru Gandhi v. Raj Narain (1975)","S. P. Gupta v. Union of India (1981)","State of U.P. v. Raj Narain (1975)","Union of India v. Association for Democratic Reforms (2002)"],"answer":2,"explanation":"State of U.P. v. Raj Narain (1975) arose from the Allahabad election petition but was a separate case on privilege over the Blue Book. Indira Nehru Gandhi v. Raj Narain is the 39th Amendment case; ADR later gave voters a right to know about candidates.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जानने का अधिकार, वाक् और अभिव्यक्ति की स्वतंत्रता के भाग के रूप में, सर्वोच्च न्यायालय ने पहली बार प्रधानमंत्री की सुरक्षा पर ‘ब्लू बुक’ के प्रकटीकरण से संबंधित मामले में मान्य किया। कौन-सा मामला?","optionsHi":["इंदिरा नेहरू गांधी बनाम राज नारायण (1975)","एस. पी. गुप्ता बनाम भारत संघ (1981)","उत्तर प्रदेश राज्य बनाम राज नारायण (1975)","यूनियन ऑफ इंडिया बनाम एसोसिएशन फॉर डेमोक्रेटिक रिफॉर्म्स (2002)"],"explanationHi":"उत्तर प्रदेश राज्य बनाम राज नारायण (1975) इलाहाबाद चुनाव याचिका से उत्पन्न हुआ पर ब्लू बुक पर विशेषाधिकार का अलग मामला था। इंदिरा नेहरू गांधी बनाम राज नारायण 39वें संशोधन का मामला है; ADR ने बाद में मतदाताओं को उम्मीदवारों के बारे में जानने का अधिकार दिया।"},
  {"id":"polity-fundamental-rights-146","question":"In which case did the Supreme Court hold that commercial speech, such as advertising, is protected by Article 19(1)(a), departing from an earlier view that advertisements are mere trade?","options":["Hamdard Dawakhana v. Union of India (1960)","Bennett Coleman and Co. v. Union of India (1972)","Secretary, Ministry of I&B v. Cricket Association of Bengal (1995)","Tata Press Ltd. v. Mahanagar Telephone Nigam Ltd. (1995)"],"answer":3,"explanation":"Tata Press (1995), on advertisements in a telephone directory, recognised commercial speech. Hamdard Dawakhana (1960), the trap, had treated advertisements for objectionable drugs as trade rather than expression.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किस मामले में सर्वोच्च न्यायालय ने माना कि विज्ञापन जैसी वाणिज्यिक अभिव्यक्ति अनुच्छेद 19(1)(a) द्वारा संरक्षित है, इस पूर्व मत से हटकर कि विज्ञापन मात्र व्यापार हैं?","optionsHi":["हमदर्द दवाखाना बनाम भारत संघ (1960)","बेनेट कोलमैन एंड कंपनी बनाम भारत संघ (1972)","सचिव, सूचना एवं प्रसारण मंत्रालय बनाम क्रिकेट एसोसिएशन ऑफ बंगाल (1995)","टाटा प्रेस लिमिटेड बनाम महानगर टेलीफोन निगम लिमिटेड (1995)"],"explanationHi":"टाटा प्रेस (1995) ने, टेलीफोन निर्देशिका में विज्ञापनों के संबंध में, वाणिज्यिक अभिव्यक्ति को मान्यता दी। हमदर्द दवाखाना (1960), जो भ्रामक विकल्प है, ने आपत्तिजनक दवाओं के विज्ञापनों को अभिव्यक्ति नहीं बल्कि व्यापार माना था।"},
  {"id":"polity-fundamental-rights-147","question":"In which case did the Supreme Court hold that airwaves are public property to be used for the public good, and that the right to telecast a sporting event is part of the freedom of expression?","options":["Life Insurance Corporation v. Manubhai D. Shah (1992)","Tata Press Ltd. v. Mahanagar Telephone Nigam Ltd. (1995)","Ministry of I&B v. Cricket Association of Bengal (1995)","Shreya Singhal v. Union of India (2015)"],"answer":2,"explanation":"The Cricket Association of Bengal case (1995) dealt with telecasting cricket matches and called for an independent public authority to regulate airwaves. Manubhai Shah concerned a right of reply and the screening of a documentary on Doordarshan.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किस मामले में सर्वोच्च न्यायालय ने माना कि वायुतरंगें लोक हित के लिए उपयोग की जाने वाली सार्वजनिक संपत्ति हैं, और किसी खेल आयोजन के प्रसारण का अधिकार अभिव्यक्ति की स्वतंत्रता का भाग है?","optionsHi":["भारतीय जीवन बीमा निगम बनाम मनुभाई डी. शाह (1992)","टाटा प्रेस लिमिटेड बनाम महानगर टेलीफोन निगम लिमिटेड (1995)","सूचना एवं प्रसारण मंत्रालय बनाम क्रिकेट एसोसिएशन ऑफ बंगाल (1995)","श्रेया सिंघल बनाम भारत संघ (2015)"],"explanationHi":"क्रिकेट एसोसिएशन ऑफ बंगाल मामला (1995) क्रिकेट मैचों के प्रसारण से संबंधित था और वायुतरंगों के विनियमन के लिए स्वतंत्र सार्वजनिक प्राधिकरण की आवश्यकता बताई। मनुभाई शाह उत्तर देने के अधिकार और दूरदर्शन पर वृत्तचित्र के प्रदर्शन से संबंधित था।"},
  {"id":"polity-fundamental-rights-148","question":"Consider the following statements: 1. The right to form associations under Article 19(1)(c) includes a guaranteed right to go on strike. 2. In T. K. Rangarajan v. Government of Tamil Nadu (2003), the Supreme Court said government employees have no fundamental, legal or moral right to strike. 3. The right to form a union does not include a fundamental right to have it recognised or to bargain collectively. Which of the statements given above is/are correct?","options":["1 and 2 only","2 and 3 only","3 only","1, 2 and 3"],"answer":1,"explanation":"Forming a union is protected, but its activities, such as strikes, recognition and collective bargaining, are regulated by ordinary law and are not Fundamental Rights; Rangarajan applied this to government servants.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. अनुच्छेद 19(1)(c) के अंतर्गत संघ बनाने के अधिकार में हड़ताल पर जाने का सुनिश्चित अधिकार शामिल है। 2. टी. के. रंगराजन बनाम तमिलनाडु सरकार (2003) में सर्वोच्च न्यायालय ने कहा कि सरकारी कर्मचारियों को हड़ताल का कोई मौलिक, विधिक या नैतिक अधिकार नहीं है। 3. संघ बनाने के अधिकार में उसे मान्यता दिलाने या सामूहिक सौदेबाजी का मौलिक अधिकार शामिल नहीं है। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 3","1, 2 और 3"],"explanationHi":"संघ बनाना संरक्षित है, परंतु उसकी गतिविधियाँ, जैसे हड़ताल, मान्यता और सामूहिक सौदेबाजी, सामान्य कानून द्वारा विनियमित हैं और मौलिक अधिकार नहीं हैं; रंगराजन ने इसे सरकारी सेवकों पर लागू किया।"},
  {"id":"polity-fundamental-rights-149","question":"Consider the following statements about Article 20(3): 1. The protection is available to an accused even during police interrogation, before any trial begins. 2. Compelling an accused to give fingerprints or a specimen of handwriting does not violate it. 3. The protection is available to every witness in any proceeding, whether or not the witness is accused of an offence. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Nandini Satpathy (1978) extended the bar to police questioning and Kathi Kalu Oghad (1961) held that identification material is not ‘testimony’. Article 20(3) protects only a person ‘accused of any offence’.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 20(3) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. संरक्षण अभियुक्त को पुलिस पूछताछ के दौरान भी, किसी विचारण के शुरू होने से पहले, उपलब्ध है। 2. अभियुक्त को उँगलियों के निशान या हस्तलेख का नमूना देने के लिए बाध्य करना इसका उल्लंघन नहीं है। 3. संरक्षण किसी भी कार्यवाही में प्रत्येक साक्षी को उपलब्ध है, चाहे साक्षी पर अपराध का अभियोग हो या नहीं। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"नंदिनी सत्पथी (1978) ने वर्जन को पुलिस पूछताछ तक बढ़ाया और काठी कालू ओघड़ (1961) ने माना कि पहचान सामग्री ‘साक्ष्य’ नहीं है। अनुच्छेद 20(3) केवल ‘किसी अपराध के अभियुक्त’ व्यक्ति की रक्षा करता है।"},
  {"id":"polity-fundamental-rights-150","question":"Which case held that the right to life under Article 21 does not include a right to die, upheld the penal provision on attempted suicide, and overruled an earlier judgment to the contrary?","options":["Gian Kaur v. State of Punjab (1996)","P. Rathinam v. Union of India (1994)","Aruna Ramchandra Shanbaug v. Union of India (2011)","Common Cause v. Union of India (2018)"],"answer":0,"explanation":"The five-judge bench in Gian Kaur overruled P. Rathinam, which had struck down the attempted-suicide offence. Aruna Shanbaug and Common Cause later dealt with passive euthanasia and living wills.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किस मामले में सर्वोच्च न्यायालय ने माना कि अनुच्छेद 21 के जीवन के अधिकार में मरने का अधिकार शामिल नहीं है, आत्महत्या के प्रयास के दंडात्मक उपबंध को बरकरार रखा, और इसके विपरीत पहले के निर्णय को पलटा?","optionsHi":["ज्ञान कौर बनाम पंजाब राज्य (1996)","पी. रथिनम बनाम भारत संघ (1994)","अरुणा रामचंद्र शानबाग बनाम भारत संघ (2011)","कॉमन कॉज बनाम भारत संघ (2018)"],"explanationHi":"ज्ञान कौर में पाँच न्यायाधीशों की पीठ ने पी. रथिनम को पलट दिया, जिसने आत्महत्या के प्रयास के अपराध को रद्द किया था। अरुणा शानबाग और कॉमन कॉज ने बाद में निष्क्रिय इच्छामृत्यु और जीवित वसीयत को देखा।"},
  {"id":"polity-fundamental-rights-151","question":"Consider the following statements about the Right to Education: 1. In Society for Unaided Private Schools of Rajasthan (2012), the Supreme Court upheld the 25% reservation of entry-level seats in unaided non-minority schools for disadvantaged children. 2. In Pramati Educational and Cultural Trust (2014), it held that the RTE Act does not apply to minority schools, aided or unaided. 3. Pramati struck down Article 21A as violating the basic structure. Which of the statements given above is/are correct?","options":["1 and 2 only","2 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Pramati upheld both Article 21A and Article 15(5) but exempted all minority schools from the RTE Act to protect Article 30. The 2012 case upheld Section 12(1)(c) for unaided non-minority schools.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"शिक्षा के अधिकार के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. सोसायटी फॉर अनएडेड प्राइवेट स्कूल्स ऑफ राजस्थान (2012) में सर्वोच्च न्यायालय ने गैर-सहायता प्राप्त गैर-अल्पसंख्यक स्कूलों में वंचित बच्चों के लिए प्रवेश-स्तर की 25% सीटों के आरक्षण को बरकरार रखा। 2. प्रमति एजुकेशनल एंड कल्चरल ट्रस्ट (2014) में उसने माना कि RTE अधिनियम अल्पसंख्यक स्कूलों, सहायता प्राप्त या गैर-सहायता प्राप्त, पर लागू नहीं होता। 3. प्रमति ने अनुच्छेद 21A को मूल ढाँचे का उल्लंघन मानकर रद्द कर दिया। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1 और 2","केवल 2","केवल 1 और 3","1, 2 और 3"],"explanationHi":"प्रमति ने अनुच्छेद 21A और अनुच्छेद 15(5) दोनों को बरकरार रखा, परंतु अनुच्छेद 30 की रक्षा के लिए सभी अल्पसंख्यक स्कूलों को RTE अधिनियम से छूट दी। 2012 के मामले ने गैर-सहायता प्राप्त गैर-अल्पसंख्यक स्कूलों के लिए धारा 12(1)(c) को बरकरार रखा।"},
  {"id":"polity-fundamental-rights-152","question":"Under Article 22(3), the safeguards in Article 22(1) and (2), such as being told the grounds of arrest, consulting a lawyer and production before a magistrate within 24 hours, do NOT apply to:","options":["Any foreigner, and any person arrested for a non-bailable offence","A person arrested under a special criminal law such as an anti-terror law","A member of the armed forces arrested for an ordinary civil offence","An enemy alien, and a person held under a preventive detention law"],"answer":3,"explanation":"Article 22(3) excludes only enemy aliens and preventive detainees, whose separate safeguards are in Article 22(4) to (7). Ordinary foreigners and people arrested under special punitive laws keep these protections.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 22(3) के अंतर्गत अनुच्छेद 22(1) और (2) के रक्षोपाय, जैसे गिरफ्तारी के आधार बताया जाना, वकील से परामर्श और 24 घंटे के भीतर मजिस्ट्रेट के समक्ष पेशी, किन पर लागू नहीं होते?","optionsHi":["किसी भी विदेशी पर, और अजमानतीय अपराध में गिरफ्तार किसी भी व्यक्ति पर","आतंकवाद-विरोधी कानून जैसे विशेष आपराधिक कानून के अंतर्गत गिरफ्तार व्यक्ति पर","साधारण सिविल अपराध के लिए गिरफ्तार सशस्त्र बल के सदस्य पर","शत्रु विदेशी पर, और निवारक निरोध कानून के अंतर्गत निरुद्ध व्यक्ति पर"],"explanationHi":"अनुच्छेद 22(3) केवल शत्रु विदेशियों और निवारक निरोध में निरुद्ध व्यक्तियों को बाहर रखता है, जिनके अलग रक्षोपाय अनुच्छेद 22(4) से (7) में हैं। साधारण विदेशियों और विशेष दंडात्मक कानूनों के अंतर्गत गिरफ्तार लोगों को ये संरक्षण मिलते रहते हैं।"},
  {"id":"polity-fundamental-rights-153","question":"Article 23(2) allows the State to impose compulsory service for public purposes but bars discrimination in doing so on certain grounds. Which of these is NOT one of those grounds?","options":["Religion","Caste","Class","Sex"],"answer":3,"explanation":"Article 23(2) lists only religion, race, caste or class. Sex is absent, so a compulsory service scheme confined to men would not breach this clause.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 23(2) राज्य को सार्वजनिक प्रयोजनों के लिए अनिवार्य सेवा लागू करने देता है परंतु ऐसा करने में कुछ आधारों पर भेदभाव को वर्जित करता है। इनमें से कौन-सा उन आधारों में नहीं है?","optionsHi":["धर्म","जाति","वर्ग","लिंग"],"explanationHi":"अनुच्छेद 23(2) केवल धर्म, मूलवंश, जाति या वर्ग को सूचीबद्ध करता है। लिंग इसमें नहीं है, इसलिए केवल पुरुषों तक सीमित अनिवार्य सेवा योजना इस खंड का उल्लंघन नहीं करेगी।"},
  {"id":"polity-fundamental-rights-154","question":"Article 29(2) bars the denial of admission to an educational institution maintained by the State or receiving State aid on grounds only of certain factors. Which set is correct?","options":["Religion, race, caste, sex, place of birth","Religion, race, caste, sex, descent","Religion, race, caste, language","Religion, caste, language, residence"],"answer":2,"explanation":"Article 29(2) names religion, race, caste and language. Sex and place of birth belong to Article 15(1), and descent and residence to Article 16(2), which are the traps.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 29(2) राज्य द्वारा पोषित या राज्य सहायता पाने वाली शिक्षा संस्था में केवल कुछ कारणों से प्रवेश से वंचित करने को वर्जित करता है। कौन-सा समूह सही है?","optionsHi":["धर्म, मूलवंश, जाति, लिंग, जन्मस्थान","धर्म, मूलवंश, जाति, लिंग, वंश","धर्म, मूलवंश, जाति, भाषा","धर्म, जाति, भाषा, निवास"],"explanationHi":"अनुच्छेद 29(2) धर्म, मूलवंश, जाति और भाषा का नाम लेता है। लिंग और जन्मस्थान अनुच्छेद 15(1) के हैं, और वंश तथा निवास अनुच्छेद 16(2) के, जो भ्रम के कारण हैं।"},
  {"id":"polity-fundamental-rights-155","question":"In I. R. Coelho v. State of Tamil Nadu (2007), the Supreme Court held that laws placed in the Ninth Schedule:","options":["inserted after 24 April 1973 can be tested against the basic structure","are wholly immune from judicial review, whatever the date of their insertion","placed there before 1973 can be struck down for violating any Fundamental Right","can be challenged only in the Supreme Court under Article 32, not in High Courts"],"answer":0,"explanation":"The nine-judge bench took 24 April 1973, the date of Kesavananda Bharati, as the cut-off: later insertions get no blanket immunity and are tested against the basic structure, including the essence of Articles 14, 19 and 21. Earlier insertions stay protected, as upheld in Waman Rao.","difficulty":"hard","source":"UPSC Prelims","questionHi":"आई. आर. कोएलो बनाम तमिलनाडु राज्य (2007) में सर्वोच्च न्यायालय ने माना कि नौवीं अनुसूची में रखे गए कानून:","optionsHi":["24 अप्रैल 1973 के बाद जोड़े गए कानूनों की मूल ढाँचे की कसौटी पर जाँच की जा सकती है","पूरी तरह न्यायिक पुनरावलोकन से मुक्त हैं, उनके जोड़े जाने की तिथि चाहे जो हो","1973 से पहले रखे गए कानून किसी भी मौलिक अधिकार के उल्लंघन पर रद्द किए जा सकते हैं","केवल अनुच्छेद 32 के अंतर्गत सर्वोच्च न्यायालय में चुनौती दी जा सकती है, उच्च न्यायालयों में नहीं"],"explanationHi":"नौ न्यायाधीशों की पीठ ने 24 अप्रैल 1973, केशवानंद भारती की तिथि, को कट-ऑफ माना: बाद में जोड़े गए कानूनों को कोई पूर्ण उन्मुक्ति नहीं है और उनकी जाँच मूल ढाँचे की कसौटी पर होगी, जिसमें अनुच्छेद 14, 19 और 21 का सार भी शामिल है। पहले जोड़े गए कानून संरक्षित रहते हैं, जैसा वामन राव में बरकरार रखा गया।"},
  {"id":"polity-fundamental-rights-156","question":"In which case did the Bombay High Court hold that uncodified personal laws are not ‘laws in force’ within Article 13 and so cannot be tested against Fundamental Rights?","options":["Mohd. Ahmed Khan v. Shah Bano Begum","Sarla Mudgal v. Union of India","Shayara Bano v. Union of India","State of Bombay v. Narasu Appa Mali"],"answer":3,"explanation":"Narasu Appa Mali (1952) upheld a Bombay law against bigamy and held that personal law as such is outside Article 13; it was much debated in the triple talaq and Sabarimala cases.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किस मामले में बॉम्बे उच्च न्यायालय ने माना कि असंहिताबद्ध व्यक्तिगत कानून अनुच्छेद 13 के अर्थ में ‘प्रवृत्त विधियाँ’ नहीं हैं और इसलिए उन्हें मौलिक अधिकारों की कसौटी पर नहीं परखा जा सकता?","optionsHi":["मोहम्मद अहमद खान बनाम शाह बानो बेगम","सरला मुद्गल बनाम भारत संघ","शायरा बानो बनाम भारत संघ","बॉम्बे राज्य बनाम नरसु अप्पा माली"],"explanationHi":"नरसु अप्पा माली (1952) ने द्विविवाह के विरुद्ध बॉम्बे के कानून को बरकरार रखा और माना कि व्यक्तिगत कानून अपने आप में अनुच्छेद 13 से बाहर है; तीन तलाक और सबरीमाला मामलों में इस पर बहुत बहस हुई।"},
  {"id":"polity-fundamental-rights-157","question":"How many of these statements about Article 18 are correct? I. The State cannot confer any title except a military or academic distinction. II. A citizen of India cannot accept any title from a foreign State. III. A person holding an office of profit or trust under the State needs the President’s consent to accept any present, emolument or office from a foreign State. IV. Article 18 itself lays down a penalty for its breach.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III restate Article 18(1), (2) and (4). Article 18 prescribes no penalty; enforcement is left to law made by Parliament.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 18 के बारे में इनमें से कितने कथन सही हैं? I. राज्य सैनिक या शैक्षिक विशिष्टता के सिवाय कोई उपाधि प्रदान नहीं कर सकता। II. भारत का नागरिक किसी विदेशी राज्य से कोई उपाधि स्वीकार नहीं कर सकता। III. राज्य के अधीन लाभ या विश्वास का पद धारण करने वाले व्यक्ति को किसी विदेशी राज्य से कोई भेंट, उपलब्धि या पद स्वीकार करने के लिए राष्ट्रपति की सहमति चाहिए। IV. अनुच्छेद 18 स्वयं अपने उल्लंघन के लिए दंड निर्धारित करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III अनुच्छेद 18(1), (2) और (4) को दोहराते हैं। अनुच्छेद 18 कोई दंड निर्धारित नहीं करता; प्रवर्तन संसद द्वारा बनाए कानून पर छोड़ा गया है।"},
  {"id":"polity-fundamental-rights-158","question":"Which provision ensures that a law creating a State monopoly in a trade or business, such as nationalised road transport, cannot be challenged under Article 19(1)(g) merely because it excludes citizens from that trade?","options":["Article 301","Article 31C","Article 19(6)","Article 304(b)"],"answer":2,"explanation":"Article 19(6)(ii), added by the 1st Amendment (1951), protects trade carried on by the State or its corporations ‘to the exclusion, complete or partial, of citizens’. Article 301 is the freedom of inter-State trade and Article 304(b) lets States restrict it, so neither shields a monopoly from Article 19(1)(g).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कौन-सा उपबंध सुनिश्चित करता है कि किसी व्यापार या कारोबार में राज्य का एकाधिकार बनाने वाले कानून, जैसे राष्ट्रीयकृत सड़क परिवहन, को केवल इस आधार पर अनुच्छेद 19(1)(g) के अंतर्गत चुनौती नहीं दी जा सकती कि वह नागरिकों को उस व्यापार से बाहर करता है?","optionsHi":["अनुच्छेद 301","अनुच्छेद 31C","अनुच्छेद 19(6)","अनुच्छेद 304(b)"],"explanationHi":"पहले संशोधन (1951) द्वारा जोड़ा गया अनुच्छेद 19(6)(ii) राज्य या उसके निगमों द्वारा ‘नागरिकों के पूर्ण या आंशिक अपवर्जन’ के साथ किए जाने वाले व्यापार को संरक्षित करता है। अनुच्छेद 301 अंतर-राज्यीय व्यापार की स्वतंत्रता है और अनुच्छेद 304(b) राज्यों को उसे निर्बंधित करने देता है, इसलिए दोनों में से कोई एकाधिकार को अनुच्छेद 19(1)(g) से नहीं बचाता।"},
  {"id":"polity-fundamental-rights-159","question":"In K. A. Abbas v. Union of India (1970), the Supreme Court held that:","options":["pre-censorship of films is void, since every prior restraint on expression is unconstitutional","pre-censorship of films is valid, since films stir people more than other media","films are mere entertainment and so fall outside the scope of Article 19(1)(a)","only Parliament, and not an appointed board, may decide which films can be shown"],"answer":1,"explanation":"The Court upheld film censorship, noting the strong effect of moving pictures, while insisting the standards be reasonable and clearly stated.","difficulty":"hard","source":"UPSC Prelims","questionHi":"के. ए. अब्बास बनाम भारत संघ (1970) में सर्वोच्च न्यायालय ने माना कि:","optionsHi":["फिल्मों की पूर्व-सेंसरशिप शून्य है, क्योंकि अभिव्यक्ति पर प्रत्येक पूर्व निर्बंधन असंवैधानिक है","फिल्मों की पूर्व-सेंसरशिप वैध है, क्योंकि फिल्में अन्य माध्यमों से अधिक लोगों को उद्वेलित करती हैं","फिल्में मात्र मनोरंजन हैं और इसलिए अनुच्छेद 19(1)(a) के दायरे से बाहर हैं","केवल संसद, न कि नियुक्त बोर्ड, तय कर सकती है कि कौन-सी फिल्में दिखाई जा सकती हैं"],"explanationHi":"न्यायालय ने फिल्म सेंसरशिप को बरकरार रखा, चलचित्रों के प्रबल प्रभाव का उल्लेख करते हुए, साथ ही यह आग्रह किया कि मानक युक्तियुक्त और स्पष्ट रूप से बताए गए हों।"},
  {"id":"polity-fundamental-rights-160","question":"In S. Rangarajan v. P. Jagjivan Ram (1989), about a Tamil film on reservations, the Supreme Court held that:","options":["threats of protest cannot justify suppression; the danger must be like a ‘spark in a powder keg’","the State may revoke a film’s certificate whenever any group threatens violence over it","films criticising the reservation policy may be banned because they disturb public order","certification decisions of the Censor Board are final and cannot be reviewed by any court of law"],"answer":0,"explanation":"The Court restored the film’s certificate, holding that the State must protect expression rather than give in to threats, and that restriction needs a proximate and direct link to public disorder.","difficulty":"hard","source":"UPSC Prelims","questionHi":"एस. रंगराजन बनाम पी. जगजीवन राम (1989) में, जो आरक्षण पर एक तमिल फिल्म से संबंधित था, सर्वोच्च न्यायालय ने माना कि:","optionsHi":["विरोध की धमकियाँ दमन को उचित नहीं ठहरा सकतीं; खतरा ‘बारूद के ढेर में चिंगारी’ जैसा होना चाहिए","जब भी कोई समूह किसी फिल्म पर हिंसा की धमकी दे, राज्य फिल्म का प्रमाणपत्र रद्द कर सकता है","आरक्षण नीति की आलोचना करने वाली फिल्मों पर प्रतिबंध लगाया जा सकता है क्योंकि वे लोक व्यवस्था बिगाड़ती हैं","सेंसर बोर्ड के प्रमाणन निर्णय अंतिम हैं और किसी न्यायालय द्वारा पुनर्विलोकित नहीं किए जा सकते"],"explanationHi":"न्यायालय ने फिल्म का प्रमाणपत्र बहाल किया, यह मानते हुए कि राज्य को धमकियों के आगे झुकने के बजाय अभिव्यक्ति की रक्षा करनी चाहिए, और निर्बंधन के लिए लोक अव्यवस्था से निकट और प्रत्यक्ष संबंध आवश्यक है।"},
  {"id":"polity-fundamental-rights-161","question":"A tribunal begins hearing a dispute that is clearly outside its jurisdiction, and the hearing is still going on. An aggrieved party wants a higher court to stop it from proceeding further. The appropriate writ is:","options":["Certiorari","Prohibition","Mandamus","Quo warranto"],"answer":1,"explanation":"Prohibition is preventive and issues while the proceedings are pending; certiorari is curative and quashes a decision already made. Both lie against judicial and quasi-judicial bodies.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"कोई अधिकरण ऐसे विवाद की सुनवाई शुरू करता है जो स्पष्ट रूप से उसकी अधिकारिता से बाहर है, और सुनवाई अभी जारी है। पीड़ित पक्ष चाहता है कि उच्च न्यायालय उसे आगे बढ़ने से रोके। उपयुक्त रिट कौन-सी है?","optionsHi":["उत्प्रेषण","प्रतिषेध","परमादेश","अधिकार पृच्छा"],"explanationHi":"प्रतिषेध निवारक है और कार्यवाही लंबित रहते जारी होती है; उत्प्रेषण उपचारात्मक है और पहले ही लिए गए निर्णय को रद्द करता है। दोनों न्यायिक और अर्ध-न्यायिक निकायों के विरुद्ध लागू होते हैं।"},
  {"id":"polity-fundamental-rights-162","question":"A private restaurant open to the public refuses entry to a customer because of his caste. Which provision directly forbids this, even though the restaurant is not ‘the State’?","options":["Article 14","Article 15(2)","Article 16(2)","Article 29(2)"],"answer":1,"explanation":"Article 15(2) bars restrictions on access to shops, public restaurants, hotels and places of public entertainment, and so binds private persons. Article 14 binds only the State, 16(2) concerns public jobs and 29(2) admission to aided institutions.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"जनता के लिए खुला एक निजी रेस्तरां किसी ग्राहक को उसकी जाति के कारण प्रवेश देने से इनकार करता है। कौन-सा उपबंध इसे सीधे वर्जित करता है, भले ही रेस्तरां ‘राज्य’ नहीं है?","optionsHi":["अनुच्छेद 14","अनुच्छेद 15(2)","अनुच्छेद 16(2)","अनुच्छेद 29(2)"],"explanationHi":"अनुच्छेद 15(2) दुकानों, सार्वजनिक रेस्तराँओं, होटलों और सार्वजनिक मनोरंजन के स्थानों तक पहुँच पर निर्बंधन को वर्जित करता है, और इसलिए निजी व्यक्तियों पर बाध्यकारी है। अनुच्छेद 14 केवल राज्य पर बाध्यकारी है, 16(2) लोक नौकरियों से और 29(2) सहायता प्राप्त संस्थाओं में प्रवेश से संबंधित है।"},
  {"id":"polity-fundamental-rights-163","question":"Under Article 26, which right of a religious denomination is expressly to be exercised ‘in accordance with law’?","options":["To establish and maintain institutions for religious and charitable purposes","To manage its own affairs in matters of religion","To own and acquire movable and immovable property","To administer its property"],"answer":3,"explanation":"Clause (d) lets a denomination administer its property ‘in accordance with law’, so the State may regulate administration but cannot take it away altogether, as held in Ratilal Panachand Gandhi (1954).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 26 के अंतर्गत धार्मिक संप्रदाय का कौन-सा अधिकार स्पष्ट रूप से ‘विधि के अनुसार’ प्रयोग किया जाना है?","optionsHi":["धार्मिक और पूर्त प्रयोजनों के लिए संस्थाएँ स्थापित और पोषित करना","धर्म के विषयों में अपने कार्यों का प्रबंध करना","जंगम और स्थावर संपत्ति का स्वामित्व और अर्जन","अपनी संपत्ति का प्रशासन करना"],"explanationHi":"खंड (d) संप्रदाय को अपनी संपत्ति का प्रशासन ‘विधि के अनुसार’ करने देता है, इसलिए राज्य प्रशासन को विनियमित कर सकता है पर उसे पूरी तरह छीन नहीं सकता, जैसा रतिलाल पानाचंद गांधी (1954) में माना गया।"},
  {"id":"polity-fundamental-rights-164","question":"In which case did the Supreme Court first hold that Article 16(4) is not an exception to Article 16(1) but a facet of equality of opportunity itself?","options":["State of Kerala v. N. M. Thomas (1976)","M. R. Balaji v. State of Mysore (1962)","Indra Sawhney v. Union of India (1992)","State of Madras v. Champakam Dorairajan (1951)"],"answer":0,"explanation":"N. M. Thomas (1976) treated Article 16(4) as a facet of the equality of opportunity in Article 16(1), a view Indra Sawhney (1992) later endorsed. Earlier cases such as T. Devadasan (1964), following M. R. Balaji (1962, an Article 15(4) case that suggested keeping reservations below 50%), had treated such provisions as exceptions.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किस मामले में सर्वोच्च न्यायालय ने पहली बार माना कि अनुच्छेद 16(4) अनुच्छेद 16(1) का अपवाद नहीं बल्कि स्वयं अवसर की समता का एक पहलू है?","optionsHi":["केरल राज्य बनाम एन. एम. थॉमस (1976)","एम. आर. बालाजी बनाम मैसूर राज्य (1962)","इंद्रा साहनी बनाम भारत संघ (1992)","मद्रास राज्य बनाम चंपकम दोराईराजन (1951)"],"explanationHi":"एन. एम. थॉमस (1976) ने अनुच्छेद 16(4) को अनुच्छेद 16(1) की अवसर की समता का पहलू माना, जिसका इंद्रा साहनी (1992) ने बाद में समर्थन किया। टी. देवदासन (1964) जैसे पहले के मामलों ने, एम. आर. बालाजी (1962, अनुच्छेद 15(4) का मामला जिसने आरक्षण को 50% से नीचे रखने का सुझाव दिया) का अनुसरण करते हुए, ऐसे उपबंधों को अपवाद माना था।"},
  {"id":"polity-fundamental-rights-165","question":"Consider the following statements: 1. M. R. Balaji (1962) first said that reservations should generally stay below 50%. 2. Indra Sawhney (1992) held that Article 16(4) does not permit reservation in promotions. 3. Indra Sawhney upheld the 10% reservation for economically poorer sections not covered by other reservation schemes. Which of the statements given above is/are correct?","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Indra Sawhney struck down the 1991 order reserving 10% on an economic criterion alone, and ruled out reservation in promotions, which led to Article 16(4A) in 1995. Economic reservation came only with the 103rd Amendment (2019).","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. एम. आर. बालाजी (1962) ने पहली बार कहा कि आरक्षण सामान्यतः 50% से कम रहना चाहिए। 2. इंद्रा साहनी (1992) ने माना कि अनुच्छेद 16(4) पदोन्नति में आरक्षण की अनुमति नहीं देता। 3. इंद्रा साहनी ने अन्य आरक्षण योजनाओं के अंतर्गत न आने वाले आर्थिक रूप से गरीब वर्गों के लिए 10% आरक्षण को बरकरार रखा। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"इंद्रा साहनी ने केवल आर्थिक मानदंड पर 10% आरक्षण देने वाले 1991 के आदेश को रद्द किया, और पदोन्नति में आरक्षण को अस्वीकार किया, जिसके कारण 1995 में अनुच्छेद 16(4A) आया। आर्थिक आरक्षण 103वें संशोधन (2019) से ही आया।"},
  {"id":"polity-fundamental-rights-166","question":"A law passed in 2020 increases the punishment for an offence. A person who committed that offence in 2018 is tried in 2021. Under Article 20(1), he can be given:","options":["only the penalty in force when the offence was committed","the higher penalty, since the trial took place after the new law","either penalty, at the court’s discretion","no penalty, since the law has changed since the offence"],"answer":0,"explanation":"Article 20(1) bars a penalty greater than the one in force when the act was committed. What matters is the date of the offence, not the date of trial.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"2020 में पारित कोई कानून किसी अपराध का दंड बढ़ाता है। 2018 में वह अपराध करने वाले व्यक्ति पर 2021 में मुकदमा चलता है। अनुच्छेद 20(1) के अंतर्गत उसे क्या दंड दिया जा सकता है?","optionsHi":["केवल वही दंड जो अपराध करते समय लागू था","अधिक दंड, क्योंकि विचारण नए कानून के बाद हुआ","न्यायालय के विवेक से कोई भी दंड","कोई दंड नहीं, क्योंकि अपराध के बाद कानून बदल गया है"],"explanationHi":"अनुच्छेद 20(1) कृत्य करते समय लागू दंड से अधिक दंड को वर्जित करता है। महत्त्व अपराध की तिथि का है, विचारण की तिथि का नहीं।"},
  {"id":"polity-fundamental-rights-167","question":"Article 32(2) empowers the Supreme Court to issue directions, orders or writs, ‘including writs in the nature of’ five named writs. Which of these is NOT one of them?","options":["Quo warranto","Certiorari","Injunction","Prohibition"],"answer":2,"explanation":"The five named writs are habeas corpus, mandamus, prohibition, quo warranto and certiorari. An injunction is a civil remedy, though the Court may issue other directions too.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"अनुच्छेद 32(2) सर्वोच्च न्यायालय को निदेश, आदेश या रिट जारी करने का अधिकार देता है, ‘जिनमें पाँच नामित रिटों की प्रकृति की रिटें भी शामिल हैं’। इनमें से कौन-सी उनमें नहीं है?","optionsHi":["अधिकार पृच्छा","उत्प्रेषण","व्यादेश (injunction)","प्रतिषेध"],"explanationHi":"पाँच नामित रिटें हैं बंदी प्रत्यक्षीकरण, परमादेश, प्रतिषेध, अधिकार पृच्छा और उत्प्रेषण। व्यादेश सिविल उपचार है, यद्यपि न्यायालय अन्य निदेश भी जारी कर सकता है।"},
  {"id":"polity-fundamental-rights-168","question":"Article 15(2) bars denying a citizen access to certain places on grounds only of religion, race, caste, sex or place of birth. To which of these does Article 15(2) apply?","options":["A well dug and maintained by a private trust solely for the use of its own members","A bathing ghat built by a private person but dedicated to the use of the general public","A swimming pool in a private residential club that admits only its own enrolled members","A playground of a private unaided school that is open only to its own enrolled pupils"],"answer":1,"explanation":"Article 15(2)(b) covers wells, tanks, bathing ghats, roads and places of public resort maintained wholly or partly out of State funds OR dedicated to the use of the general public, so public dedication is enough even without State money. The other places are not open to the public at all.","difficulty":"very-hard","source":"UPSC Prelims · State PSCs","questionHi":"अनुच्छेद 15(2) नागरिक को केवल धर्म, मूलवंश, जाति, लिंग या जन्मस्थान के आधार पर कुछ स्थानों तक पहुँच से वंचित करने को वर्जित करता है। अनुच्छेद 15(2) इनमें से किस पर लागू होता है?","optionsHi":["निजी न्यास द्वारा केवल अपने सदस्यों के उपयोग के लिए खोदा और रखरखाव किया जाने वाला कुआँ","किसी निजी व्यक्ति द्वारा बनाया गया पर आम जनता के उपयोग के लिए समर्पित स्नान घाट","निजी आवासीय क्लब का तरण-ताल जो केवल अपने पंजीकृत सदस्यों को प्रवेश देता है","निजी गैर-सहायता प्राप्त स्कूल का खेल का मैदान जो केवल अपने पंजीकृत विद्यार्थियों के लिए खुला है"],"explanationHi":"अनुच्छेद 15(2)(b) पूर्णतः या भागतः राज्य निधि से पोषित या आम जनता के उपयोग के लिए समर्पित कुओं, तालाबों, स्नान घाटों, सड़कों और सार्वजनिक समागम स्थलों को कवर करता है, इसलिए राज्य के धन के बिना भी जनता को समर्पित होना पर्याप्त है। अन्य स्थान जनता के लिए खुले ही नहीं हैं।"},
  {"id":"polity-fundamental-rights-169","question":"In Pradeep Kumar Biswas v. Indian Institute of Chemical Biology (2002), a seven-judge bench ruled on the status of the Council of Scientific and Industrial Research (CSIR). It held that CSIR:","options":["Is not ‘State’, because it is only a society registered under the Societies Registration Act","Is ‘State’ only for claims under Articles 14 and 16, and not for any of the other Fundamental Rights","Is ‘State’ under Article 12, and it overruled Sabhajit Tewary (1975), which had held otherwise","Is ‘State’ only because it was created directly by an Act of Parliament as a statutory body"],"answer":2,"explanation":"Applying the test of deep and pervasive financial, functional and administrative control by the government, the Court held CSIR to be an ‘other authority’ under Article 12 and overruled Sabhajit Tewary. Registration as a society does not settle the question, and CSIR is not a statutory body.","difficulty":"hard","source":"UPSC Prelims","questionHi":"प्रदीप कुमार बिस्वास बनाम भारतीय रासायनिक जैविकी संस्थान (2002) में सात न्यायाधीशों की पीठ ने वैज्ञानिक और औद्योगिक अनुसंधान परिषद (CSIR) की स्थिति पर निर्णय दिया। उसने माना कि CSIR:","optionsHi":["‘राज्य’ नहीं है, क्योंकि वह केवल सोसायटी रजिस्ट्रीकरण अधिनियम के अंतर्गत पंजीकृत सोसायटी है","केवल अनुच्छेद 14 और 16 के दावों के लिए ‘राज्य’ है, अन्य मौलिक अधिकारों के लिए नहीं","अनुच्छेद 12 के अंतर्गत ‘राज्य’ है, और उसने सभाजीत तिवारी (1975), जिसने अन्यथा माना था, को पलट दिया","केवल इसलिए ‘राज्य’ है कि वह संसद के अधिनियम द्वारा सीधे सांविधिक निकाय के रूप में बनी"],"explanationHi":"सरकार के गहरे और व्यापक वित्तीय, कार्यात्मक और प्रशासनिक नियंत्रण की कसौटी लागू करते हुए न्यायालय ने CSIR को अनुच्छेद 12 के अंतर्गत ‘अन्य प्राधिकारी’ माना और सभाजीत तिवारी को पलट दिया। सोसायटी के रूप में पंजीकरण प्रश्न को तय नहीं करता, और CSIR सांविधिक निकाय नहीं है।"},
  {"id":"polity-fundamental-rights-170","question":"In Mithu v. State of Punjab (1983), the Supreme Court struck down Section 303 of the Indian Penal Code. What did that section provide?","options":["Death by hanging as the only lawful method of carrying out every death sentence","Life imprisonment without any remission for a person convicted of murder twice","A death sentence for murder at the trial judge's discretion without recorded reasons","A mandatory death sentence for murder committed by a person already serving life"],"answer":3,"explanation":"Section 303 left the court no choice: a life convict who committed murder had to be sentenced to death. The Court held a mandatory death sentence unfair, unjust and unreasonable under Articles 14 and 21. Hanging as a method was upheld separately in Deena Dayal (1983).","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"मिठू बनाम पंजाब राज्य (1983) में सर्वोच्च न्यायालय ने भारतीय दंड संहिता की धारा 303 को रद्द किया। उस धारा में क्या प्रावधान था?","optionsHi":["प्रत्येक मृत्युदंड को लागू करने की एकमात्र वैध पद्धति के रूप में फाँसी","दो बार हत्या के लिए दोषसिद्ध व्यक्ति के लिए बिना किसी परिहार के आजीवन कारावास","विचारण न्यायाधीश के विवेक पर, कारण दर्ज किए बिना, हत्या के लिए मृत्युदंड","आजीवन कारावास भुगत रहे व्यक्ति द्वारा की गई हत्या के लिए अनिवार्य मृत्युदंड"],"explanationHi":"धारा 303 ने न्यायालय को कोई विकल्प नहीं छोड़ा: आजीवन कारावास का दोषसिद्ध जो हत्या करे, उसे मृत्युदंड देना ही पड़ता था। न्यायालय ने अनिवार्य मृत्युदंड को अनुच्छेद 14 और 21 के अंतर्गत अनुचित, अन्यायपूर्ण और अयुक्तियुक्त माना। फाँसी की पद्धति को अलग से दीना दयाल (1983) में बरकरार रखा गया।"},
  {"id":"polity-fundamental-rights-171","question":"How many of these statements about the right to property today are correct? I. It is a constitutional right under Article 300A in Part XII. II. A person deprived of property can move the Supreme Court directly under Article 32 to enforce it. III. Deprivation must be by authority of law, so an executive order without legal backing is not enough. IV. The 42nd Amendment, 1976 removed both Article 19(1)(f) and Article 31 from Part III.","options":["Only three","Only two","Only one","All four"],"answer":1,"explanation":"I and III are correct: property is a constitutional right under Article 300A, and any deprivation needs authority of law. II is wrong: it cannot be enforced under Article 32. IV is wrong: Articles 19(1)(f) and 31 were removed by the 44th Amendment (1978), not the 42nd.","difficulty":"hard","source":"UPSC Prelims","questionHi":"आज संपत्ति के अधिकार के बारे में इनमें से कितने कथन सही हैं? I. यह भाग XII में अनुच्छेद 300A के अंतर्गत संवैधानिक अधिकार है। II. संपत्ति से वंचित व्यक्ति इसे लागू कराने के लिए अनुच्छेद 32 के अंतर्गत सीधे सर्वोच्च न्यायालय जा सकता है। III. वंचन विधि के प्राधिकार से होना चाहिए, इसलिए विधिक आधार के बिना कार्यपालिका का आदेश पर्याप्त नहीं है। IV. 42वें संशोधन, 1976 ने अनुच्छेद 19(1)(f) और अनुच्छेद 31 दोनों को भाग III से हटा दिया।","optionsHi":["केवल तीन","केवल दो","केवल एक","सभी चार"],"explanationHi":"I और III सही हैं: संपत्ति अनुच्छेद 300A के अंतर्गत संवैधानिक अधिकार है, और किसी भी वंचन के लिए विधि का प्राधिकार आवश्यक है। II गलत है: इसे अनुच्छेद 32 के अंतर्गत लागू नहीं कराया जा सकता। IV गलत है: अनुच्छेद 19(1)(f) और 31 को 44वें संशोधन (1978) ने हटाया था, 42वें ने नहीं।"},
  {"id":"polity-fundamental-rights-172","question":"Consider these statements about Article 14: 1. ‘Equality before law’ is a negative concept of British origin, while ‘equal protection of the laws’ is a positive concept drawn from the US Constitution. 2. Article 14 protects any person, including a company or a foreign national. 3. The immunity of the President and Governors from criminal proceedings during their term under Article 361 is an exception to equality before law. Which of these are correct?","options":["1 and 2 only","1, 2 and 3","2 and 3 only","1 and 3 only"],"answer":1,"explanation":"Article 14 combines the British idea of no special privilege before the law with the American idea of equal treatment in equal circumstances, and its word ‘person’ covers companies and foreigners. Article 361 immunity for the President and Governors is a recognised exception to equality before law, so all three are correct.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 14 के बारे में इन कथनों पर विचार कीजिए: 1. ‘विधि के समक्ष समता’ ब्रिटिश मूल की नकारात्मक अवधारणा है, जबकि ‘विधियों का समान संरक्षण’ अमेरिकी संविधान से ली गई सकारात्मक अवधारणा है। 2. अनुच्छेद 14 किसी भी व्यक्ति की रक्षा करता है, जिसमें कंपनी या विदेशी नागरिक भी शामिल हैं। 3. अनुच्छेद 361 के अंतर्गत राष्ट्रपति और राज्यपालों को पदावधि के दौरान आपराधिक कार्यवाही से उन्मुक्ति विधि के समक्ष समता का अपवाद है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","1, 2 और 3","केवल 2 और 3","केवल 1 और 3"],"explanationHi":"अनुच्छेद 14 विधि के समक्ष किसी विशेषाधिकार के न होने के ब्रिटिश विचार को समान परिस्थितियों में समान व्यवहार के अमेरिकी विचार से जोड़ता है, और इसका शब्द ‘व्यक्ति’ कंपनियों और विदेशियों को कवर करता है। राष्ट्रपति और राज्यपालों की अनुच्छेद 361 उन्मुक्ति विधि के समक्ष समता का मान्य अपवाद है, इसलिए तीनों सही हैं।"},
  {"id":"polity-fundamental-rights-173","question":"In Anuj Garg v. Hotel Association of India (2007), the Supreme Court struck down a provision of the Punjab Excise Act, 1914, as applied in Delhi, that barred:","options":["Women from holding a licence to run a liquor vend anywhere in the National Capital Territory","Persons below 25 from buying liquor at any licensed shop in the National Capital Territory","Men below 25 and all women from being employed where liquor is consumed by the public","Women from serving as excise inspectors in districts that had declared total prohibition"],"answer":2,"explanation":"Section 30 barred employing any man under 25 or any woman in premises where liquor is consumed by the public. The Court held that ‘protective’ laws resting on stereotypes about women must pass strict scrutiny and proportionality, and struck the bar down under Articles 14, 15 and 19(1)(g).","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुज गर्ग बनाम होटल एसोसिएशन ऑफ इंडिया (2007) में सर्वोच्च न्यायालय ने पंजाब आबकारी अधिनियम, 1914 के उस उपबंध को, जैसा वह दिल्ली में लागू था, रद्द किया जो वर्जित करता था:","optionsHi":["महिलाओं को राष्ट्रीय राजधानी क्षेत्र में कहीं भी शराब की दुकान चलाने का लाइसेंस रखने से","25 वर्ष से कम आयु के व्यक्तियों को राष्ट्रीय राजधानी क्षेत्र की किसी भी लाइसेंसशुदा दुकान से शराब खरीदने से","25 वर्ष से कम आयु के पुरुषों और सभी महिलाओं को उन स्थानों पर नियोजित होने से जहाँ जनता शराब पीती है","महिलाओं को उन जिलों में आबकारी निरीक्षक के रूप में सेवा देने से जहाँ पूर्ण मद्यनिषेध घोषित था"],"explanationHi":"धारा 30 ने 25 वर्ष से कम आयु के किसी भी पुरुष या किसी भी महिला को उन परिसरों में नियोजित करने से रोका जहाँ जनता शराब पीती है। न्यायालय ने माना कि महिलाओं के बारे में रूढ़ियों पर आधारित ‘संरक्षणात्मक’ कानूनों को कठोर संवीक्षा और आनुपातिकता की कसौटी पर खरा उतरना होगा, और अनुच्छेद 14, 15 और 19(1)(g) के अंतर्गत वर्जन को रद्द किया।"},
  {"id":"polity-fundamental-rights-174","question":"In which case did the Supreme Court hold that telephone tapping invades the right to privacy under Article 21, and lay down safeguards for interception orders under the Indian Telegraph Act, 1885?","options":["R. Rajagopal v. State of Tamil Nadu (1994)","Kharak Singh v. State of Uttar Pradesh (1963)","Govind v. State of Madhya Pradesh (1975)","PUCL v. Union of India (1997)"],"answer":3,"explanation":"In PUCL (1997) the Court held a telephone conversation to be part of private life, so interception must follow safeguards such as orders by the Home Secretary and review by a committee. Rajagopal dealt with privacy against press publication; Kharak Singh and Govind dealt with police surveillance.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"किस मामले में सर्वोच्च न्यायालय ने माना कि टेलीफोन टैपिंग अनुच्छेद 21 के अंतर्गत निजता के अधिकार का अतिक्रमण है, और भारतीय तार अधिनियम, 1885 के अंतर्गत अंतरावरोध (interception) आदेशों के लिए रक्षोपाय निर्धारित किए?","optionsHi":["आर. राजगोपाल बनाम तमिलनाडु राज्य (1994)","खड़क सिंह बनाम उत्तर प्रदेश राज्य (1963)","गोविंद बनाम मध्य प्रदेश राज्य (1975)","पीयूसीएल बनाम भारत संघ (1997)"],"explanationHi":"पीयूसीएल (1997) में न्यायालय ने टेलीफोन वार्तालाप को निजी जीवन का भाग माना, इसलिए अंतरावरोध को गृह सचिव के आदेश और समिति द्वारा पुनर्विलोकन जैसे रक्षोपायों का पालन करना चाहिए। राजगोपाल प्रेस प्रकाशन के विरुद्ध निजता से और खड़क सिंह तथा गोविंद पुलिस निगरानी से संबंधित थे।"},
  {"id":"polity-fundamental-rights-175","question":"A State law charges religious institutions a fee to meet the cost of a department that supervises the proper administration of their endowments. Judged against Article 27, the levy is:","options":["Valid, as Article 27 bars only a tax that promotes a religion, not a fee for a service","Invalid, because Article 27 forbids every compulsory payment demanded from a religious body","Valid only if the fee is collected at the same rate from the institutions of every religion","Invalid, because only Parliament may levy a charge on religious endowments under Article 26"],"answer":0,"explanation":"In the 1954 religious endowments cases the Supreme Court held that Article 27 bars a tax whose proceeds are appropriated to promote or maintain a religion. A fee that pays for supervising the secular administration of endowments is not such a tax, so it is valid.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कोई राज्य कानून धार्मिक संस्थाओं से उनके बंदोबस्तों के उचित प्रशासन की निगरानी करने वाले विभाग की लागत पूरी करने के लिए शुल्क लेता है। अनुच्छेद 27 की कसौटी पर यह उद्ग्रहण है:","optionsHi":["वैध, क्योंकि अनुच्छेद 27 केवल धर्म को बढ़ावा देने वाले कर को वर्जित करता है, सेवा के शुल्क को नहीं","अवैध, क्योंकि अनुच्छेद 27 धार्मिक निकाय से माँगे गए प्रत्येक अनिवार्य भुगतान को वर्जित करता है","वैध केवल तभी जब शुल्क प्रत्येक धर्म की संस्थाओं से एक ही दर पर वसूला जाए","अवैध, क्योंकि अनुच्छेद 26 के अंतर्गत केवल संसद ही धार्मिक बंदोबस्तों पर प्रभार लगा सकती है"],"explanationHi":"1954 के धार्मिक बंदोबस्त मामलों में सर्वोच्च न्यायालय ने माना कि अनुच्छेद 27 ऐसे कर को वर्जित करता है जिसकी आगम किसी धर्म को बढ़ावा देने या बनाए रखने में लगाई जाए। बंदोबस्तों के धर्मनिरपेक्ष प्रशासन की निगरानी का खर्च उठाने वाला शुल्क ऐसा कर नहीं है, इसलिए वह वैध है।"},
  {"id":"polity-fundamental-rights-176","question":"In M. Ismail Faruqui v. Union of India (1994), upholding the acquisition of land at Ayodhya, the Supreme Court made which observation on Articles 25 and 26?","options":["A place of worship of any religion is immune from compulsory acquisition by the State","A mosque is not an essential part of the practice of Islam, and namaz can be offered anywhere","Religious property can be acquired only if the religious denomination concerned gives its consent","Places of worship can be acquired only under a law that Article 31A saves from challenge"],"answer":1,"explanation":"The Court held that places of worship, mosques included, can be acquired under the State's sovereign power, since a mosque is not essential to Islamic practice and prayer may be offered even in the open. Only a place of special significance, whose loss would hit the religion itself, could claim protection.","difficulty":"hard","source":"UPSC Prelims","questionHi":"एम. इस्माइल फारूकी बनाम भारत संघ (1994) में, जिसने अयोध्या में भूमि के अधिग्रहण को बरकरार रखा, सर्वोच्च न्यायालय ने अनुच्छेद 25 और 26 पर कौन-सी टिप्पणी की?","optionsHi":["किसी भी धर्म का पूजा स्थल राज्य द्वारा अनिवार्य अधिग्रहण से उन्मुक्त है","मस्जिद इस्लाम के आचरण का अनिवार्य भाग नहीं है, और नमाज कहीं भी पढ़ी जा सकती है","धार्मिक संपत्ति का अधिग्रहण तभी हो सकता है जब संबंधित धार्मिक संप्रदाय सहमति दे","पूजा स्थलों का अधिग्रहण केवल ऐसे कानून के अंतर्गत हो सकता है जिसे अनुच्छेद 31A चुनौती से बचाता हो"],"explanationHi":"न्यायालय ने माना कि मस्जिदों सहित पूजा स्थलों का अधिग्रहण राज्य की संप्रभु शक्ति से हो सकता है, क्योंकि मस्जिद इस्लामी आचरण के लिए अनिवार्य नहीं है और प्रार्थना खुले में भी की जा सकती है। केवल विशेष महत्व का स्थान, जिसके खोने से धर्म पर ही आघात हो, संरक्षण का दावा कर सकता था।"},
  {"id":"polity-fundamental-rights-177","question":"Arrange these preventive detention laws in the order in which they were enacted: 1. National Security Act 2. Maintenance of Internal Security Act 3. Preventive Detention Act 4. Conservation of Foreign Exchange and Prevention of Smuggling Activities Act","options":["3, 2, 1, 4","2, 3, 4, 1","3, 2, 4, 1","3, 4, 2, 1"],"answer":2,"explanation":"Preventive Detention Act 1950, MISA 1971, COFEPOSA 1974 and NSA 1980. All of them rest on Article 22, which permits preventive detention subject to the Advisory Board safeguards.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"इन निवारक निरोध कानूनों को उनके अधिनियमित होने के क्रम में व्यवस्थित कीजिए: 1. राष्ट्रीय सुरक्षा अधिनियम 2. आंतरिक सुरक्षा व्यवस्था अधिनियम (MISA) 3. निवारक निरोध अधिनियम 4. विदेशी मुद्रा संरक्षण और तस्करी निवारण अधिनियम (COFEPOSA)","optionsHi":["3, 2, 1, 4","2, 3, 4, 1","3, 2, 4, 1","3, 4, 2, 1"],"explanationHi":"निवारक निरोध अधिनियम 1950, MISA 1971, COFEPOSA 1974 और NSA 1980। ये सभी अनुच्छेद 22 पर आधारित हैं, जो सलाहकार बोर्ड के रक्षोपायों के अधीन निवारक निरोध की अनुमति देता है।"},
  {"id":"polity-fundamental-rights-178","question":"In Secretary, Ministry of Defence v. Babita Puniya (2020), the Supreme Court:","options":["Upheld limits on command postings for women officers as based on their differing physical standards","Held that Article 33 bars any challenge to Army service rules on the ground of equality","Upheld the exclusion of women from the National Defence Academy as a reasonable classification","Directed that women officers on Short Service Commission be considered for Permanent Commission"],"answer":3,"explanation":"The Court rejected arguments based on physiology and social norms as stereotypes, held that women SSC officers must be considered for Permanent Commission and command posts, and treated this as a matter of equality under Article 14. Article 33 lets Parliament restrict rights by law; it does not bar such claims.","difficulty":"hard","source":"UPSC Prelims","questionHi":"सचिव, रक्षा मंत्रालय बनाम बबीता पुनिया (2020) में सर्वोच्च न्यायालय ने:","optionsHi":["महिला अधिकारियों के लिए कमान की नियुक्तियों पर सीमाओं को उनके भिन्न शारीरिक मानकों पर आधारित मानकर बरकरार रखा","माना कि अनुच्छेद 33 समता के आधार पर सेना की सेवा नियमों को किसी भी चुनौती को वर्जित करता है","महिलाओं को राष्ट्रीय रक्षा अकादमी से बाहर रखने को युक्तियुक्त वर्गीकरण मानकर बरकरार रखा","निर्देश दिया कि शॉर्ट सर्विस कमीशन की महिला अधिकारियों पर स्थायी कमीशन के लिए विचार किया जाए"],"explanationHi":"न्यायालय ने शरीर-क्रिया विज्ञान और सामाजिक मानदंडों पर आधारित तर्कों को रूढ़ियाँ मानकर अस्वीकार किया, माना कि महिला SSC अधिकारियों पर स्थायी कमीशन और कमान पदों के लिए विचार किया जाना चाहिए, और इसे अनुच्छेद 14 के अंतर्गत समता का विषय माना। अनुच्छेद 33 संसद को कानून द्वारा अधिकार प्रतिबंधित करने देता है; यह ऐसे दावों को वर्जित नहीं करता।"},
  {"id":"polity-fundamental-rights-179","question":"In Supriyo v. Union of India (2023), the Constitution Bench hearing petitions on marriage equality for queer couples:","options":["Held unanimously that there is no Fundamental Right to marry, leaving recognition to Parliament","Held by a 3:2 majority that queer couples have a Fundamental Right to marry under Article 21","Read the Special Marriage Act, 1954 by a 3:2 majority so as to include couples of the same sex as well","Struck down the Special Marriage Act, 1954 to the extent that it excluded same-sex couples"],"answer":0,"explanation":"All five judges declined to strike down or read words into the Special Marriage Act and held that there is no unqualified Fundamental Right to marry. They split 3:2 on recognising civil unions, which the majority also left to the legislature.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सुप्रियो बनाम भारत संघ (2023) में समलैंगिक जोड़ों के विवाह की समानता पर याचिकाओं की सुनवाई करने वाली संविधान पीठ ने:","optionsHi":["सर्वसम्मति से माना कि विवाह का कोई मौलिक अधिकार नहीं है, मान्यता का विषय संसद पर छोड़ा","3:2 के बहुमत से माना कि समलैंगिक जोड़ों को अनुच्छेद 21 के अंतर्गत विवाह का मौलिक अधिकार है","विशेष विवाह अधिनियम, 1954 को 3:2 के बहुमत से इस प्रकार पढ़ा कि उसमें समान लिंग के जोड़े भी शामिल हों","विशेष विवाह अधिनियम, 1954 को, जहाँ तक वह समलैंगिक जोड़ों को बाहर रखता है, रद्द कर दिया"],"explanationHi":"पाँचों न्यायाधीशों ने विशेष विवाह अधिनियम को रद्द करने या उसमें शब्द पढ़ने से इनकार किया और माना कि विवाह का कोई अप्रतिबंधित मौलिक अधिकार नहीं है। सिविल यूनियन की मान्यता पर वे 3:2 से बँटे, जिसे बहुमत ने भी विधायिका पर छोड़ा।"},
  {"id":"polity-fundamental-rights-180","question":"In Aishat Shifa v. State of Karnataka (2022), on the ban on wearing the hijab in government pre-university colleges, the two-judge bench:","options":["Unanimously upheld the ban, holding that the hijab is not an essential religious practice","Gave a split verdict, so the matter went to the Chief Justice for a larger bench","Unanimously struck down the ban as violating Articles 19(1)(a) and 25 of the Constitution","Declined to decide the case and tagged it with the pending Sabarimala review reference"],"answer":1,"explanation":"Justice Hemant Gupta upheld the Karnataka High Court ruling that sustained the ban, while Justice Sudhanshu Dhulia set it aside, stressing choice and girls' education. A split verdict of a two-judge bench sends the case to the Chief Justice for a larger bench.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"आयशत शिफा बनाम कर्नाटक राज्य (2022) में, जो सरकारी पूर्व-विश्वविद्यालय महाविद्यालयों में हिजाब पहनने पर प्रतिबंध से संबंधित था, दो न्यायाधीशों की पीठ ने:","optionsHi":["प्रतिबंध को सर्वसम्मति से बरकरार रखा, यह मानते हुए कि हिजाब अनिवार्य धार्मिक प्रथा नहीं है","विभाजित निर्णय दिया, इसलिए मामला बड़ी पीठ के लिए मुख्य न्यायाधीश के पास गया","प्रतिबंध को संविधान के अनुच्छेद 19(1)(a) और 25 का उल्लंघन मानकर सर्वसम्मति से रद्द किया","मामले का निर्णय करने से इनकार किया और उसे लंबित सबरीमाला पुनर्विचार संदर्भ के साथ संलग्न किया"],"explanationHi":"न्यायमूर्ति हेमंत गुप्ता ने प्रतिबंध को बनाए रखने वाले कर्नाटक उच्च न्यायालय के निर्णय को बरकरार रखा, जबकि न्यायमूर्ति सुधांशु धूलिया ने चयन और बालिकाओं की शिक्षा पर बल देते हुए उसे रद्द कर दिया। दो न्यायाधीशों की पीठ का विभाजित निर्णय मामले को बड़ी पीठ के लिए मुख्य न्यायाधीश के पास भेजता है।"},
  {"id":"polity-fundamental-rights-181","question":"How many of these statements about the rights of minorities under Article 30 are correct? I. Linguistic minorities, and not only religious ones, can claim Article 30. II. The right covers institutions set up before the Constitution came into force. III. The State may not impose any regulation, even on academic standards, on an aided minority institution. IV. Article 30 protects only institutions that teach the minority's own religion or language.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct: Article 30(1) covers minorities based on religion or language, and the Kerala Education Bill reference (1958) covered pre-1950 institutions. III is wrong: reasonable regulation of standards is allowed. IV is wrong: they may give general secular education.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 30 के अंतर्गत अल्पसंख्यकों के अधिकारों के बारे में इनमें से कितने कथन सही हैं? I. भाषायी अल्पसंख्यक भी, केवल धार्मिक ही नहीं, अनुच्छेद 30 का दावा कर सकते हैं। II. अधिकार संविधान के लागू होने से पहले स्थापित संस्थाओं को भी कवर करता है। III. राज्य सहायता प्राप्त अल्पसंख्यक संस्था पर, शैक्षिक मानकों पर भी, कोई विनियमन नहीं लगा सकता। IV. अनुच्छेद 30 केवल उन संस्थाओं की रक्षा करता है जो अल्पसंख्यक की अपनी धार्मिक या भाषा की शिक्षा देती हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं: अनुच्छेद 30(1) धर्म या भाषा पर आधारित अल्पसंख्यकों को कवर करता है, और केरल शिक्षा विधेयक संदर्भ (1958) ने 1950 से पूर्व की संस्थाओं को कवर किया। III गलत है: मानकों का युक्तियुक्त विनियमन अनुमत है। IV गलत है: वे सामान्य धर्मनिरपेक्ष शिक्षा दे सकती हैं।"},
  {"id":"polity-fundamental-rights-182","question":"In Naresh Shridhar Mirajkar v. State of Maharashtra (1966), a High Court judge had ordered that a witness's evidence not be published, and journalists challenged the order under Article 32. The Supreme Court held that:","options":["The order violated Article 19(1)(a), as courts are ‘State’ for every purpose","Only a Constitution Bench could quash a High Court judge's order under Article 32","The order was void, since a High Court has no inherent power to hold a trial in camera","A High Court's judicial order cannot be quashed by a writ under Article 32"],"answer":3,"explanation":"The majority held that a judicial decision of a superior court, even one that affects a Fundamental Right, is not open to a writ under Article 32; the remedy is appeal. It also held that a High Court has inherent power to restrict publicity where justice requires it.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"नरेश श्रीधर मिराजकर बनाम महाराष्ट्र राज्य (1966) में उच्च न्यायालय के एक न्यायाधीश ने आदेश दिया था कि किसी साक्षी का साक्ष्य प्रकाशित न किया जाए, और पत्रकारों ने अनुच्छेद 32 के अंतर्गत इस आदेश को चुनौती दी। सर्वोच्च न्यायालय ने माना कि:","optionsHi":["आदेश ने अनुच्छेद 19(1)(a) का उल्लंघन किया, क्योंकि न्यायालय प्रत्येक प्रयोजन के लिए ‘राज्य’ हैं","अनुच्छेद 32 के अंतर्गत उच्च न्यायालय के न्यायाधीश का आदेश केवल संविधान पीठ ही रद्द कर सकती थी","आदेश शून्य था, क्योंकि उच्च न्यायालय को बंद कमरे में विचारण करने की अंतर्निहित शक्ति नहीं है","उच्च न्यायालय के न्यायिक आदेश को अनुच्छेद 32 के अंतर्गत रिट द्वारा रद्द नहीं किया जा सकता"],"explanationHi":"बहुमत ने माना कि वरिष्ठ न्यायालय का न्यायिक निर्णय, भले ही वह मौलिक अधिकार को प्रभावित करे, अनुच्छेद 32 के अंतर्गत रिट के लिए खुला नहीं है; उपाय अपील है। उसने यह भी माना कि जहाँ न्याय की आवश्यकता हो, वहाँ प्रचार को सीमित करने की उच्च न्यायालय को अंतर्निहित शक्ति है।"},
  {"id":"polity-fundamental-rights-183","question":"A law made after 1950 violates Article 19(1)(g), a right available only to citizens. Following State of Gujarat v. Ambica Mills (1974), what is the position of this law?","options":["It is void only against citizens and remains operative against non-citizens and companies","It is void ab initio for everyone, since Article 13(2) forbids the State from making it at all","It lies dormant under the doctrine of eclipse and revives if the right is later suspended","It is valid until a court declares it void, after which it is void against every person"],"answer":0,"explanation":"Ambica Mills held that ‘void’ in Article 13(2) is relative: a post-Constitution law that infringes a citizens-only right is void only against those who hold the right, and stays operative against non-citizens such as companies. It is not void against everyone, as Deep Chand (1959) had suggested.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"1950 के बाद बना कोई कानून अनुच्छेद 19(1)(g) का उल्लंघन करता है, जो केवल नागरिकों को उपलब्ध अधिकार है। गुजरात राज्य बनाम अंबिका मिल्स (1974) के अनुसार इस कानून की स्थिति क्या है?","optionsHi":["यह केवल नागरिकों के विरुद्ध शून्य है और गैर-नागरिकों तथा कंपनियों के विरुद्ध प्रवर्तनीय रहता है","यह सभी के लिए आरंभ से ही शून्य है, क्योंकि अनुच्छेद 13(2) राज्य को इसे बनाने से ही वर्जित करता है","यह ग्रहण के सिद्धांत के अंतर्गत सुप्त रहता है और अधिकार के बाद में निलंबित होने पर पुनर्जीवित हो जाता है","यह तब तक वैध है जब तक न्यायालय इसे शून्य घोषित न करे, जिसके बाद यह प्रत्येक व्यक्ति के विरुद्ध शून्य है"],"explanationHi":"अंबिका मिल्स ने माना कि अनुच्छेद 13(2) में ‘शून्य’ सापेक्ष है: केवल नागरिकों को उपलब्ध अधिकार का अतिक्रमण करने वाला संविधान-पश्चात कानून केवल उन्हीं के विरुद्ध शून्य है जिनके पास वह अधिकार है, और कंपनियों जैसे गैर-नागरिकों के विरुद्ध प्रवर्तनीय रहता है। यह सभी के विरुद्ध शून्य नहीं है, जैसा दीप चंद (1959) ने सुझाया था।"},
  {"id":"polity-fundamental-rights-184","question":"Arrange these rulings on Section 377 of the IPC and privacy in chronological order: 1. Navtej Singh Johar v. Union of India 2. Suresh Kumar Koushal v. Naz Foundation 3. Naz Foundation v. Government of NCT of Delhi (Delhi High Court) 4. K. S. Puttaswamy v. Union of India (privacy)","options":["3, 4, 2, 1","3, 2, 4, 1","2, 3, 4, 1","3, 2, 1, 4"],"answer":1,"explanation":"The Delhi High Court read down Section 377 in Naz (2009); the Supreme Court reversed it in Koushal (2013); Puttaswamy (2017) criticised Koushal while declaring privacy a Fundamental Right; and Navtej (2018) decriminalised consensual relations between adults of the same sex.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"भारतीय दंड संहिता की धारा 377 और निजता पर इन निर्णयों को कालानुक्रम में व्यवस्थित कीजिए: 1. नवतेज सिंह जौहर बनाम भारत संघ 2. सुरेश कुमार कौशल बनाम नाज़ फाउंडेशन 3. नाज़ फाउंडेशन बनाम दिल्ली सरकार (दिल्ली उच्च न्यायालय) 4. के. एस. पुट्टस्वामी बनाम भारत संघ (निजता)","optionsHi":["3, 4, 2, 1","3, 2, 4, 1","2, 3, 4, 1","3, 2, 1, 4"],"explanationHi":"दिल्ली उच्च न्यायालय ने नाज़ (2009) में धारा 377 को सीमित किया; सर्वोच्च न्यायालय ने कौशल (2013) में उसे पलट दिया; पुट्टस्वामी (2017) ने निजता को मौलिक अधिकार घोषित करते हुए कौशल की आलोचना की; और नवतेज (2018) ने समान लिंग के वयस्कों के बीच सहमति से संबंधों को अपराध-मुक्त किया।"},
  {"id":"polity-fundamental-rights-185","question":"In Excel Wear v. Union of India (1978), the Supreme Court struck down Section 25-O of the Industrial Disputes Act, which required prior government permission to close an undertaking. Its main reasoning was that:","options":["Closure of industries is a trade policy matter reserved for Parliament, not for courts","Workers have no Fundamental Right to employment, so the provision served no purpose","Freedom of business includes a right to close it, and the curb was unreasonable","The provision dealt with a State List subject, so Parliament lacked competence to make it"],"answer":2,"explanation":"The Court held that the freedom of business under Article 19(1)(g) includes the right not to carry it on, and that the unguided power to refuse permission was not a reasonable restriction under Article 19(6). The right to close is not absolute, and a revised provision was later upheld.","difficulty":"hard","source":"UPSC Prelims","questionHi":"एक्सेल वियर बनाम भारत संघ (1978) में सर्वोच्च न्यायालय ने औद्योगिक विवाद अधिनियम की धारा 25-O को रद्द किया, जो किसी उपक्रम को बंद करने के लिए सरकार की पूर्व अनुमति अपेक्षित करती थी। उसका मुख्य तर्क यह था कि:","optionsHi":["उद्योगों को बंद करना व्यापार नीति का विषय है जो संसद के लिए आरक्षित है, न्यायालयों के लिए नहीं","कामगारों का रोजगार का कोई मौलिक अधिकार नहीं है, इसलिए उपबंध का कोई प्रयोजन नहीं था","कारोबार की स्वतंत्रता में उसे बंद करने का अधिकार शामिल है, और यह निर्बंधन अयुक्तियुक्त था","उपबंध राज्य सूची के विषय से संबंधित था, इसलिए संसद को उसे बनाने की क्षमता नहीं थी"],"explanationHi":"न्यायालय ने माना कि अनुच्छेद 19(1)(g) के अंतर्गत कारोबार की स्वतंत्रता में उसे न चलाने का अधिकार भी शामिल है, और अनुमति से इनकार करने की निरंकुश शक्ति अनुच्छेद 19(6) के अंतर्गत युक्तियुक्त निर्बंधन नहीं थी। बंद करने का अधिकार निरपेक्ष नहीं है, और संशोधित उपबंध को बाद में बरकरार रखा गया।"},
  {"id":"polity-fundamental-rights-186","question":"A person runs a prize competition in which winning depends wholly on chance and claims that a ban on it violates his freedom of trade under Article 19(1)(g). Following R. M. D. Chamarbaugwala v. Union of India (1957), the claim fails because:","options":["Article 19(1)(g) protects only trades carried on under a licence granted by the State","A prize competition is a lottery, which is a Union List subject outside Part III","Gaming is protected, but only Parliament may restrict it under Article 19(6)","Gambling is not ‘trade’ or ‘business’ at all, so it lies outside Article 19(1)(g)"],"answer":3,"explanation":"The Court held that gambling is res extra commercium: it is not trade, business or commerce in the constitutional sense, so Article 19(1)(g) does not reach it. Competitions involving substantial skill were treated differently.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कोई व्यक्ति पुरस्कार प्रतियोगिता चलाता है जिसमें जीतना पूरी तरह संयोग पर निर्भर है, और दावा करता है कि उस पर प्रतिबंध अनुच्छेद 19(1)(g) के अंतर्गत उसकी व्यापार की स्वतंत्रता का उल्लंघन करता है। आर. एम. डी. चमारबागवाला बनाम भारत संघ (1957) के अनुसार दावा विफल होता है क्योंकि:","optionsHi":["अनुच्छेद 19(1)(g) केवल राज्य द्वारा दिए गए लाइसेंस के अधीन चलाए जाने वाले व्यापार को संरक्षित करता है","पुरस्कार प्रतियोगिता लॉटरी है, जो भाग III से बाहर संघ सूची का विषय है","जुए को संरक्षण है, पर अनुच्छेद 19(6) के अंतर्गत केवल संसद उसे प्रतिबंधित कर सकती है","जुआ ‘व्यापार’ या ‘कारोबार’ है ही नहीं, इसलिए वह अनुच्छेद 19(1)(g) से बाहर है"],"explanationHi":"न्यायालय ने माना कि जुआ वाणिज्य से परे (res extra commercium) है: वह संवैधानिक अर्थ में व्यापार, कारोबार या वाणिज्य नहीं है, इसलिए अनुच्छेद 19(1)(g) उस तक नहीं पहुँचता। पर्याप्त कौशल वाली प्रतियोगिताओं को अलग माना गया।"},
  {"id":"polity-fundamental-rights-187","question":"In Air India v. Nergesh Meerza (1981), the Supreme Court examined service rules for air hostesses. Which rule did it strike down as arbitrary and violative of Article 14?","options":["Termination of service on the air hostess's first pregnancy","A retirement age for air hostesses lower than for male pursers","A bar on marriage within four years of joining the service","Separate promotion channels for air hostesses and pursers"],"answer":0,"explanation":"The Court struck down the rule ending service on first pregnancy as unreasonable and an affront to womanhood. It upheld the bar on marriage within the first four years and treated air hostesses and pursers as separate cadres, so different service conditions were not sex discrimination as such.","difficulty":"hard","source":"UPSC Prelims","questionHi":"एयर इंडिया बनाम नर्गेश मीर्जा (1981) में सर्वोच्च न्यायालय ने एयर होस्टेसों के सेवा नियमों की जाँच की। उसने किस नियम को मनमाना और अनुच्छेद 14 का उल्लंघन मानकर रद्द किया?","optionsHi":["एयर होस्टेस की पहली गर्भावस्था पर सेवा की समाप्ति","एयर होस्टेसों के लिए पुरुष परसरों से कम सेवानिवृत्ति आयु","सेवा में शामिल होने के चार वर्ष के भीतर विवाह पर रोक","एयर होस्टेसों और परसरों के लिए अलग पदोन्नति मार्ग"],"explanationHi":"न्यायालय ने पहली गर्भावस्था पर सेवा समाप्त करने वाले नियम को अयुक्तियुक्त और नारीत्व का अपमान मानकर रद्द किया। उसने पहले चार वर्षों में विवाह पर रोक को बरकरार रखा और एयर होस्टेसों तथा परसरों को अलग संवर्ग माना, इसलिए भिन्न सेवा शर्तें अपने आप में लिंग भेदभाव नहीं थीं।"},
  {"id":"polity-fundamental-rights-188","question":"In Yusuf Abdul Aziz v. State of Bombay (1954), a man charged with adultery argued that Section 497 of the IPC discriminated by sex because the wife could not be punished even as an abettor. The Supreme Court:","options":["Struck down Section 497 as hostile discrimination against men under Article 15(1)","Upheld Section 497 as a special provision for women permitted by Article 15(3)","Upheld Section 497 because Article 14 does not apply to provisions of criminal law","Read Section 497 down so that the wife too could be punished as an abettor"],"answer":1,"explanation":"The Court treated the exemption of the wife as a special provision for women saved by Article 15(3). Joseph Shine (2018) later struck down Section 497 itself, holding that it treated a woman as her husband's property.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"यूसुफ अब्दुल अजीज बनाम बॉम्बे राज्य (1954) में व्यभिचार के आरोपी एक व्यक्ति ने तर्क दिया कि भारतीय दंड संहिता की धारा 497 लिंग के आधार पर भेदभाव करती है क्योंकि पत्नी को दुष्प्रेरक के रूप में भी दंडित नहीं किया जा सकता। सर्वोच्च न्यायालय ने:","optionsHi":["धारा 497 को पुरुषों के प्रति विद्वेषपूर्ण भेदभाव मानकर अनुच्छेद 15(1) के अंतर्गत रद्द किया","धारा 497 को अनुच्छेद 15(3) द्वारा अनुमत महिलाओं के लिए विशेष उपबंध मानकर बरकरार रखा","धारा 497 को इसलिए बरकरार रखा कि अनुच्छेद 14 आपराधिक कानून के उपबंधों पर लागू नहीं होता","धारा 497 को सीमित किया ताकि पत्नी को भी दुष्प्रेरक के रूप में दंडित किया जा सके"],"explanationHi":"न्यायालय ने पत्नी की छूट को अनुच्छेद 15(3) द्वारा संरक्षित महिलाओं के लिए विशेष उपबंध माना। जोसेफ शाइन (2018) ने बाद में धारा 497 को ही रद्द कर दिया, यह मानते हुए कि वह महिला को उसके पति की संपत्ति मानती थी।"},
  {"id":"polity-fundamental-rights-189","question":"In Church of God (Full Gospel) in India v. K. K. R. Majestic Colony Welfare Association (2000), the Supreme Court held that:","options":["Prayer through loudspeakers is an essential practice protected by Article 25","Noise rules apply to temples and mosques but not to churches in residential areas","No religion prescribes prayer that disturbs others' peace through loudspeakers","Curbs on loudspeakers at places of worship can be made only by Parliament"],"answer":2,"explanation":"The Court held that Article 25 does not protect prayer through voice amplifiers or drums that disturb others, since no religion requires it, and that noise control rules apply to all places of worship alike.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"चर्च ऑफ गॉड (फुल गॉस्पेल) इन इंडिया बनाम के. के. आर. मजेस्टिक कॉलोनी वेलफेयर एसोसिएशन (2000) में सर्वोच्च न्यायालय ने माना कि:","optionsHi":["लाउडस्पीकरों से प्रार्थना अनिवार्य प्रथा है जो अनुच्छेद 25 द्वारा संरक्षित है","ध्वनि के नियम मंदिरों और मस्जिदों पर लागू होते हैं, आवासीय क्षेत्रों में चर्चों पर नहीं","कोई धर्म ऐसी प्रार्थना निर्धारित नहीं करता जो लाउडस्पीकरों से दूसरों की शांति भंग करे","पूजा स्थलों पर लाउडस्पीकर पर रोक केवल संसद लगा सकती है"],"explanationHi":"न्यायालय ने माना कि अनुच्छेद 25 ध्वनि-विस्तारकों या ढोल से प्रार्थना की रक्षा नहीं करता जो दूसरों को परेशान करे, क्योंकि कोई धर्म इसकी अपेक्षा नहीं करता, और ध्वनि नियंत्रण के नियम सभी पूजा स्थलों पर समान रूप से लागू होते हैं।"},
  {"id":"polity-fundamental-rights-190","question":"In Amit Sahni v. Commissioner of Police (2020), arising from the Shaheen Bagh protest in Delhi, the Supreme Court held that:","options":["A peaceful protest may occupy any public road until the government responds to it","The right to protest is only a statutory right that the police may suspend at will","Protests against a law passed by Parliament are not protected by Article 19(1)(b)","Public ways cannot be occupied indefinitely; protests belong at designated sites"],"answer":3,"explanation":"The Court affirmed the right to peaceful protest under Articles 19(1)(a) and (b) but held that it must be balanced against others' freedom of movement, so public roads cannot be occupied indefinitely and the administration may clear such blockades.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अमित साहनी बनाम पुलिस आयुक्त (2020) में, जो दिल्ली के शाहीन बाग प्रदर्शन से उत्पन्न हुआ, सर्वोच्च न्यायालय ने माना कि:","optionsHi":["शांतिपूर्ण विरोध प्रदर्शन किसी भी सार्वजनिक सड़क पर तब तक कब्जा कर सकता है जब तक सरकार उत्तर न दे","विरोध का अधिकार केवल सांविधिक अधिकार है जिसे पुलिस इच्छानुसार निलंबित कर सकती है","संसद द्वारा पारित कानून के विरुद्ध विरोध अनुच्छेद 19(1)(b) द्वारा संरक्षित नहीं हैं","सार्वजनिक मार्गों पर अनिश्चित काल तक कब्जा नहीं किया जा सकता; विरोध प्रदर्शन निर्धारित स्थलों पर होने चाहिए"],"explanationHi":"न्यायालय ने अनुच्छेद 19(1)(a) और (b) के अंतर्गत शांतिपूर्ण विरोध के अधिकार की पुष्टि की, पर माना कि इसे दूसरों की आवागमन की स्वतंत्रता के साथ संतुलित करना होगा, इसलिए सार्वजनिक सड़कों पर अनिश्चित काल तक कब्जा नहीं किया जा सकता और प्रशासन ऐसे अवरोध हटा सकता है।"},
  {"id":"polity-fundamental-rights-191","question":"How many of these statements about Ashoka Kumar Thakur v. Union of India (2008) are correct? I. It upheld the 93rd Amendment as far as it applied to State-maintained and aided institutions. II. It required the creamy layer to be excluded from OBC reservation in central educational institutions. III. It finally decided that Article 15(5) is valid in its application to private unaided institutions.","options":["Only two","Only one","All three","None"],"answer":0,"explanation":"The Court upheld the 93rd Amendment and the 27% OBC quota in central institutions with the creamy layer excluded (I, II correct). It expressly left open whether Article 15(5) is valid for private unaided institutions, which was settled later in Pramati (2014), so III is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अशोक कुमार ठाकुर बनाम भारत संघ (2008) के बारे में इनमें से कितने कथन सही हैं? I. इसने 93वें संशोधन को, जहाँ तक वह राज्य-पोषित और सहायता प्राप्त संस्थाओं पर लागू होता है, बरकरार रखा। II. इसने केंद्रीय शिक्षा संस्थाओं में OBC आरक्षण से क्रीमी लेयर को बाहर रखना आवश्यक किया। III. इसने अंतिम रूप से तय किया कि अनुच्छेद 15(5) निजी गैर-सहायता प्राप्त संस्थाओं पर लागू होने में वैध है।","optionsHi":["केवल दो","केवल एक","सभी तीन","कोई नहीं"],"explanationHi":"न्यायालय ने 93वें संशोधन और केंद्रीय संस्थाओं में क्रीमी लेयर को बाहर रखकर 27% OBC कोटा बरकरार रखा (I, II सही)। उसने स्पष्ट रूप से खुला छोड़ा कि अनुच्छेद 15(5) निजी गैर-सहायता प्राप्त संस्थाओं के लिए वैध है या नहीं, जो बाद में प्रमति (2014) में तय हुआ, इसलिए III गलत है।"},
  {"id":"polity-fundamental-rights-192","question":"Arrange these milestones on reservation in promotions in chronological order: 1. M. Nagaraj v. Union of India 2. 77th Amendment inserting Article 16(4A) 3. General Manager, Southern Railway v. Rangachari 4. Indra Sawhney v. Union of India","options":["3, 2, 4, 1","3, 4, 2, 1","4, 3, 2, 1","3, 4, 1, 2"],"answer":1,"explanation":"Rangachari (1961) held that Article 16(4) covers promotions; Indra Sawhney (1992) overruled this and barred reservation in promotions; the 77th Amendment (1995) restored it for SCs and STs through Article 16(4A); and Nagaraj (2006) upheld that clause subject to conditions.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पदोन्नति में आरक्षण पर इन पड़ावों को कालानुक्रम में व्यवस्थित कीजिए: 1. एम. नागराज बनाम भारत संघ 2. अनुच्छेद 16(4A) जोड़ने वाला 77वाँ संशोधन 3. जनरल मैनेजर, दक्षिण रेलवे बनाम रंगाचारी 4. इंद्रा साहनी बनाम भारत संघ","optionsHi":["3, 2, 4, 1","3, 4, 2, 1","4, 3, 2, 1","3, 4, 1, 2"],"explanationHi":"रंगाचारी (1961) ने माना कि अनुच्छेद 16(4) पदोन्नतियों को कवर करता है; इंद्रा साहनी (1992) ने इसे पलट कर पदोन्नति में आरक्षण को वर्जित किया; 77वें संशोधन (1995) ने अनुच्छेद 16(4A) द्वारा अनुसूचित जातियों और जनजातियों के लिए इसे बहाल किया; और नागराज (2006) ने उस खंड को शर्तों के साथ बरकरार रखा।"},
  {"id":"polity-fundamental-rights-193","question":"A private school recognised by the State, but not maintained out of State funds, holds religious instruction during school hours. A Class 8 pupil does not want to attend. Under Article 28(3):","options":["The pupil must attend, since Article 28 restricts only wholly State-funded schools","The school must stop all religious instruction, since recognition makes it a State school","The pupil cannot be required to attend without the consent of the pupil's guardian","The pupil may stay away only if the school is run by a minority under Article 30"],"answer":2,"explanation":"Article 28(3) says no one attending an institution recognised by the State or receiving State aid shall be required to take part in its religious instruction or worship without consent, given by the guardian for a minor. Only wholly State-maintained institutions face the outright bar of Article 28(1).","difficulty":"hard","source":"UPSC Prelims","questionHi":"राज्य द्वारा मान्यता प्राप्त किंतु राज्य निधि से पोषित न होने वाला एक निजी स्कूल स्कूल के समय में धार्मिक शिक्षा देता है। कक्षा 8 का एक विद्यार्थी उसमें उपस्थित नहीं होना चाहता। अनुच्छेद 28(3) के अंतर्गत:","optionsHi":["विद्यार्थी को उपस्थित होना होगा, क्योंकि अनुच्छेद 28 केवल पूर्णतः राज्य-निधि से पोषित स्कूलों को प्रतिबंधित करता है","स्कूल को सभी धार्मिक शिक्षा बंद करनी होगी, क्योंकि मान्यता उसे राज्य का स्कूल बना देती है","विद्यार्थी के संरक्षक की सहमति के बिना उसे उपस्थित होने के लिए बाध्य नहीं किया जा सकता","विद्यार्थी अनुपस्थित रह सकता है केवल तब जब स्कूल अनुच्छेद 30 के अंतर्गत अल्पसंख्यक द्वारा चलाया जाता हो"],"explanationHi":"अनुच्छेद 28(3) कहता है कि राज्य द्वारा मान्यता प्राप्त या राज्य सहायता प्राप्त संस्था में पढ़ने वाले किसी व्यक्ति को उसकी धार्मिक शिक्षा या उपासना में भाग लेने के लिए सहमति के बिना बाध्य नहीं किया जाएगा, अवयस्क के लिए संरक्षक की सहमति। केवल पूर्णतः राज्य-पोषित संस्थाओं पर अनुच्छेद 28(1) का पूर्ण वर्जन है।"},
  {"id":"polity-fundamental-rights-194","question":"The second proviso to Article 31A(1), added by the 17th Amendment (1964), protects a person whose land is acquired by the State. What does it require?","options":["Prior approval of each acquisition by a resolution of the State Legislative Assembly","Payment of compensation in cash within one year from the date of acquisition","Placing the law in the Ninth Schedule before any of the land is taken over","Market-value compensation for land within the ceiling under personal cultivation"],"answer":3,"explanation":"Where land under a person's personal cultivation and within the statutory ceiling is acquired, the law must provide compensation not less than its market value. It is one of the few places where the Constitution still speaks of market value.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 31A(1) का दूसरा परंतुक, जो 17वें संशोधन (1964) द्वारा जोड़ा गया, उस व्यक्ति की रक्षा करता है जिसकी भूमि राज्य द्वारा अधिगृहीत की जाती है। यह क्या अपेक्षा करता है?","optionsHi":["प्रत्येक अधिग्रहण का राज्य विधानसभा के संकल्प द्वारा पूर्व अनुमोदन","अधिग्रहण की तिथि से एक वर्ष के भीतर नकद प्रतिकर का भुगतान","किसी भी भूमि को लेने से पहले कानून को नौवीं अनुसूची में रखना","व्यक्तिगत खेती वाली और सीमा के भीतर की भूमि के लिए बाजार मूल्य का प्रतिकर"],"explanationHi":"जहाँ किसी व्यक्ति की व्यक्तिगत खेती वाली और सांविधिक सीमा के भीतर की भूमि अधिगृहीत की जाए, वहाँ कानून को उसके बाजार मूल्य से कम न होने वाले प्रतिकर का उपबंध करना होगा। यह उन थोड़े स्थानों में से है जहाँ संविधान अब भी बाजार मूल्य की बात करता है।"},
  {"id":"polity-fundamental-rights-195","question":"In Sheela Barse v. State of Maharashtra (1983), acting on a journalist's letter about the treatment of women in police custody, the Supreme Court directed that:","options":["Female suspects be kept in separate lock-ups guarded by female constables","Special courts for women be set up in every district to try their cases","Every arrest of a woman be recorded on video and sent to the High Court","Women prisoners be given bail as of right in all bailable and non-bailable cases"],"answer":0,"explanation":"The Court directed separate, well-guarded lock-ups for women with female constables, interrogation of women only in the presence of policewomen, and prompt intimation of arrests to legal aid bodies so that arrested persons get legal help.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"शीला बार्से बनाम महाराष्ट्र राज्य (1983) में, पुलिस हिरासत में महिलाओं के साथ व्यवहार पर एक पत्रकार के पत्र पर कार्रवाई करते हुए, सर्वोच्च न्यायालय ने निर्देश दिया कि:","optionsHi":["महिला संदिग्धों को महिला कांस्टेबलों द्वारा संरक्षित अलग हवालातों में रखा जाए","प्रत्येक जिले में उनके मामलों की सुनवाई के लिए महिलाओं के विशेष न्यायालय बनाए जाएँ","महिला की प्रत्येक गिरफ्तारी की वीडियो रिकॉर्डिंग हो और उच्च न्यायालय को भेजी जाए","महिला कैदियों को सभी जमानती और अजमानतीय मामलों में अधिकार के रूप में जमानत दी जाए"],"explanationHi":"न्यायालय ने महिला कांस्टेबलों के साथ महिलाओं के लिए अलग, सुरक्षित हवालात, महिला पुलिसकर्मियों की उपस्थिति में ही महिलाओं से पूछताछ, और विधिक सहायता निकायों को गिरफ्तारी की शीघ्र सूचना का निर्देश दिया ताकि गिरफ्तार व्यक्तियों को विधिक सहायता मिले।"},
  {"id":"polity-fundamental-rights-196","question":"In Lata Singh v. State of U.P. (2006), about the harassment of an adult woman who had married outside her caste, the Supreme Court held that:","options":["An adult may marry anyone, and police must act against those who threaten such couples","An inter-caste marriage is valid only if registered under the Special Marriage Act, 1954","Parents may seek annulment of an adult child's inter-caste marriage under Article 226","Caste panchayats may advise on marriages so long as they impose no penalty on the couple"],"answer":0,"explanation":"The Court held that an adult is free to marry a person of choice, that inter-caste marriages are in the national interest, and directed the police to protect such couples and prosecute those who threaten or harass them; it condemned so-called honour killings.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"लता सिंह बनाम उत्तर प्रदेश राज्य (2006) में, जाति के बाहर विवाह करने वाली वयस्क महिला के उत्पीड़न के संबंध में, सर्वोच्च न्यायालय ने माना कि:","optionsHi":["वयस्क किसी से भी विवाह कर सकता है, और ऐसे जोड़ों को धमकाने वालों के विरुद्ध पुलिस को कार्रवाई करनी चाहिए","अंतर्जातीय विवाह तभी वैध है जब वह विशेष विवाह अधिनियम, 1954 के अंतर्गत पंजीकृत हो","माता-पिता अनुच्छेद 226 के अंतर्गत वयस्क संतान के अंतर्जातीय विवाह को शून्य घोषित कराने की माँग कर सकते हैं","जाति पंचायतें विवाहों पर सलाह दे सकती हैं बशर्ते वे जोड़े पर कोई दंड न लगाएँ"],"explanationHi":"न्यायालय ने माना कि वयस्क अपनी पसंद के व्यक्ति से विवाह करने के लिए स्वतंत्र है, कि अंतर्जातीय विवाह राष्ट्रीय हित में हैं, और पुलिस को ऐसे जोड़ों की रक्षा करने तथा उन्हें धमकाने या सताने वालों पर मुकदमा चलाने का निर्देश दिया; उसने तथाकथित ऑनर किलिंग की निंदा की।"},
  {"id":"polity-fundamental-rights-197","question":"In Zahira Habibullah Sheikh v. State of Gujarat (2004), the Best Bakery case, the Supreme Court set aside the acquittals and ordered a retrial. What did it do to secure a fair trial?","options":["It ordered the case to be tried afresh by a special bench of the Gujarat High Court","It transferred the retrial to a court in Maharashtra, outside the State of Gujarat","It gave the retrial to a court-martial because witnesses feared the State police","It ordered the retrial to be held before a sessions judge from another district of Gujarat"],"answer":1,"explanation":"Holding that a fair trial is part of Article 21 and that witnesses had been intimidated, the Court ordered a retrial and transferred it to Mumbai. A fair trial needs an impartial judge and an atmosphere in which witnesses can speak without fear.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जाहिरा हबीबुल्ला शेख बनाम गुजरात राज्य (2004), बेस्ट बेकरी मामले, में सर्वोच्च न्यायालय ने बरी करने के आदेशों को रद्द कर पुनर्विचारण का आदेश दिया। निष्पक्ष विचारण सुनिश्चित करने के लिए उसने क्या किया?","optionsHi":["गुजरात उच्च न्यायालय की विशेष पीठ द्वारा मामले की नए सिरे से सुनवाई का आदेश दिया","पुनर्विचारण को गुजरात राज्य के बाहर महाराष्ट्र के न्यायालय में स्थानांतरित किया","पुनर्विचारण कोर्ट-मार्शल को सौंपा क्योंकि साक्षियों को राज्य पुलिस से भय था","पुनर्विचारण गुजरात के किसी अन्य जिले के सत्र न्यायाधीश के समक्ष कराने का आदेश दिया"],"explanationHi":"यह मानते हुए कि निष्पक्ष विचारण अनुच्छेद 21 का भाग है और साक्षियों को डराया गया था, न्यायालय ने पुनर्विचारण का आदेश दिया और उसे मुंबई स्थानांतरित किया। निष्पक्ष विचारण के लिए निष्पक्ष न्यायाधीश और ऐसा वातावरण चाहिए जिसमें साक्षी निर्भय होकर बोल सकें।"},
  {"id":"polity-fundamental-rights-198","question":"In A. K. Kraipak v. Union of India (1969), a member of a selection board was himself a candidate for the post, though he stayed out when his own name was considered. The Supreme Court:","options":["Upheld the selection, since he withdrew from the meeting while his own case was considered","Upheld the selection, since natural justice binds only judicial and quasi-judicial bodies","Quashed the selection: the rule against bias applies to administrative action too","Quashed the selection only because the board had not recorded reasons for its ranking"],"answer":2,"explanation":"The Court held that the line between administrative and quasi-judicial functions is thin and that natural justice, including the rule against bias, applies to administrative decisions as well. His presence while rival candidates were assessed vitiated the selection.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ए. के. क्रैपाक बनाम भारत संघ (1969) में चयन बोर्ड का एक सदस्य स्वयं उसी पद का अभ्यर्थी था, यद्यपि अपने नाम पर विचार के समय वह बैठक से बाहर रहा। सर्वोच्च न्यायालय ने:","optionsHi":["चयन को बरकरार रखा, क्योंकि अपने मामले पर विचार के समय वह बैठक से हट गया था","चयन को बरकरार रखा, क्योंकि नैसर्गिक न्याय केवल न्यायिक और अर्ध-न्यायिक निकायों पर बाध्यकारी है","चयन को रद्द किया: पक्षपात-विरोधी नियम प्रशासनिक कार्रवाई पर भी लागू होता है","चयन को केवल इसलिए रद्द किया कि बोर्ड ने अपनी क्रम-सूची के कारण दर्ज नहीं किए थे"],"explanationHi":"न्यायालय ने माना कि प्रशासनिक और अर्ध-न्यायिक कार्यों के बीच की रेखा क्षीण है और नैसर्गिक न्याय, पक्षपात-विरोधी नियम सहित, प्रशासनिक निर्णयों पर भी लागू होता है। प्रतिद्वंद्वी अभ्यर्थियों के मूल्यांकन के समय उसकी उपस्थिति ने चयन को दूषित कर दिया।"},
  {"id":"polity-fundamental-rights-199","question":"A Tamil Nadu law abolished the hereditary right of succession to the office of archaka (temple priest) and let trustees appoint qualified persons. In Seshammal v. State of Tamil Nadu (1972), the Supreme Court:","options":["Struck it down, as hereditary succession to priestly office is an essential religious practice","Struck it down under Article 26, since only the denomination may appoint its own priests","Upheld it, since Article 25(2)(b) lets the State reform every Hindu religious practice","Upheld it, since appointing an archaka is a secular act, though his rituals are religious"],"answer":3,"explanation":"The Court held that appointing an archaka is a secular function of the trustee; the religious part is the worship he performs, which the law did not touch, and the Agamas on who may perform it must still be followed. Article 25(2)(b) covers social welfare and reform, not every practice.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"तमिलनाडु के एक कानून ने अर्चक (मंदिर पुजारी) के पद पर वंशानुगत उत्तराधिकार का अधिकार समाप्त कर दिया और न्यासियों को योग्य व्यक्तियों की नियुक्ति करने दी। शेषम्मल बनाम तमिलनाडु राज्य (1972) में सर्वोच्च न्यायालय ने:","optionsHi":["इसे रद्द किया, क्योंकि पुजारी पद पर वंशानुगत उत्तराधिकार अनिवार्य धार्मिक प्रथा है","इसे अनुच्छेद 26 के अंतर्गत रद्द किया, क्योंकि केवल संप्रदाय ही अपने पुजारी नियुक्त कर सकता है","इसे बरकरार रखा, क्योंकि अनुच्छेद 25(2)(b) राज्य को प्रत्येक हिंदू धार्मिक प्रथा में सुधार करने देता है","इसे बरकरार रखा, क्योंकि अर्चक की नियुक्ति धर्मनिरपेक्ष कार्य है, यद्यपि उसके अनुष्ठान धार्मिक हैं"],"explanationHi":"न्यायालय ने माना कि अर्चक की नियुक्ति न्यासी का धर्मनिरपेक्ष कार्य है; धार्मिक भाग वह पूजा है जो वह करता है, जिसे कानून ने नहीं छुआ, और कौन पूजा कर सकता है इस पर आगम अब भी मानने होंगे। अनुच्छेद 25(2)(b) सामाजिक कल्याण और सुधार को कवर करता है, हर प्रथा को नहीं।"},
  {"id":"polity-fundamental-rights-200","question":"In Chintaman Rao v. State of Madhya Pradesh (1950), a law barred everyone in certain villages from making bidis during the agricultural season, so that labour would be free for farming. The Supreme Court struck it down because:","options":["A total ban that went beyond what its object needed was not a ‘reasonable’ restriction","The freedom of trade in Article 19(1)(g) cannot be restricted by a State law at all","Bidi making is a cottage industry protected absolutely by the directive in Article 43","Restrictions on trade under Article 19(6) can be imposed only during a National Emergency"],"answer":0,"explanation":"The Court held that a restriction is reasonable only if it is not arbitrary or excessive beyond what the public interest requires; barring even persons who were not farm workers went far beyond the object. It was among the first cases to explain ‘reasonable restrictions’.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"चिंतामन राव बनाम मध्य प्रदेश राज्य (1950) में एक कानून ने कुछ गाँवों में सभी को कृषि के मौसम में बीड़ी बनाने से रोका, ताकि खेती के लिए श्रम उपलब्ध रहे। सर्वोच्च न्यायालय ने इसे रद्द किया क्योंकि:","optionsHi":["अपने उद्देश्य की आवश्यकता से आगे जाने वाला पूर्ण प्रतिबंध ‘युक्तियुक्त’ निर्बंधन नहीं था","अनुच्छेद 19(1)(g) में व्यापार की स्वतंत्रता पर राज्य का कानून कोई निर्बंधन लगा ही नहीं सकता","बीड़ी बनाना कुटीर उद्योग है जिसे अनुच्छेद 43 का निदेश पूर्ण संरक्षण देता है","अनुच्छेद 19(6) के अंतर्गत व्यापार पर निर्बंधन केवल राष्ट्रीय आपातकाल में लगाए जा सकते हैं"],"explanationHi":"न्यायालय ने माना कि निर्बंधन तभी युक्तियुक्त है जब वह मनमाना या लोक हित की अपेक्षा से अधिक न हो; उन व्यक्तियों को भी रोकना जो खेतिहर मजदूर नहीं थे, उद्देश्य से बहुत आगे था। यह ‘युक्तियुक्त निर्बंधन’ समझाने वाले पहले मामलों में था।"},
  {"id":"polity-fundamental-rights-201","question":"In Triveniben v. State of Gujarat (1989), a Constitution Bench considered whether delay in executing a death sentence can be a ground to commute it. It held that:","options":["A delay of over two years after sentence automatically entitles the convict to commutation","Only delay after the judicial process ends counts, and no fixed period can be laid down","Delay can never be a ground, since the convict himself causes it by filing petitions","Delay counts only if it occurs before the High Court confirms the death sentence"],"answer":1,"explanation":"The Bench rejected the fixed two-year rule of T. V. Vatheeswaran (1983) and held that only delay after the judicial process is over, such as in deciding mercy petitions, may be considered, weighing all the circumstances; no fixed period applies.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"त्रिवेणीबेन बनाम गुजरात राज्य (1989) में एक संविधान पीठ ने विचार किया कि क्या मृत्युदंड के निष्पादन में विलंब उसे बदलने का आधार हो सकता है। उसने माना कि:","optionsHi":["दंडादेश के दो वर्ष से अधिक विलंब पर दोषी स्वतः दंड परिवर्तन का हकदार हो जाता है","केवल न्यायिक प्रक्रिया समाप्त होने के बाद का विलंब गिना जाएगा, और कोई निश्चित अवधि निर्धारित नहीं की जा सकती","विलंब कभी आधार नहीं हो सकता, क्योंकि दोषी स्वयं याचिकाएँ दायर करके उसे उत्पन्न करता है","विलंब तभी गिना जाएगा जब वह उच्च न्यायालय द्वारा मृत्युदंड की पुष्टि से पहले हुआ हो"],"explanationHi":"पीठ ने टी. वी. वथीश्वरन (1983) के दो वर्ष के निश्चित नियम को अस्वीकार किया और माना कि केवल न्यायिक प्रक्रिया पूरी होने के बाद का विलंब, जैसे दया याचिकाओं के निर्णय में, सभी परिस्थितियों को तौलकर विचारणीय है; कोई निश्चित अवधि लागू नहीं होती।"},
  {"id":"polity-fundamental-rights-202","question":"In Rajasthan State Electricity Board v. Mohan Lal (1967), the Supreme Court interpreted the phrase ‘other authorities’ in Article 12. It held that:","options":["Only bodies performing governmental or sovereign functions are covered by the phrase","The phrase must be read ejusdem generis with Parliament and the State Legislatures","Statutory bodies with power to issue binding directions are covered by the phrase","Only bodies wholly funded out of the Consolidated Fund of India are covered by it"],"answer":2,"explanation":"The Court refused to read ‘other authorities’ ejusdem generis with the bodies named before it and held that authorities created by statute, with power to issue binding directions whose breach is punishable, fall within Article 12, even if some of their activities are commercial.","difficulty":"hard","source":"UPSC Prelims","questionHi":"राजस्थान राज्य विद्युत बोर्ड बनाम मोहन लाल (1967) में सर्वोच्च न्यायालय ने अनुच्छेद 12 में ‘अन्य प्राधिकारी’ पदावली की व्याख्या की। उसने माना कि:","optionsHi":["इस पदावली में केवल शासकीय या संप्रभु कार्य करने वाले निकाय आते हैं","इस पदावली को संसद और राज्य विधानमंडलों के साथ समान जाति (ejusdem generis) के रूप में पढ़ा जाना चाहिए","बाध्यकारी निदेश जारी करने की शक्ति वाले सांविधिक निकाय इस पदावली में आते हैं","इसमें केवल भारत की संचित निधि से पूर्णतः वित्तपोषित निकाय आते हैं"],"explanationHi":"न्यायालय ने ‘अन्य प्राधिकारी’ को उससे पहले नामित निकायों के साथ समान जाति सिद्धांत से पढ़ने से इनकार किया और माना कि कानून द्वारा बने प्राधिकारी, जिन्हें ऐसे बाध्यकारी निदेश जारी करने की शक्ति है जिनका उल्लंघन दंडनीय हो, अनुच्छेद 12 के अंतर्गत आते हैं, भले ही उनकी कुछ गतिविधियाँ वाणिज्यिक हों।"},
  {"id":"polity-fundamental-rights-203","question":"Consider these statements: 1. Article 16(4) uses the words ‘socially and educationally backward classes’, like Article 15(4). 2. Article 16(4) requires that the backward class be not adequately represented in the services under the State. 3. Article 15(4) covers special provisions for Scheduled Castes and Scheduled Tribes as well as for other backward classes. Which of these are correct?","options":["1 and 2 only","1 and 3 only","1, 2 and 3","2 and 3 only"],"answer":3,"explanation":"Article 16(4) speaks only of ‘any backward class of citizens’ which, in the State's opinion, is not adequately represented, while Article 15(4) names socially and educationally backward classes and the SCs and STs. So 2 and 3 are correct and 1 is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन कथनों पर विचार कीजिए: 1. अनुच्छेद 16(4) अनुच्छेद 15(4) की तरह ‘सामाजिक और शैक्षिक रूप से पिछड़े वर्गों’ शब्दों का प्रयोग करता है। 2. अनुच्छेद 16(4) अपेक्षा करता है कि पिछड़े वर्ग को राज्य के अधीन सेवाओं में पर्याप्त प्रतिनिधित्व न मिला हो। 3. अनुच्छेद 15(4) अनुसूचित जातियों और जनजातियों के साथ-साथ अन्य पिछड़े वर्गों के लिए विशेष उपबंधों को कवर करता है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 1 और 3","1, 2 और 3","केवल 2 और 3"],"explanationHi":"अनुच्छेद 16(4) केवल ‘नागरिकों के किसी पिछड़े वर्ग’ की बात करता है जिसका, राज्य की राय में, पर्याप्त प्रतिनिधित्व नहीं है, जबकि अनुच्छेद 15(4) सामाजिक और शैक्षिक रूप से पिछड़े वर्गों तथा अनुसूचित जातियों और जनजातियों का नाम लेता है। इसलिए 2 और 3 सही हैं और 1 गलत है।"},
  {"id":"polity-fundamental-rights-204","question":"In Sri Venkataramana Devaru v. State of Mysore (1958), a law threw open a denominational temple to all classes of Hindus, and the denomination claimed protection under Article 26(b). The Supreme Court:","options":["Applied the temple-entry law but let the denomination keep others out of certain rituals","Held that Article 26(b) prevails, so the denomination could keep its temple closed to others","Held that Article 25(2)(b) applies only to temples not owned by any religious denomination","Struck down the law, since temples can be opened to all only by a constitutional amendment"],"answer":0,"explanation":"Using harmonious construction, the Court held that the denomination's right under Article 26(b) is subject to a law under Article 25(2)(b) throwing open Hindu religious institutions of a public character, but allowed it to exclude outsiders from certain special ceremonies.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"श्री वेंकटरमण देवारु बनाम मैसूर राज्य (1958) में एक कानून ने सांप्रदायिक मंदिर को हिंदुओं के सभी वर्गों के लिए खोल दिया, और संप्रदाय ने अनुच्छेद 26(b) के अंतर्गत संरक्षण का दावा किया। सर्वोच्च न्यायालय ने:","optionsHi":["मंदिर-प्रवेश कानून लागू किया, परंतु संप्रदाय को कुछ अनुष्ठानों में दूसरों को बाहर रखने दिया","माना कि अनुच्छेद 26(b) प्रभावी है, इसलिए संप्रदाय अपना मंदिर दूसरों के लिए बंद रख सकता है","माना कि अनुच्छेद 25(2)(b) केवल उन मंदिरों पर लागू होता है जो किसी धार्मिक संप्रदाय के स्वामित्व में नहीं हैं","कानून को रद्द कर दिया, क्योंकि मंदिर सबके लिए केवल संवैधानिक संशोधन से खोले जा सकते हैं"],"explanationHi":"सामंजस्यपूर्ण निर्वचन अपनाते हुए न्यायालय ने माना कि अनुच्छेद 26(b) के अंतर्गत संप्रदाय का अधिकार, सार्वजनिक स्वरूप की हिंदू धार्मिक संस्थाओं को खोलने वाले अनुच्छेद 25(2)(b) के कानून के अधीन है, परंतु उसे कुछ विशेष समारोहों से बाहरी लोगों को बाहर रखने की अनुमति दी।"},
  {"id":"polity-fundamental-rights-205","question":"Section 62(5) of the Representation of the People Act, 1951 bars persons confined in prison from voting. In Anukul Chandra Pradhan v. Union of India (1997), the Supreme Court:","options":["Struck it down, since the right to vote is a Fundamental Right under Article 21","Upheld it, since voting is a statutory right that a law may reasonably limit","Struck it down only as applied to undertrials who have not yet been convicted","Upheld it, since Article 326 itself expressly excludes prisoners from voting"],"answer":1,"explanation":"The Court held that voting is a statutory right, not a Fundamental Right, and that keeping persons in prison away from the electoral process is a reasonable classification, even for undertrials. Article 326 allows disqualification for crime by law but does not itself name prisoners.","difficulty":"hard","source":"UPSC Prelims · State PSCs","questionHi":"लोक प्रतिनिधित्व अधिनियम, 1951 की धारा 62(5) कारागार में बंद व्यक्तियों को मतदान से वर्जित करती है। अनुकूल चंद्र प्रधान बनाम भारत संघ (1997) में सर्वोच्च न्यायालय ने:","optionsHi":["इसे रद्द किया, क्योंकि मतदान का अधिकार अनुच्छेद 21 के अंतर्गत मौलिक अधिकार है","इसे बरकरार रखा, क्योंकि मतदान सांविधिक अधिकार है जिसे कानून युक्तियुक्त रूप से सीमित कर सकता है","इसे केवल उन विचाराधीन कैदियों के संबंध में रद्द किया जो अभी दोषसिद्ध नहीं हुए","इसे बरकरार रखा, क्योंकि अनुच्छेद 326 स्वयं कैदियों को मतदान से स्पष्ट रूप से बाहर रखता है"],"explanationHi":"न्यायालय ने माना कि मतदान सांविधिक अधिकार है, मौलिक अधिकार नहीं, और कारागार में बंद व्यक्तियों को चुनाव प्रक्रिया से दूर रखना, विचाराधीन कैदियों के लिए भी, युक्तियुक्त वर्गीकरण है। अनुच्छेद 326 अपराध के कारण कानून द्वारा निरर्हता की अनुमति देता है पर स्वयं कैदियों का नाम नहीं लेता।"},
  {"id":"polity-fundamental-rights-206","question":"In Sodan Singh v. New Delhi Municipal Committee (1989), on street hawking, the Supreme Court held that:","options":["Hawking on public streets is a public nuisance that falls wholly outside Article 19(1)(g)","Hawkers have a Fundamental Right to a fixed place of business on any public road","Hawking is a trade under Article 19(1)(g), subject to reasonable regulation by the State","Hawking is protected under Article 21 alone, so no licence can ever be required for it"],"answer":2,"explanation":"The Court held that street trading is a business protected by Article 19(1)(g) but subject to reasonable restrictions; hawkers have no right to occupy any particular spot, and the State may regulate where and how they trade.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"सोहन सिंह बनाम नई दिल्ली नगरपालिका समिति (1989) में, जो सड़क पर फेरी लगाने से संबंधित था, सर्वोच्च न्यायालय ने माना कि:","optionsHi":["सार्वजनिक सड़कों पर फेरी लगाना लोक उपद्रव है जो पूरी तरह अनुच्छेद 19(1)(g) से बाहर है","फेरीवालों को किसी भी सार्वजनिक सड़क पर कारोबार के निश्चित स्थान का मौलिक अधिकार है","फेरी लगाना अनुच्छेद 19(1)(g) के अंतर्गत व्यापार है, जो राज्य द्वारा युक्तियुक्त विनियमन के अधीन है","फेरी लगाना केवल अनुच्छेद 21 से संरक्षित है, इसलिए इसके लिए कभी लाइसेंस की आवश्यकता नहीं हो सकती"],"explanationHi":"न्यायालय ने माना कि सड़क पर व्यापार अनुच्छेद 19(1)(g) द्वारा संरक्षित कारोबार है पर युक्तियुक्त निर्बंधनों के अधीन है; फेरीवालों को किसी विशेष स्थान पर कब्जे का अधिकार नहीं है, और राज्य यह विनियमित कर सकता है कि वे कहाँ और कैसे व्यापार करें।"},
  {"id":"polity-fundamental-rights-207","question":"Match the case with the relief or principle it is known for: A. Rudul Sah v. State of Bihar (1983) B. Nilabati Behera v. State of Orissa (1993) C. Chairman, Railway Board v. Chandrima Das (2000) D. Bodhisattwa Gautam v. Subhra Chakraborty (1996) — 1. Compensation to a foreign national raped by railway employees 2. Compensation for a custodial death, with sovereign immunity no defence 3. Compensation for detention continued for years after acquittal 4. Rape violates Article 21 even when committed by a private person","options":["A-3, B-1, C-2, D-4","A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-3, B-2, C-1, D-4"],"answer":3,"explanation":"Rudul Sah was the first award of compensation under Article 32 for illegal detention; Nilabati Behera treated it as a public law remedy based on strict liability; Chandrima Das applied Article 21 to a Bangladeshi national; and Bodhisattwa Gautam held rape to violate the victim's right to life.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मामले का उस राहत या सिद्धांत से मिलान कीजिए जिसके लिए वह जाना जाता है: A. रुदुल साह बनाम बिहार राज्य (1983) B. नीलाबती बेहरा बनाम उड़ीसा राज्य (1993) C. चेयरमैन, रेलवे बोर्ड बनाम चंद्रिमा दास (2000) D. बोधिसत्व गौतम बनाम सुभ्रा चक्रवर्ती (1996) — 1. रेलवे कर्मचारियों द्वारा बलात्कार की शिकार विदेशी नागरिक को मुआवजा 2. हिरासत में मृत्यु के लिए मुआवजा, संप्रभु उन्मुक्ति कोई बचाव नहीं 3. बरी होने के वर्षों बाद तक निरोध जारी रहने के लिए मुआवजा 4. बलात्कार निजी व्यक्ति द्वारा किए जाने पर भी अनुच्छेद 21 का उल्लंघन है","optionsHi":["A-3, B-1, C-2, D-4","A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-3, B-2, C-1, D-4"],"explanationHi":"रुदुल साह अवैध निरोध के लिए अनुच्छेद 32 के अंतर्गत मुआवजे का पहला पुरस्कार था; नीलाबती बेहरा ने इसे कठोर दायित्व पर आधारित लोक विधि उपाय माना; चंद्रिमा दास ने अनुच्छेद 21 को बांग्लादेशी नागरिक पर लागू किया; और बोधिसत्व गौतम ने बलात्कार को पीड़िता के जीवन के अधिकार का उल्लंघन माना।"},
  {"id":"polity-fundamental-rights-208","question":"How many of these statements about the Aadhaar judgment, K. S. Puttaswamy v. Union of India (2018), are correct? I. It upheld the Aadhaar Act as broadly valid. II. It struck down Section 7, which made Aadhaar mandatory for subsidies and benefits. III. It upheld mandatory linking of Aadhaar with bank accounts and mobile numbers. IV. It upheld linking Aadhaar with PAN under Section 139AA of the Income-tax Act.","options":["Only three","All four","Only two","Only one"],"answer":2,"explanation":"I and IV are correct. II is wrong: Section 7 (Aadhaar for subsidies) was upheld; it was Section 57 (use by private entities) that was struck down. III is wrong: mandatory linking with bank accounts and mobile numbers was struck down.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"आधार निर्णय, के. एस. पुट्टस्वामी बनाम भारत संघ (2018), के बारे में इनमें से कितने कथन सही हैं? I. इसने आधार अधिनियम को मोटे तौर पर वैध माना। II. इसने धारा 7 को रद्द किया, जो आधार को सब्सिडी और लाभों के लिए अनिवार्य बनाती थी। III. इसने आधार को बैंक खातों और मोबाइल नंबरों से अनिवार्य रूप से जोड़ने को बरकरार रखा। IV. इसने आयकर अधिनियम की धारा 139AA के अंतर्गत आधार को पैन से जोड़ने को बरकरार रखा।","optionsHi":["केवल तीन","सभी चार","केवल दो","केवल एक"],"explanationHi":"I और IV सही हैं। II गलत है: धारा 7 (सब्सिडी के लिए आधार) बरकरार रखी गई; निजी संस्थाओं द्वारा उपयोग वाली धारा 57 रद्द हुई। III गलत है: बैंक खातों और मोबाइल नंबरों से अनिवार्य जोड़ने को रद्द किया गया।"},
  {"id":"polity-fundamental-rights-209","question":"In Commissioner of Police v. Acharya Jagadishwarananda Avadhuta (2004), the Supreme Court considered the performance of the tandava dance in public processions by the Ananda Margis. It held that:","options":["The dance is protected by Article 26, since the Ananda Marga is a religious denomination","The dance in public is not an essential practice of the faith, so it is not protected","The dance is protected because a sect's own scriptures alone decide what is essential","The dance may be restricted only during a National Emergency proclaimed under Article 352"],"answer":1,"explanation":"Although Ananda Marga is a religious denomination, the Court held that tandava in public was a later addition and not an essential part of its religion, so a police ban on it in processions did not violate Articles 25 and 26. Being a denomination does not protect every practice.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पुलिस आयुक्त बनाम आचार्य जगदीश्वरानंद अवधूत (2004) में सर्वोच्च न्यायालय ने आनंद मार्गियों द्वारा सार्वजनिक जुलूसों में तांडव नृत्य करने पर विचार किया। उसने माना कि:","optionsHi":["नृत्य अनुच्छेद 26 से संरक्षित है, क्योंकि आनंद मार्ग धार्मिक संप्रदाय है","सार्वजनिक रूप से नृत्य आस्था की अनिवार्य प्रथा नहीं है, इसलिए वह संरक्षित नहीं है","नृत्य संरक्षित है क्योंकि कोई संप्रदाय अपने ही ग्रंथों से तय करता है कि क्या अनिवार्य है","नृत्य पर केवल अनुच्छेद 352 के अंतर्गत घोषित राष्ट्रीय आपातकाल में ही निर्बंधन लगाया जा सकता है"],"explanationHi":"यद्यपि आनंद मार्ग धार्मिक संप्रदाय है, न्यायालय ने माना कि सार्वजनिक रूप से तांडव बाद का जोड़ था और उसके धर्म का अनिवार्य भाग नहीं था, इसलिए जुलूसों में उस पर पुलिस प्रतिबंध ने अनुच्छेद 25 और 26 का उल्लंघन नहीं किया। संप्रदाय होने से हर प्रथा संरक्षित नहीं हो जाती।"},
  {"id":"polity-fundamental-rights-210","question":"In X v. Principal Secretary, Health and Family Welfare Department (2022), the Supreme Court read the Medical Termination of Pregnancy law and rules to hold that:","options":["Only married women may end a pregnancy between 20 and 24 weeks of gestation","A pregnancy beyond 12 weeks may be ended only with the husband's written consent","Unmarried women may end a pregnancy up to 24 weeks, just like married women","No pregnancy may be ended after 20 weeks except to save the life of the woman"],"answer":2,"explanation":"Holding that excluding unmarried women would violate Article 14 and their reproductive autonomy under Article 21, the Court read the 24-week category to cover all women, married or not.","difficulty":"hard","source":"UPSC Prelims","questionHi":"एक्स बनाम प्रधान सचिव, स्वास्थ्य एवं परिवार कल्याण विभाग (2022) में सर्वोच्च न्यायालय ने गर्भ का चिकित्सीय समापन कानून और नियमों को पढ़कर माना कि:","optionsHi":["गर्भ के 20 से 24 सप्ताह के बीच केवल विवाहित महिलाएँ गर्भ समाप्त करा सकती हैं","12 सप्ताह से अधिक का गर्भ केवल पति की लिखित सहमति से समाप्त हो सकता है","अविवाहित महिलाएँ भी विवाहित महिलाओं की तरह 24 सप्ताह तक गर्भ समाप्त करा सकती हैं","जीवन बचाने के सिवाय 20 सप्ताह के बाद कोई गर्भ समाप्त नहीं किया जा सकता"],"explanationHi":"यह मानते हुए कि अविवाहित महिलाओं को बाहर रखना अनुच्छेद 14 और अनुच्छेद 21 के अंतर्गत उनकी प्रजनन स्वायत्तता का उल्लंघन होगा, न्यायालय ने 24 सप्ताह की श्रेणी को सभी महिलाओं, विवाहित हों या नहीं, तक पढ़ा।"},
  {"id":"polity-fundamental-rights-211","question":"In Joginder Kumar v. State of U.P. (1994), the Supreme Court laid down that:","options":["Police may arrest on any complaint, provided the person is produced in court within 24 hours","No arrest may be made in a cognisable case without a warrant issued by a magistrate","Every arrest must be video-recorded and the recording kept for at least one year","Arrest needs justification beyond mere power, and a friend or relative must be informed"],"answer":3,"explanation":"The Court held that having the power to arrest is one thing and justifying its use another, and that an arrested person is entitled to have someone told of the arrest and where he is held. These safeguards were expanded in D. K. Basu (1997).","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"जोगिंदर कुमार बनाम उत्तर प्रदेश राज्य (1994) में सर्वोच्च न्यायालय ने निर्धारित किया कि:","optionsHi":["पुलिस किसी भी शिकायत पर गिरफ्तार कर सकती है, बशर्ते व्यक्ति को 24 घंटे में न्यायालय में पेश किया जाए","संज्ञेय मामले में मजिस्ट्रेट के वारंट के बिना कोई गिरफ्तारी नहीं हो सकती","प्रत्येक गिरफ्तारी की वीडियो रिकॉर्डिंग हो और कम से कम एक वर्ष रखी जाए","गिरफ्तारी के लिए केवल शक्ति से परे औचित्य चाहिए, और किसी मित्र या रिश्तेदार को सूचित किया जाना चाहिए"],"explanationHi":"न्यायालय ने माना कि गिरफ्तारी की शक्ति होना एक बात है और उसके प्रयोग को उचित ठहराना दूसरी, और गिरफ्तार व्यक्ति को यह अधिकार है कि किसी को गिरफ्तारी और उसके निरुद्ध स्थान की सूचना दी जाए। इन रक्षोपायों का विस्तार डी. के. बसु (1997) में हुआ।"},
  {"id":"polity-fundamental-rights-212","question":"In A. K. Roy v. Union of India (1982), the Supreme Court upheld the National Security Act, 1980. On the 44th Amendment's clause changing the composition of Advisory Boards, which the government had not brought into force, it held that:","options":["No mandamus could compel the government to bring the clause into force","The clause came into force on its own, since an Amendment cannot be left unnotified","The clause was void, since Advisory Boards lie outside Parliament's amending power","Detentions under the NSA were invalid until the clause was brought into force"],"answer":0,"explanation":"The 44th Amendment Act let the Central Government notify different dates for different provisions, and the majority held that no mandamus could issue to force it to notify the Advisory Board clause. That clause has still not been brought into force.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"ए. के. रॉय बनाम भारत संघ (1982) में सर्वोच्च न्यायालय ने राष्ट्रीय सुरक्षा अधिनियम, 1980 को बरकरार रखा। सलाहकार बोर्डों की संरचना बदलने वाले 44वें संशोधन के उस खंड पर, जिसे सरकार ने लागू नहीं किया था, उसने माना कि:","optionsHi":["खंड को लागू करने के लिए सरकार को बाध्य करने वाला कोई परमादेश जारी नहीं हो सकता","खंड अपने आप लागू हो गया, क्योंकि संशोधन को अधिसूचित किए बिना नहीं छोड़ा जा सकता","खंड शून्य था, क्योंकि सलाहकार बोर्ड संसद की संशोधन शक्ति से बाहर हैं","खंड लागू होने तक NSA के अंतर्गत निरोध अवैध थे"],"explanationHi":"44वें संशोधन अधिनियम ने केंद्र सरकार को विभिन्न उपबंधों के लिए अलग-अलग तिथियाँ अधिसूचित करने दीं, और बहुमत ने माना कि सलाहकार बोर्ड खंड को अधिसूचित करने के लिए सरकार को बाध्य करने वाला कोई परमादेश जारी नहीं हो सकता। वह खंड अब तक लागू नहीं हुआ है।"},
  {"id":"polity-fundamental-rights-213","question":"Assertion (A): A State may reserve a share of posts in its services for women, even though Article 16(2) forbids discrimination in public employment on the ground of sex. Reason (R): In Government of Andhra Pradesh v. P. B. Vijayakumar (1995), the Supreme Court held that Article 15(3) permits special provisions for women in State employment as well.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Vijayakumar held that Article 16 must be read with Article 15(3), so special provisions for women in State posts are valid; Article 16(2) bars discrimination on the ground only of sex, not measures in favour of women. R therefore explains A.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): कोई राज्य अपनी सेवाओं में महिलाओं के लिए पदों का एक हिस्सा आरक्षित कर सकता है, यद्यपि अनुच्छेद 16(2) लोक नियोजन में लिंग के आधार पर विभेद को वर्जित करता है। कारण (R): आंध्र प्रदेश सरकार बनाम पी. बी. विजयकुमार (1995) में सर्वोच्च न्यायालय ने माना कि अनुच्छेद 15(3) राज्य नियोजन में भी महिलाओं के लिए विशेष उपबंधों की अनुमति देता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"विजयकुमार ने माना कि अनुच्छेद 16 को अनुच्छेद 15(3) के साथ पढ़ा जाना चाहिए, इसलिए राज्य के पदों में महिलाओं के लिए विशेष उपबंध वैध हैं; अनुच्छेद 16(2) केवल लिंग के आधार पर विभेद को वर्जित करता है, महिलाओं के पक्ष के उपायों को नहीं। इसलिए R, A की व्याख्या करता है।"},
  {"id":"polity-fundamental-rights-214","question":"In Khoday Distilleries v. State of Karnataka (1995), the Supreme Court held about trade in potable liquor that:","options":["It is a trade like any other, protected by Article 19(1)(g) subject to Article 19(6)","There is no Fundamental Right to trade in it, and the State may ban or monopolise it","Only Parliament can regulate it, since alcohol is a Union List subject in Schedule VII","It can be restricted only on the grounds of public order listed in Article 19(2)"],"answer":1,"explanation":"The Court held that trade in potable liquor is res extra commercium, so there is no Fundamental Right to carry it on; the State may prohibit it or allow it only through licences or a State monopoly. Intoxicating liquor is a State List subject.","difficulty":"hard","source":"UPSC Prelims","questionHi":"खोदे डिस्टिलरीज बनाम कर्नाटक राज्य (1995) में सर्वोच्च न्यायालय ने पेय शराब के व्यापार के बारे में माना कि:","optionsHi":["यह अन्य व्यापारों जैसा ही व्यापार है, जो अनुच्छेद 19(1)(g) द्वारा संरक्षित है, अनुच्छेद 19(6) के अधीन","इसमें व्यापार का कोई मौलिक अधिकार नहीं है, और राज्य इस पर प्रतिबंध लगा सकता है या एकाधिकार रख सकता है","केवल संसद इसे विनियमित कर सकती है, क्योंकि शराब सातवीं अनुसूची में संघ सूची का विषय है","इसे केवल अनुच्छेद 19(2) में सूचीबद्ध लोक व्यवस्था के आधार पर निर्बंधित किया जा सकता है"],"explanationHi":"न्यायालय ने माना कि पेय शराब का व्यापार वाणिज्य से परे (res extra commercium) है, इसलिए उसे करने का कोई मौलिक अधिकार नहीं है; राज्य उस पर प्रतिबंध लगा सकता है या उसे केवल लाइसेंस या राज्य एकाधिकार के माध्यम से अनुमत कर सकता है। मादक शराब राज्य सूची का विषय है।"},
  {"id":"polity-fundamental-rights-215","question":"In S. P. Mittal v. Union of India (1983), on the Auroville (Emergency Provisions) Act, 1980, which took over the management of Auroville from the Sri Aurobindo Society, the Supreme Court held that the Society:","options":["Was a religious denomination whose management could not be taken over by any law","Was a linguistic minority entitled to protection under Article 29(1) against takeover","Was not a religious denomination, so it could not claim the protection of Article 26","Was a minority educational institution protected by Article 30 against any takeover"],"answer":2,"explanation":"The majority held that Sri Aurobindo's teachings are a philosophy, not a religion, so the Society was not a religious denomination and could not invoke Article 26; the takeover of management was upheld.","difficulty":"hard","source":"UPSC Prelims","questionHi":"एस. पी. मित्तल बनाम भारत संघ (1983) में, ऑरोविल (आपातकालीन उपबंध) अधिनियम, 1980 पर, जिसने श्री अरविंद सोसायटी से ऑरोविल का प्रबंध अपने हाथ में लिया, सर्वोच्च न्यायालय ने माना कि सोसायटी:","optionsHi":["धार्मिक संप्रदाय थी जिसका प्रबंध कोई कानून नहीं ले सकता","भाषायी अल्पसंख्यक थी जिसे अधिग्रहण के विरुद्ध अनुच्छेद 29(1) का संरक्षण प्राप्त था","धार्मिक संप्रदाय नहीं थी, इसलिए वह अनुच्छेद 26 के संरक्षण का दावा नहीं कर सकती थी","अल्पसंख्यक शिक्षा संस्था थी जिसे अनुच्छेद 30 किसी भी अधिग्रहण से संरक्षित करता है"],"explanationHi":"बहुमत ने माना कि श्री अरविंद की शिक्षाएँ दर्शन हैं, धर्म नहीं, इसलिए सोसायटी धार्मिक संप्रदाय नहीं थी और अनुच्छेद 26 का सहारा नहीं ले सकती थी; प्रबंध के अधिग्रहण को बरकरार रखा गया।"},
  {"id":"polity-fundamental-rights-216","question":"Consider these statements: 1. Article 31B protects only laws placed in the Ninth Schedule. 2. Article 31C, as it now stands, protects a law giving effect to Article 39(b) or (c) from challenge under Articles 14 and 19. 3. Article 31A saves laws for the acquisition of estates from challenge under Articles 14 and 19. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":3,"explanation":"Article 31B shields Ninth Schedule laws from challenge on any Fundamental Right (subject to the basic structure, per Coelho); Article 31A saves five kinds of laws, starting with acquisition of estates, from Articles 14 and 19; and Article 31C saves laws for Article 39(b) and (c) from Articles 14 and 19.","difficulty":"hard","source":"UPSC Prelims","questionHi":"इन कथनों पर विचार कीजिए: 1. अनुच्छेद 31B केवल नौवीं अनुसूची में रखे गए कानूनों की रक्षा करता है। 2. अनुच्छेद 31C, जैसा अब है, अनुच्छेद 39(b) या (c) को प्रभावी बनाने वाले कानून को अनुच्छेद 14 और 19 के अंतर्गत चुनौती से बचाता है। 3. अनुच्छेद 31A संपदाओं के अर्जन के कानूनों को अनुच्छेद 14 और 19 के अंतर्गत चुनौती से बचाता है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"अनुच्छेद 31B नौवीं अनुसूची के कानूनों को किसी भी मौलिक अधिकार के आधार पर चुनौती से बचाता है (कोएलो के अनुसार मूल ढाँचे के अधीन); अनुच्छेद 31A संपदाओं के अर्जन से आरंभ होने वाले पाँच प्रकार के कानूनों को अनुच्छेद 14 और 19 से बचाता है; और अनुच्छेद 31C अनुच्छेद 39(b) और (c) के कानूनों को अनुच्छेद 14 और 19 से बचाता है।"},
  {"id":"polity-fundamental-rights-217","question":"In Indian Express Newspapers v. Union of India (1985), on import duty levied on newsprint, the Supreme Court held that:","options":["The press is wholly immune from taxation, since any tax on it burdens free speech","The press can be taxed, but a levy that cripples circulation can be struck down","Taxes on the press can be tested only under Article 265 and never under Article 19","A newsprint duty is valid only if the Press Council of India approves it in advance"],"answer":1,"explanation":"The Court held that newspapers are not immune from ordinary taxation, but an excessive tax that curtails circulation can be challenged under Article 19(1)(a); it directed the government to re-examine the levy.","difficulty":"hard","source":"UPSC Prelims","questionHi":"इंडियन एक्सप्रेस न्यूजपेपर्स बनाम भारत संघ (1985) में, जो न्यूजप्रिंट पर लगाए गए आयात शुल्क से संबंधित था, सर्वोच्च न्यायालय ने माना कि:","optionsHi":["प्रेस कराधान से पूरी तरह मुक्त है, क्योंकि उस पर कोई भी कर वाक्-स्वतंत्रता पर बोझ है","प्रेस पर कर लगाया जा सकता है, परंतु प्रसार को पंगु करने वाला उद्ग्रहण रद्द किया जा सकता है","प्रेस पर करों की जाँच केवल अनुच्छेद 265 के अंतर्गत हो सकती है, अनुच्छेद 19 के अंतर्गत कभी नहीं","न्यूजप्रिंट शुल्क तभी वैध है जब भारतीय प्रेस परिषद उसे पहले से अनुमोदित करे"],"explanationHi":"न्यायालय ने माना कि समाचार पत्र सामान्य कराधान से मुक्त नहीं हैं, परंतु प्रसार को घटाने वाले अत्यधिक कर को अनुच्छेद 19(1)(a) के अंतर्गत चुनौती दी जा सकती है; उसने सरकार को उद्ग्रहण पर पुनर्विचार का निर्देश दिया।"},
  {"id":"polity-fundamental-rights-218","question":"In Ramana Dayaram Shetty v. International Airport Authority of India (1979), the Authority accepted a tender from a person who did not meet its own condition of being a registered second-class hotelier. The Supreme Court held that:","options":["The government may contract with anyone it likes, since its contracts lie outside Part III","The tender was valid, because the Authority is not ‘State’ within Article 12","A public authority cannot arbitrarily depart from the standards it has itself laid down","Only the Comptroller and Auditor General can review the award of a public contract"],"answer":2,"explanation":"The Court held the Authority to be an instrumentality of the State and said that even in awarding contracts it must act fairly and keep to the eligibility standards it has set, or the action is arbitrary under Article 14. On the facts it did not set aside the contract.","difficulty":"hard","source":"UPSC Prelims","questionHi":"रमणा दयाराम शेट्टी बनाम अंतर्राष्ट्रीय विमानपत्तन प्राधिकरण (1979) में प्राधिकरण ने ऐसे व्यक्ति की निविदा स्वीकार कर ली जो उसकी अपनी शर्त, पंजीकृत द्वितीय श्रेणी होटलवाला होना, पूरी नहीं करता था। सर्वोच्च न्यायालय ने माना कि:","optionsHi":["सरकार जिससे चाहे संविदा कर सकती है, क्योंकि उसकी संविदाएँ भाग III से बाहर हैं","निविदा वैध थी, क्योंकि प्राधिकरण अनुच्छेद 12 के अर्थ में ‘राज्य’ नहीं है","कोई लोक प्राधिकारी उन मानकों से मनमाने ढंग से हट नहीं सकता जो उसने स्वयं निर्धारित किए हैं","लोक संविदा के पुरस्कार की समीक्षा केवल भारत का नियंत्रक और महालेखा परीक्षक कर सकता है"],"explanationHi":"न्यायालय ने प्राधिकरण को राज्य का साधन माना और कहा कि संविदाएँ देने में भी उसे निष्पक्षता से कार्य करना और अपने निर्धारित पात्रता मानकों का पालन करना होगा, अन्यथा कार्रवाई अनुच्छेद 14 के अंतर्गत मनमानी है। तथ्यों पर उसने संविदा रद्द नहीं की।"},
  {"id":"polity-fundamental-rights-219","question":"A person is detained under a preventive detention law. Under Article 22(5) and the rule in Harikisan v. State of Maharashtra (1962), which of these will make the detention invalid?","options":["The grounds were served only in English, which the detenu could not read or understand","Some facts were withheld because the authority found their disclosure against public interest","The detenu was not allowed to be represented by a lawyer before the Advisory Board","The detenu was not produced before a magistrate within 24 hours of the detention"],"answer":0,"explanation":"Article 22(5) requires the grounds to be communicated so the detenu can make an effective representation, and Harikisan held that grounds in a language he does not understand are not communicated. Withholding facts is allowed by Article 22(6), and Article 22(3) excludes preventive detenus from the lawyer and 24-hour safeguards.","difficulty":"hard","source":"UPSC Prelims","questionHi":"किसी व्यक्ति को निवारक निरोध कानून के अंतर्गत निरुद्ध किया जाता है। अनुच्छेद 22(5) और हरिकिसन बनाम महाराष्ट्र राज्य (1962) के नियम के अंतर्गत इनमें से कौन-सी बात निरोध को अवैध बनाएगी?","optionsHi":["आधार केवल अंग्रेजी में दिए गए, जिसे निरुद्ध व्यक्ति पढ़ या समझ नहीं सकता था","कुछ तथ्य रोके गए क्योंकि प्राधिकारी ने उनके प्रकटीकरण को लोक हित के विरुद्ध पाया","निरुद्ध व्यक्ति को सलाहकार बोर्ड के समक्ष वकील द्वारा प्रतिनिधित्व की अनुमति नहीं दी गई","निरुद्ध व्यक्ति को निरोध के 24 घंटे के भीतर मजिस्ट्रेट के समक्ष पेश नहीं किया गया"],"explanationHi":"अनुच्छेद 22(5) अपेक्षा करता है कि आधार सूचित किए जाएँ ताकि निरुद्ध व्यक्ति प्रभावी अभ्यावेदन दे सके, और हरिकिसन ने माना कि जिस भाषा को वह नहीं समझता उसमें दिए गए आधार सूचित नहीं माने जाते। तथ्य रोकना अनुच्छेद 22(6) से अनुमत है, और अनुच्छेद 22(3) निवारक निरुद्धों को वकील और 24 घंटे के रक्षोपायों से बाहर रखता है।"},
  {"id":"polity-fundamental-rights-220","question":"In Arnesh Kumar v. State of Bihar (2014), the Supreme Court gave directions to prevent needless arrests. They apply mainly to offences punishable with imprisonment of:","options":["Up to three years, and require a magistrate's warrant for every arrest","Up to seven years, and require the police to record reasons for an arrest","More than ten years, and require a Superintendent to approve the arrest","Any term, but only for offences under the dowry and domestic violence laws"],"answer":1,"explanation":"For offences punishable with up to seven years, police must be satisfied of the need to arrest under Section 41 CrPC and record reasons using a checklist, and magistrates must not authorise detention mechanically. The case arose under Section 498A IPC, but the directions are general.","difficulty":"moderate","source":"UPSC Prelims · State PSCs","questionHi":"अर्नेश कुमार बनाम बिहार राज्य (2014) में सर्वोच्च न्यायालय ने अनावश्यक गिरफ्तारियाँ रोकने के निर्देश दिए। वे मुख्यतः किस कारावास से दंडनीय अपराधों पर लागू होते हैं?","optionsHi":["तीन वर्ष तक, और हर गिरफ्तारी के लिए मजिस्ट्रेट का वारंट आवश्यक","सात वर्ष तक, और पुलिस को गिरफ्तारी के कारण दर्ज करने होंगे","दस वर्ष से अधिक, और गिरफ्तारी के लिए अधीक्षक का अनुमोदन आवश्यक","कोई भी अवधि, परंतु केवल दहेज और घरेलू हिंसा कानूनों के अपराधों के लिए"],"explanationHi":"सात वर्ष तक दंडनीय अपराधों में पुलिस को दंड प्रक्रिया संहिता की धारा 41 के अंतर्गत गिरफ्तारी की आवश्यकता से संतुष्ट होना और जाँच-सूची से कारण दर्ज करना होगा, और मजिस्ट्रेट यांत्रिक रूप से निरोध की अनुमति न दें। मामला भारतीय दंड संहिता की धारा 498A से उत्पन्न हुआ, पर निर्देश सामान्य हैं।"},
  {"id":"polity-fundamental-rights-221","question":"In Mr X v. Hospital Z (1998), a hospital disclosed to a man's fiancée that he was HIV-positive, and the marriage was called off. The Supreme Court held that:","options":["The disclosure violated his right to privacy, so the hospital had to pay damages","Doctors may never disclose a patient's condition to anyone without written consent","The disclosure was justified to protect the health of the woman he was to marry","Medical records are State records, so privacy claims against hospitals cannot lie"],"answer":2,"explanation":"The Court held that the right to privacy is not absolute; where disclosure is needed to protect another person's right to life and health, here the intended wife's, the doctor's disclosure is not wrongful.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मिस्टर एक्स बनाम हॉस्पिटल जेड (1998) में एक अस्पताल ने एक पुरुष की मंगेतर को बताया कि वह एचआईवी पॉजिटिव है, और विवाह टूट गया। सर्वोच्च न्यायालय ने माना कि:","optionsHi":["प्रकटीकरण ने उसके निजता के अधिकार का उल्लंघन किया, इसलिए अस्पताल को क्षतिपूर्ति देनी थी","चिकित्सक लिखित सहमति के बिना किसी को भी रोगी की स्थिति कभी नहीं बता सकते","जिस महिला से उसका विवाह होना था उसके स्वास्थ्य की रक्षा के लिए प्रकटीकरण उचित था","चिकित्सा अभिलेख राज्य के अभिलेख हैं, इसलिए अस्पतालों के विरुद्ध निजता के दावे नहीं हो सकते"],"explanationHi":"न्यायालय ने माना कि निजता का अधिकार निरपेक्ष नहीं है; जहाँ किसी अन्य व्यक्ति, यहाँ भावी पत्नी, के जीवन और स्वास्थ्य के अधिकार की रक्षा के लिए प्रकटीकरण आवश्यक हो, वहाँ चिकित्सक का प्रकटीकरण अनुचित नहीं है।"},
  {"id":"polity-fundamental-rights-222","question":"In K. S. Puttaswamy (2017), the plurality laid down tests that any State intrusion into privacy must meet. Which of these is NOT one of them?","options":["There must be a law that authorises the intrusion","The law must pursue a legitimate aim of the State","The means must be proportionate to the object sought","A judicial warrant must be obtained in every case"],"answer":3,"explanation":"The plurality required legality (a law), a legitimate State aim and proportionality between the object and the means adopted; Justice Kaul added procedural guarantees against abuse. A prior judicial warrant in every case was not one of the tests.","difficulty":"hard","source":"UPSC Prelims","questionHi":"के. एस. पुट्टस्वामी (2017) में बहुमत की राय (plurality) ने वे कसौटियाँ निर्धारित कीं जिन्हें निजता में राज्य के किसी भी हस्तक्षेप को पूरा करना होगा। इनमें से कौन-सी उनमें नहीं है?","optionsHi":["हस्तक्षेप को प्राधिकृत करने वाला कानून होना चाहिए","कानून को राज्य के वैध उद्देश्य की पूर्ति करनी चाहिए","साधन अपेक्षित उद्देश्य के अनुपात में होने चाहिए","प्रत्येक मामले में न्यायिक वारंट प्राप्त करना आवश्यक है"],"explanationHi":"बहुमत राय ने वैधता (कानून), राज्य का वैध उद्देश्य और उद्देश्य तथा अपनाए गए साधनों के बीच आनुपातिकता की अपेक्षा की; न्यायमूर्ति कौल ने दुरुपयोग के विरुद्ध प्रक्रियात्मक रक्षोपाय जोड़े। प्रत्येक मामले में पूर्व न्यायिक वारंट उन कसौटियों में नहीं था।"},
];

export default questions;
